// phrases-data.js — Prepositional-phrase MCQ bank for the Phrases tab.
// 500 questions (verb=176, adj=125, noun=100, phrase=99). Generated by /tmp/build-phrases.js; quality fixes by /tmp/fix-phrases.js.
// Schema: { id, cat:'verb'|'adj'|'noun'|'phrase', q (one ___), options[4], correct (index), phrase, vi, explanation }
const PREPOSITION_QUESTIONS = [
  { id: 'pp-1', cat: 'verb', q: 'She always focuses ___ her studies before the final exams.', options: ['at', 'in', 'on', 'for'], correct: 2, phrase: 'focus on', vi: 'tập trung vào — focus on (chú ý, dồn sức vào)', explanation: 'Động từ "focus" luôn đi với "on": focus on something = tập trung vào việc gì. (at/in/for không kết hợp với focus.)' },
  { id: 'pp-2', cat: 'verb', q: 'Whether we go camping will depend ___ the weather this weekend.', options: ['in', 'on', 'to', 'of'], correct: 1, phrase: 'depend on', vi: 'phụ thuộc vào — depend on (dựa vào, tùy thuộc)', explanation: '"Depend" luôn đi với "on" (hoặc upon): depend on something = phụ thuộc vào. (in/of/to không dùng với depend.)' },
  { id: 'pp-3', cat: 'verb', q: 'Many children still strongly believe ___ Santa Claus at Christmas.', options: ['in', 'at', 'on', 'of'], correct: 0, phrase: 'believe in', vi: 'tin vào — believe in (tin tưởng vào sự tồn tại/giá trị)', explanation: '"Believe in" = tin vào sự tồn tại hoặc giá trị của ai/cái gì. (on/at/of không kết hợp với believe.)' },
  { id: 'pp-4', cat: 'verb', q: 'He wanted to apologize ___ being so rude to his teacher.', options: ['to', 'of', 'for', 'about'], correct: 2, phrase: 'apologize for', vi: 'xin lỗi vì — apologize for (xin lỗi về điều gì)', explanation: '"Apologize for" = xin lỗi vì/về điều gì. Ta dùng apologize TO ai đó nhưng apologize FOR điều gì. (about/of không đúng ở đây.)' },
  { id: 'pp-5', cat: 'verb', q: 'I love to listen ___ classical music while I am working.', options: ['on', 'at', 'to', 'for'], correct: 2, phrase: 'listen to', vi: 'nghe — listen to (lắng nghe ai/cái gì)', explanation: 'Động từ "listen" luôn đi với "to": listen to something = lắng nghe cái gì. (at/on/for không dùng với listen.)' },
  { id: 'pp-6', cat: 'verb', q: 'Please look ___ this photo and tell me what you see.', options: ['at', 'to', 'in', 'on'], correct: 0, phrase: 'look at', vi: 'nhìn vào — look at (nhìn, ngắm)', explanation: '"Look at" = nhìn vào, hướng mắt vào cái gì. (on/in/to không kết hợp với look theo nghĩa này.)' },
  { id: 'pp-7', cat: 'verb', q: 'She spent all morning looking ___ her missing car keys.', options: ['for', 'at', 'into', 'after'], correct: 0, phrase: 'look for', vi: 'tìm kiếm — look for (tìm cái gì đó)', explanation: '"Look for" = tìm kiếm cái gì. (look at = nhìn, look after = chăm sóc, look into = điều tra — đều khác nghĩa.)' },
  { id: 'pp-8', cat: 'verb', q: 'We had to wait ___ the bus for almost half an hour.', options: ['to', 'at', 'for', 'on'], correct: 2, phrase: 'wait for', vi: 'chờ đợi — wait for (đợi ai/cái gì)', explanation: '"Wait for" = đợi ai/cái gì. (on/at/to không kết hợp với wait theo nghĩa chờ đợi.)' },
  { id: 'pp-9', cat: 'verb', q: 'They sat in the café and talked ___ their holiday plans.', options: ['about', 'with', 'of', 'on'], correct: 0, phrase: 'talk about', vi: 'nói về — talk about (bàn luận về chủ đề gì)', explanation: '"Talk about" = nói/bàn về chủ đề gì. Ta talk WITH/TO người, nhưng talk ABOUT chủ đề. (on/of không tự nhiên ở đây.)' },
  { id: 'pp-10', cat: 'verb', q: 'I need some time to think ___ your offer before deciding.', options: ['on', 'about', 'at', 'of'], correct: 1, phrase: 'think about', vi: 'suy nghĩ về — think about (cân nhắc, ngẫm về)', explanation: '"Think about" = suy nghĩ kỹ, cân nhắc về điều gì. (on/at không dùng; think of thường chỉ nhớ ra/có ý kiến, ít hợp với việc cân nhắc một đề nghị.)' },
  { id: 'pp-11', cat: 'verb', q: 'I completely agree ___ you about the new company policy.', options: ['for', 'on', 'with', 'to'], correct: 2, phrase: 'agree with', vi: 'đồng ý với (ai) — agree with (cùng quan điểm với người nào)', explanation: 'Khi đồng ý với MỘT NGƯỜI, ta dùng "agree with somebody". ("on" dùng cho một quyết định, "to" dùng cho lời đề nghị, "for" không kết hợp với agree.)' },
  { id: 'pp-12', cat: 'verb', q: 'After hours of talking, they finally agreed ___ a final price.', options: ['at', 'with', 'of', 'on'], correct: 3, phrase: 'agree on', vi: 'thống nhất về (vấn đề) — agree on (cùng quyết định về điều gì)', explanation: '"Agree on something" nghĩa là cùng thống nhất về một vấn đề hay quyết định. ("with" dùng cho người, "to" dùng cho đề nghị, "of" không dùng với agree.)' },
  { id: 'pp-13', cat: 'verb', q: 'She decided to apply ___ a job at the local hospital.', options: ['on', 'for', 'with', 'to'], correct: 1, phrase: 'apply for', vi: 'nộp đơn xin (việc, học bổng) — apply for (xin việc/vị trí gì)', explanation: '"Apply for something" nghĩa là nộp đơn xin việc, học bổng hay chỗ làm. ("to" dùng khi nộp đơn TỚI một nơi, "on/with" không kết hợp với apply.)' },
  { id: 'pp-14', cat: 'verb', q: 'Her strict parents did not approve ___ her new boyfriend.', options: ['of', 'with', 'on', 'for'], correct: 0, phrase: 'approve of', vi: 'tán thành, chấp thuận — approve of (đồng tình với điều gì)', explanation: '"Approve of something/somebody" nghĩa là tán thành, chấp nhận điều gì. ("with/for/on" không kết hợp với approve theo nghĩa này.)' },
  { id: 'pp-15', cat: 'verb', q: 'My brother loves to argue ___ everyone about politics.', options: ['with', 'at', 'for', 'to'], correct: 0, phrase: 'argue with', vi: 'tranh cãi với (ai) — argue with (cãi nhau với người nào)', explanation: '"Argue with somebody" nghĩa là tranh cãi với một người. ("to/at/for" không dùng để chỉ người mà ta tranh cãi cùng.)' },
  { id: 'pp-16', cat: 'verb', q: 'We finally arrived ___ the airport just before midnight.', options: ['on', 'in', 'at', 'to'], correct: 2, phrase: 'arrive at', vi: 'đến (một nơi nhỏ/cụ thể) — arrive at (tới một địa điểm cụ thể)', explanation: 'Với một địa điểm cụ thể như sân bay, ta dùng "arrive at". ("to" không bao giờ đi với arrive, "in" dùng cho thành phố/nước, "on" không hợp.)' },
  { id: 'pp-17', cat: 'verb', q: 'If you are lost, don\'t be afraid to ask ___ help.', options: ['of', 'about', 'for', 'to'], correct: 2, phrase: 'ask for', vi: 'yêu cầu, xin (điều gì) — ask for (đề nghị được giúp/cho gì)', explanation: '"Ask for something" nghĩa là yêu cầu hoặc xin điều gì. ("to" đi với động từ nguyên thể, "of/about" không hợp ở đây.)' },
  { id: 'pp-18', cat: 'verb', q: 'This beautiful old house has belonged ___ my family for years.', options: ['with', 'of', 'to', 'in'], correct: 2, phrase: 'belong to', vi: 'thuộc về (ai/cái gì) — belong to (là sở hữu của)', explanation: '"Belong to somebody" nghĩa là thuộc quyền sở hữu của ai. ("with" chỉ vị trí cất giữ, "of/in" không kết hợp với belong.)' },
  { id: 'pp-19', cat: 'verb', q: 'Many students will benefit ___ the new online learning program.', options: ['from', 'of', 'with', 'by'], correct: 0, phrase: 'benefit from', vi: 'hưởng lợi từ — benefit from (được lợi nhờ điều gì)', explanation: '"Benefit from something" nghĩa là nhận được lợi ích từ điều gì. ("of/with" không hợp, "by" dùng cho phương tiện chứ không phải nguồn lợi.)' },
  { id: 'pp-20', cat: 'verb', q: 'The manager blamed the workers ___ the delay in production.', options: ['on', 'with', 'for', 'of'], correct: 2, phrase: 'blame for', vi: 'đổ lỗi cho (ai) về (việc gì) — blame for (quy trách nhiệm về điều gì)', explanation: '"Blame somebody for something" nghĩa là đổ lỗi cho ai về điều gì. ("on" dùng trong "blame something on somebody", còn "of/with" không hợp.)' },
  { id: 'pp-21', cat: 'verb', q: 'She really cares ___ the environment and recycles everything at home.', options: ['about', 'for', 'of', 'with'], correct: 0, phrase: 'care about', vi: 'quan tâm đến — care about (để ý, thấy quan trọng)', explanation: 'Động từ "care" đi với "about" khi nói quan tâm/thấy quan trọng: care about something. ("care for" nghĩa là chăm sóc; of/with không dùng ở đây.)' },
  { id: 'pp-22', cat: 'verb', q: 'The customers often complain ___ the slow service at that restaurant.', options: ['about', 'to', 'on', 'for'], correct: 0, phrase: 'complain about', vi: 'phàn nàn về — complain about (kêu ca, than phiền)', explanation: 'Động từ "complain" đi với "about" để chỉ nội dung phàn nàn: complain about something. (on/for không kết hợp; "to" dùng cho người nghe, không phải vấn đề.)' },
  { id: 'pp-23', cat: 'verb', q: 'It is hard to concentrate ___ my homework when the TV is loud.', options: ['in', 'on', 'for', 'at'], correct: 1, phrase: 'concentrate on', vi: 'tập trung vào — concentrate on (dồn sự chú ý vào)', explanation: 'Động từ "concentrate" luôn đi với "on": concentrate on something = tập trung vào việc gì. (in/at/for không dùng với concentrate.)' },
  { id: 'pp-24', cat: 'verb', q: 'I want to congratulate you ___ passing your final exam this week.', options: ['on', 'for', 'with', 'about'], correct: 0, phrase: 'congratulate on', vi: 'chúc mừng về — congratulate on (chúc mừng ai về điều gì)', explanation: 'Cấu trúc "congratulate somebody on something" = chúc mừng ai về điều gì. (for/about/with không dùng sau congratulate.)' },
  { id: 'pp-25', cat: 'verb', q: 'A water molecule consists ___ two hydrogen atoms and one oxygen atom.', options: ['in', 'with', 'of', 'from'], correct: 2, phrase: 'consist of', vi: 'bao gồm — consist of (được tạo thành từ, gồm có)', explanation: 'Động từ "consist" luôn đi với "of": consist of = bao gồm, được tạo thành từ. (from/in/with không kết hợp với consist.)' },
  { id: 'pp-26', cat: 'verb', q: 'Eating too much sugar can contribute ___ several serious health problems.', options: ['for', 'to', 'with', 'into'], correct: 1, phrase: 'contribute to', vi: 'góp phần vào — contribute to (đóng góp, là nguyên nhân)', explanation: 'Động từ "contribute" đi với "to": contribute to something = góp phần vào việc gì. (for/into/with không dùng với contribute.)' },
  { id: 'pp-27', cat: 'verb', q: 'Many students struggle to cope ___ the pressure of difficult exams.', options: ['for', 'to', 'on', 'with'], correct: 3, phrase: 'cope with', vi: 'đối phó với — cope with (xoay xở, chịu đựng được)', explanation: 'Động từ "cope" luôn đi với "with": cope with something = đối phó/xoay xở với việc gì. (to/on/for không kết hợp với cope.)' },
  { id: 'pp-28', cat: 'verb', q: 'You can always count ___ your true friends when times get tough.', options: ['to', 'on', 'at', 'in'], correct: 1, phrase: 'count on', vi: 'trông cậy vào — count on (tin tưởng, dựa vào)', explanation: 'Cụm "count on somebody" = trông cậy/dựa vào ai. (in/to/at không dùng theo nghĩa tin tưởng này.)' },
  { id: 'pp-29', cat: 'verb', q: 'The manager knows exactly how to deal ___ angry customers calmly.', options: ['with', 'for', 'about', 'in'], correct: 0, phrase: 'deal with', vi: 'giải quyết, xử lý — deal with (đối phó, làm việc với)', explanation: 'Động từ "deal" đi với "with": deal with something/someone = giải quyết, xử lý. (in/about/for không dùng theo nghĩa này.)' },
  { id: 'pp-30', cat: 'verb', q: 'After hours of discussion, they finally decided ___ a new company logo.', options: ['to', 'about', 'for', 'on'], correct: 3, phrase: 'decide on', vi: 'quyết định chọn — decide on (chọn lựa dứt khoát)', explanation: 'Cụm "decide on something" = quyết định chọn cái gì sau khi cân nhắc. (for/about không kết hợp; "to" chỉ đi trước động từ nguyên thể, không phải danh từ.)' },
  { id: 'pp-31', cat: 'verb', q: 'Many people in that region still die ___ hunger every winter.', options: ['of', 'by', 'with', 'from'], correct: 0, phrase: 'die of', vi: 'chết vì — die of (qua đời do bệnh tật, đói khát)', explanation: 'Động từ "die" đi với "of" khi nói về nguyên nhân bên trong như bệnh tật hay đói: die of hunger = chết vì đói. (from/with/by không phải cách kết hợp chuẩn ở đây.)' },
  { id: 'pp-32', cat: 'verb', q: 'His opinion clearly differs ___ mine on this important matter.', options: ['of', 'from', 'with', 'to'], correct: 1, phrase: 'differ from', vi: 'khác với — differ from (không giống, có sự khác biệt)', explanation: 'Động từ "differ" luôn đi với "from": differ from something = khác với cái gì. (to/with/of không kết hợp với differ theo nghĩa này.)' },
  { id: 'pp-33', cat: 'verb', q: 'I completely disagree ___ you about the new company policy.', options: ['from', 'to', 'on', 'with'], correct: 3, phrase: 'disagree with', vi: 'không đồng ý với — disagree with (bất đồng quan điểm)', explanation: 'Động từ "disagree" đi với "with" khi nói về người: disagree with somebody = không đồng ý với ai. (to/on/from không dùng với người ở đây.)' },
  { id: 'pp-34', cat: 'verb', q: 'As a child she always dreamed ___ becoming a famous singer.', options: ['of', 'to', 'at', 'in'], correct: 0, phrase: 'dream of', vi: 'mơ ước về — dream of (khao khát, mong muốn)', explanation: 'Động từ "dream" đi với "of" khi nói về điều mong ước: dream of something = mơ ước về điều gì. (at/in/to không kết hợp với dream.)' },
  { id: 'pp-35', cat: 'verb', q: 'The two prisoners managed to escape ___ the old jail last night.', options: ['to', 'of', 'from', 'with'], correct: 2, phrase: 'escape from', vi: 'trốn thoát khỏi — escape from (thoát ra, chạy thoát)', explanation: 'Động từ "escape" đi với "from" khi chỉ nơi thoát ra: escape from prison = trốn khỏi nhà tù. (of/to/with không diễn tả việc thoát khỏi một nơi.)' },
  { id: 'pp-36', cat: 'verb', q: 'She could never forgive him ___ lying to her so often.', options: ['to', 'of', 'about', 'for'], correct: 3, phrase: 'forgive for', vi: 'tha thứ cho ai vì — forgive for (bỏ qua lỗi lầm)', explanation: 'Động từ "forgive" đi với "for" khi nói về lỗi: forgive somebody for something = tha thứ cho ai vì điều gì. (of/about/to không kết hợp với forgive ở đây.)' },
  { id: 'pp-37', cat: 'verb', q: 'Did you hear ___ the terrible accident that happened downtown yesterday?', options: ['about', 'on', 'from', 'of'], correct: 0, phrase: 'hear about', vi: 'nghe nói về — hear about (biết tin, nghe thông tin)', explanation: 'Động từ "hear" đi với "about" khi nói về tin tức, sự việc: hear about something = nghe về việc gì. (of/from/on mang nghĩa khác và không phù hợp ở đây.)' },
  { id: 'pp-38', cat: 'verb', q: 'After the long drought, the farmers are all hoping ___ rain.', options: ['at', 'for', 'on', 'to'], correct: 1, phrase: 'hope for', vi: 'hy vọng có — hope for (mong đợi điều gì xảy ra)', explanation: 'Động từ "hope" đi với "for" khi nói về điều mong đợi: hope for something = hy vọng có điều gì. (to/on/at không kết hợp với hope theo nghĩa này.)' },
  { id: 'pp-39', cat: 'verb', q: 'My manager always insists ___ checking every report before we send it.', options: ['in', 'on', 'for', 'at'], correct: 1, phrase: 'insist on', vi: 'khăng khăng đòi — insist on (yêu cầu, nhất quyết)', explanation: 'Động từ "insist" luôn đi với "on": insist on something = nhất quyết đòi điều gì. (in/at/for không kết hợp với insist.)' },
  { id: 'pp-40', cat: 'verb', q: 'Loud noise from the street can interfere ___ your ability to concentrate.', options: ['with', 'at', 'on', 'in'], correct: 0, phrase: 'interfere with', vi: 'cản trở, gây ảnh hưởng đến — interfere with (làm gián đoạn)', explanation: 'Động từ "interfere" đi với "with" khi nói về việc gây cản trở: interfere with something = ảnh hưởng đến việc gì. (in/on/at không diễn tả nghĩa cản trở này.)' },
  { id: 'pp-41', cat: 'verb', q: 'At the party, she introduced her new boyfriend ___ all of her friends.', options: ['with', 'to', 'at', 'for'], correct: 1, phrase: 'introduce to', vi: 'giới thiệu với — introduce to (làm quen ai đó với người khác)', explanation: 'Động từ "introduce" đi với "to": introduce somebody to somebody = giới thiệu ai với ai. (with/at/for không dùng sau introduce theo nghĩa này.)' },
  { id: 'pp-42', cat: 'verb', q: 'Many young people now choose to invest ___ stocks and cryptocurrency.', options: ['to', 'at', 'in', 'on'], correct: 2, phrase: 'invest in', vi: 'đầu tư vào — invest in (bỏ tiền vào việc gì để sinh lời)', explanation: 'Động từ "invest" luôn đi với "in": invest in something = đầu tư vào việc/thứ gì. (on/at/to không kết hợp với invest.)' },
  { id: 'pp-43', cat: 'verb', q: 'The other kids started to laugh ___ him when he fell over.', options: ['with', 'on', 'at', 'for'], correct: 2, phrase: 'laugh at', vi: 'cười nhạo, chế giễu — laugh at (cười nhạo ai/cái gì)', explanation: '"Laugh" đi với "at" để chỉ đối tượng bị cười: laugh at somebody = cười nhạo ai. (on/for/with không diễn đạt nghĩa chế giễu này.)' },
  { id: 'pp-44', cat: 'verb', q: 'Could you please look ___ my dog while I am away on holiday?', options: ['at', 'into', 'after', 'for'], correct: 2, phrase: 'look after', vi: 'chăm sóc, trông nom — look after (chăm sóc ai/cái gì)', explanation: 'Cụm "look after" nghĩa là chăm sóc, trông nom: look after somebody = chăm sóc ai. (at/for/into tạo nghĩa khác hẳn.)' },
  { id: 'pp-45', cat: 'verb', q: 'I am really looking forward ___ seeing you again next summer.', options: ['for', 'to', 'at', 'on'], correct: 1, phrase: 'look forward to', vi: 'mong chờ, trông đợi — look forward to (háo hức chờ đợi điều gì)', explanation: 'Cụm "look forward to" luôn theo sau bởi "to" rồi danh từ/V-ing: look forward to doing = mong được làm gì. (for/at/on đều sai.)' },
  { id: 'pp-46', cat: 'verb', q: 'Several neighbours strongly object ___ the noise from the new factory.', options: ['for', 'against', 'to', 'on'], correct: 2, phrase: 'object to', vi: 'phản đối — object to (không đồng ý với điều gì)', explanation: 'Động từ "object" đi với "to": object to something = phản đối điều gì. (against/on/for không kết hợp với object.)' },
  { id: 'pp-47', cat: 'verb', q: 'All students are encouraged to participate ___ the school\'s sports activities.', options: ['at', 'to', 'in', 'on'], correct: 2, phrase: 'participate in', vi: 'tham gia vào — participate in (góp mặt, dự phần vào việc gì)', explanation: 'Động từ "participate" đi với "in": participate in something = tham gia vào việc gì. (on/at/to không dùng sau participate.)' },
  { id: 'pp-48', cat: 'verb', q: 'My parents kindly offered to pay ___ my university tuition fees.', options: ['on', 'for', 'of', 'to'], correct: 1, phrase: 'pay for', vi: 'trả tiền cho — pay for (chi trả cho hàng hóa/dịch vụ)', explanation: 'Động từ "pay" đi với "for" trước thứ được mua: pay for something = trả tiền cho cái gì. (of/to/on không diễn đạt nghĩa này.)' },
  { id: 'pp-49', cat: 'verb', q: 'She spent the whole weekend preparing ___ her final maths exam.', options: ['with', 'to', 'for', 'on'], correct: 2, phrase: 'prepare for', vi: 'chuẩn bị cho — prepare for (sẵn sàng cho sự kiện sắp tới)', explanation: 'Động từ "prepare" đi với "for": prepare for something = chuẩn bị cho việc gì. (to/on/with không kết hợp với prepare theo nghĩa này.)' },
  { id: 'pp-50', cat: 'verb', q: 'The heavy rain prevented us ___ finishing the football match on time.', options: ['of', 'to', 'against', 'from'], correct: 3, phrase: 'prevent from', vi: 'ngăn cản khỏi — prevent from (cản trở ai làm điều gì)', explanation: 'Động từ "prevent" đi với "from": prevent somebody from doing = ngăn ai làm gì. (of/to/against không dùng sau prevent.)' },
  { id: 'pp-51', cat: 'verb', q: 'A thick coat will protect you ___ the cold winter wind outside.', options: ['at', 'for', 'by', 'from'], correct: 3, phrase: 'protect from', vi: 'bảo vệ khỏi — protect from (che chở, tránh khỏi)', explanation: 'Động từ "protect" đi với "from": protect somebody from something = bảo vệ ai khỏi điều gì. (for/at/by không dùng với protect theo nghĩa này.)' },
  { id: 'pp-52', cat: 'verb', q: 'He works two jobs to provide ___ his large family every month.', options: ['for', 'with', 'of', 'to'], correct: 0, phrase: 'provide for', vi: 'chu cấp cho — provide for (nuôi nấng, lo cho)', explanation: '"Provide for somebody" = chu cấp, lo cho ai đó. Dùng giới từ "for". (to/of/with không tạo nghĩa "nuôi nấng" này.)' },
  { id: 'pp-53', cat: 'verb', q: 'How did your parents react ___ the surprising news about your job?', options: ['in', 'at', 'on', 'to'], correct: 3, phrase: 'react to', vi: 'phản ứng với — react to (đáp lại, phản ứng)', explanation: 'Động từ "react" luôn đi với "to": react to something = phản ứng với điều gì. (at/in/on không kết hợp với react.)' },
  { id: 'pp-54', cat: 'verb', q: 'It took her several weeks to recover ___ the serious illness.', options: ['of', 'with', 'from', 'off'], correct: 2, phrase: 'recover from', vi: 'hồi phục sau — recover from (bình phục, khỏe lại)', explanation: '"Recover from" = hồi phục sau điều gì (bệnh tật, chấn thương). Dùng "from". (of/with/off không dùng với recover.)' },
  { id: 'pp-55', cat: 'verb', q: 'In your essay, please refer ___ the original report for clear evidence.', options: ['to', 'for', 'on', 'at'], correct: 0, phrase: 'refer to', vi: 'đề cập đến, tham khảo — refer to (nhắc tới, dẫn chiếu)', explanation: 'Động từ "refer" đi với "to": refer to something = đề cập, tham khảo điều gì. (at/on/for không kết hợp với refer.)' },
  { id: 'pp-56', cat: 'verb', q: 'You can always rely ___ your best friends in difficult times.', options: ['on', 'at', 'in', 'to'], correct: 0, phrase: 'rely on', vi: 'dựa vào, trông cậy — rely on (tin tưởng, nhờ cậy)', explanation: '"Rely on somebody/something" = dựa vào, trông cậy vào. Luôn dùng "on". (in/at/to không dùng với rely.)' },
  { id: 'pp-57', cat: 'verb', q: 'This old song always reminds me ___ my happy childhood days.', options: ['about', 'on', 'for', 'of'], correct: 3, phrase: 'remind of', vi: 'gợi nhớ về — remind of (làm nhớ tới)', explanation: '"Remind somebody of something" = gợi cho ai nhớ về điều gì. Dùng "of". (about/on/for không tạo nghĩa gợi nhớ này.)' },
  { id: 'pp-58', cat: 'verb', q: 'Please remember to reply ___ my email before the weekend ends.', options: ['at', 'to', 'for', 'on'], correct: 1, phrase: 'reply to', vi: 'trả lời, hồi đáp — reply to (đáp lại)', explanation: 'Động từ "reply" đi với "to": reply to something = trả lời, hồi đáp điều gì. (for/at/on không kết hợp với reply.)' },
  { id: 'pp-59', cat: 'verb', q: 'Careless driving can often result ___ very serious traffic accidents.', options: ['at', 'from', 'to', 'in'], correct: 3, phrase: 'result in', vi: 'dẫn đến, gây ra — result in (đưa đến kết quả)', explanation: '"Result in something" = dẫn đến, gây ra kết quả gì. Dùng "in". (to/from/at không dùng với result theo nghĩa này.)' },
  { id: 'pp-60', cat: 'verb', q: 'The rescue team continued to search ___ survivors after the strong earthquake.', options: ['of', 'for', 'at', 'on'], correct: 1, phrase: 'search for', vi: 'tìm kiếm — search for (lùng tìm, kiếm)', explanation: '"Search for something/somebody" = tìm kiếm ai/cái gì. Dùng "for". (of/at/on không kết hợp với search ở đây.)' },
  { id: 'pp-61', cat: 'verb', q: 'The angry coach shouted ___ the players for losing the match.', options: ['with', 'to', 'on', 'at'], correct: 3, phrase: 'shout at', vi: 'quát mắng, la mắng — shout at (hét vào ai đó cách giận dữ)', explanation: 'Khi tức giận và mắng ai, ta dùng "shout at": shout at somebody = quát mắng ai. (shout to chỉ là gọi to để ai nghe; on/with không kết hợp với shout.)' },
  { id: 'pp-62', cat: 'verb', q: 'The kind woman smiled ___ the little boy on the bus.', options: ['at', 'to', 'with', 'for'], correct: 0, phrase: 'smile at', vi: 'mỉm cười với — smile at (cười với ai đó)', explanation: 'Động từ "smile" đi với "at" khi cười với ai: smile at somebody = mỉm cười với ai. (to/with/for không dùng sau smile theo nghĩa này.)' },
  { id: 'pp-63', cat: 'verb', q: 'This famous doctor specializes ___ treating heart diseases at the hospital.', options: ['in', 'for', 'at', 'on'], correct: 0, phrase: 'specialize in', vi: 'chuyên về — specialize in (tập trung vào một lĩnh vực)', explanation: 'Động từ "specialize" luôn đi với "in": specialize in something = chuyên về việc gì. (on/at/for không kết hợp với specialize.)' },
  { id: 'pp-64', cat: 'verb', q: 'Everyone in the room stared ___ the strange painting on the wall.', options: ['on', 'at', 'to', 'into'], correct: 1, phrase: 'stare at', vi: 'nhìn chằm chằm vào — stare at (nhìn không chớp mắt)', explanation: 'Động từ "stare" đi với "at": stare at something = nhìn chằm chằm vào cái gì. (to/on/into không dùng sau stare.)' },
  { id: 'pp-65', cat: 'verb', q: 'Many new students struggle ___ math during their first year at university.', options: ['at', 'for', 'on', 'with'], correct: 3, phrase: 'struggle with', vi: 'chật vật với, vật lộn với — struggle with (gặp khó khăn với việc gì)', explanation: 'Động từ "struggle" đi với "with": struggle with something = vật lộn, chật vật với việc gì. (for/at/on không hợp với struggle theo nghĩa này.)' },
  { id: 'pp-66', cat: 'verb', q: 'My parents subscribe ___ a weekly magazine about gardening and cooking.', options: ['on', 'for', 'to', 'in'], correct: 2, phrase: 'subscribe to', vi: 'đăng ký (dài hạn) — subscribe to (mua dài hạn báo, kênh, dịch vụ)', explanation: 'Động từ "subscribe" đi với "to": subscribe to something = đăng ký nhận báo/kênh/dịch vụ. (for/in/on không kết hợp với subscribe.)' },
  { id: 'pp-67', cat: 'verb', q: 'After years of hard work, she finally succeeded ___ starting her own business.', options: ['in', 'at', 'with', 'on'], correct: 0, phrase: 'succeed in', vi: 'thành công trong việc — succeed in (đạt được điều mong muốn)', explanation: 'Động từ "succeed" đi với "in": succeed in doing something = thành công trong việc làm gì. (at/on/with không dùng sau succeed.)' },
  { id: 'pp-68', cat: 'verb', q: 'My grandfather has suffered ___ a serious back problem for many years.', options: ['of', 'by', 'from', 'with'], correct: 2, phrase: 'suffer from', vi: 'bị, mắc (bệnh, khó khăn) — suffer from (chịu đựng bệnh tật, vấn đề)', explanation: 'Khi nói về bệnh hay vấn đề kéo dài, ta dùng "suffer from": suffer from an illness = mắc bệnh gì. (with/of/by không dùng theo nghĩa này.)' },
  { id: 'pp-69', cat: 'verb', q: 'I would like to thank everyone ___ their kind help and support today.', options: ['for', 'about', 'of', 'to'], correct: 0, phrase: 'thank for', vi: 'cảm ơn vì — thank for (cảm ơn ai về điều gì)', explanation: 'Động từ "thank" đi với "for": thank somebody for something = cảm ơn ai vì việc gì. (of/to/about không kết hợp với thank.)' },
  { id: 'pp-70', cat: 'verb', q: 'I can\'t think ___ a good name for our new puppy right now.', options: ['for', 'of', 'on', 'at'], correct: 1, phrase: 'think of', vi: 'nghĩ ra, nghĩ tới — think of (nảy ra ý, nhớ tới điều gì)', explanation: 'Khi nghĩ ra hay nhớ tới điều gì, ta dùng "think of": think of something = nghĩ ra/nghĩ tới cái gì. (on/at/for không dùng sau think theo nghĩa này.)' },
  { id: 'pp-71', cat: 'verb', q: 'Most citizens decided to vote ___ the younger candidate this year.', options: ['for', 'at', 'on', 'to'], correct: 0, phrase: 'vote for', vi: 'bỏ phiếu cho — vote for (ủng hộ ai bằng lá phiếu)', explanation: 'Động từ "vote" đi với "for" khi ủng hộ ai/cái gì: vote for someone = bỏ phiếu cho ai. (to/on/at không dùng theo nghĩa ủng hộ này.)' },
  { id: 'pp-72', cat: 'verb', q: 'The lifeguard tried to warn the swimmers ___ the strong currents.', options: ['at', 'to', 'from', 'about'], correct: 3, phrase: 'warn about', vi: 'cảnh báo về — warn about (báo trước về điều nguy hiểm)', explanation: 'Động từ "warn" đi với "about" khi nói về mối nguy: warn about something = cảnh báo về điều gì. (to/at sai; "of" trang trọng hơn nhưng "about" là lựa chọn tự nhiên ở đây.)' },
  { id: 'pp-73', cat: 'verb', q: 'My grandmother always worries ___ the weather before a long trip.', options: ['at', 'for', 'about', 'on'], correct: 2, phrase: 'worry about', vi: 'lo lắng về — worry about (bận tâm, lo nghĩ về điều gì)', explanation: 'Động từ "worry" luôn đi với "about": worry about something = lo lắng về việc gì. (for/at/on không kết hợp với worry.)' },
  { id: 'pp-74', cat: 'verb', q: 'She promised to write ___ her parents every week from college.', options: ['at', 'with', 'to', 'for'], correct: 2, phrase: 'write to', vi: 'viết thư cho — write to (gửi thư cho ai)', explanation: 'Động từ "write" đi với "to" khi gửi thư cho ai: write to someone = viết thư cho ai. (at/for/with không dùng theo nghĩa này.)' },
  { id: 'pp-75', cat: 'verb', q: 'These three factors clearly account ___ most of the recent price increase.', options: ['to', 'of', 'on', 'for'], correct: 3, phrase: 'account for', vi: 'chiếm/giải thích cho — account for (chiếm tỉ lệ; lý giải)', explanation: 'Cụm "account for" nghĩa là chiếm hoặc giải thích: account for something. Luôn đi với "for". (of/to/on không dùng với account theo nghĩa này.)' },
  { id: 'pp-76', cat: 'verb', q: 'New employees usually need time to adapt ___ the company\'s busy routine.', options: ['with', 'for', 'at', 'to'], correct: 3, phrase: 'adapt to', vi: 'thích nghi với — adapt to (làm quen, điều chỉnh theo)', explanation: 'Động từ "adapt" đi với "to": adapt to something = thích nghi với điều gì. (with/for/at không kết hợp với adapt.)' },
  { id: 'pp-77', cat: 'verb', q: 'The loud music only added ___ the stress everyone felt that evening.', options: ['for', 'to', 'on', 'with'], correct: 1, phrase: 'add to', vi: 'làm tăng thêm — add to (góp thêm vào, làm nhiều hơn)', explanation: 'Cụm "add to" nghĩa là làm tăng thêm: add to something. Luôn đi với "to". (with/on/for không dùng với add theo nghĩa này.)' },
  { id: 'pp-78', cat: 'verb', q: 'After hours of questioning, the boy finally admitted ___ breaking the window.', options: ['of', 'for', 'in', 'to'], correct: 3, phrase: 'admit to', vi: 'thừa nhận đã làm — admit to (nhận lỗi/việc gì đó)', explanation: 'Động từ "admit" đi với "to" khi nhận đã làm gì: admit to doing something = thừa nhận đã làm gì. (for/of/in không dùng với admit theo nghĩa này.)' },
  { id: 'pp-79', cat: 'verb', q: 'The new training program is aimed ___ improving the students\' speaking skills.', options: ['at', 'to', 'on', 'for'], correct: 0, phrase: 'aim at', vi: 'nhắm tới/hướng tới — aim at (nhắm vào mục tiêu)', explanation: 'Động từ "aim" đi với "at" khi hướng tới mục tiêu: aim at something = nhắm tới điều gì. (to/for/on không dùng với aim theo nghĩa này.)' },
  { id: 'pp-80', cat: 'verb', q: 'This colorful packaging is designed to appeal ___ young children in stores.', options: ['with', 'at', 'for', 'to'], correct: 3, phrase: 'appeal to', vi: 'hấp dẫn/thu hút — appeal to (lôi cuốn, gây hứng thú với ai)', explanation: 'Động từ "appeal" đi với "to" khi thu hút ai: appeal to someone = hấp dẫn ai. (for/with/at không dùng với appeal theo nghĩa này.)' },
  { id: 'pp-81', cat: 'verb', q: 'The hungry stray dog stood by the door and begged ___ food.', options: ['to', 'at', 'for', 'of'], correct: 2, phrase: 'beg for', vi: 'van xin, cầu xin — beg for (nài nỉ để có được)', explanation: 'Động từ "beg" đi với "for": beg for something = van xin/cầu xin điều gì. (to/at/of không kết hợp với beg theo nghĩa này.)' },
  { id: 'pp-82', cat: 'verb', q: 'Tourists should always beware ___ pickpockets in crowded markets.', options: ['of', 'for', 'about', 'from'], correct: 0, phrase: 'beware of', vi: 'coi chừng, cẩn thận với — beware of (đề phòng nguy hiểm)', explanation: 'Động từ "beware" luôn đi với "of": beware of something = coi chừng/cẩn thận với điều gì. (from/about/for không dùng với beware.)' },
  { id: 'pp-83', cat: 'verb', q: 'I happened to bump ___ an old classmate at the train station.', options: ['into', 'to', 'on', 'with'], correct: 0, phrase: 'bump into', vi: 'tình cờ gặp — bump into (gặp ai một cách bất ngờ)', explanation: 'Cụm "bump into" nghĩa là tình cờ gặp ai: bump into someone. (with/on/to không tạo nghĩa "tình cờ gặp".)' },
  { id: 'pp-84', cat: 'verb', q: 'The police charged the suspect ___ robbery after the investigation.', options: ['of', 'by', 'for', 'with'], correct: 3, phrase: 'charge with', vi: 'buộc tội, cáo buộc — charge with (kết tội ai về việc gì)', explanation: 'Động từ "charge" đi với "with": charge someone with a crime = buộc tội ai về điều gì. (of/for/by không dùng theo nghĩa này.)' },
  { id: 'pp-85', cat: 'verb', q: 'She found it hard to choose ___ the two job offers.', options: ['between', 'of', 'among', 'from'], correct: 0, phrase: 'choose between', vi: 'lựa chọn giữa — choose between (chọn giữa hai khả năng)', explanation: 'Khi chọn giữa hai thứ ta dùng "choose between": choose between A and B. (among dùng cho ba thứ trở lên; from/of không phù hợp ở đây.)' },
  { id: 'pp-86', cat: 'verb', q: 'The teacher asked us to comment ___ the article we had read.', options: ['for', 'about', 'on', 'to'], correct: 2, phrase: 'comment on', vi: 'nhận xét về, bình luận về — comment on (đưa ra ý kiến về)', explanation: 'Động từ "comment" đi với "on": comment on something = nhận xét/bình luận về điều gì. (about/to/for không kết hợp với comment.)' },
  { id: 'pp-87', cat: 'verb', q: 'If you compare this phone ___ the older model, it is much faster.', options: ['from', 'at', 'with', 'of'], correct: 2, phrase: 'compare with', vi: 'so sánh với — compare with (đối chiếu để thấy điểm khác)', explanation: 'Động từ "compare" đi với "with" khi đối chiếu chi tiết: compare A with B. (at/of không dùng; ở đây "with" hợp ngữ cảnh nhất.)' },
  { id: 'pp-88', cat: 'verb', q: 'Small shops struggle to compete ___ large supermarket chains.', options: ['from', 'for', 'to', 'with'], correct: 3, phrase: 'compete with', vi: 'cạnh tranh với — compete with (ganh đua với đối thủ)', explanation: 'Động từ "compete" đi với "with": compete with someone = cạnh tranh với ai. (for đi với phần thưởng, không phải đối thủ; to/against không hợp ở đây.)' },
  { id: 'pp-89', cat: 'verb', q: 'All drivers must comply ___ the new traffic regulations.', options: ['by', 'on', 'to', 'with'], correct: 3, phrase: 'comply with', vi: 'tuân thủ, tuân theo — comply with (làm theo quy định, luật lệ)', explanation: 'Động từ "comply" luôn đi với "with": comply with rules = tuân thủ quy định. (to/on/by không kết hợp với comply.)' },
  { id: 'pp-90', cat: 'verb', q: 'New products must conform ___ strict safety standards before being sold.', options: ['with', 'to', 'for', 'at'], correct: 1, phrase: 'conform to', vi: 'phù hợp với, tuân theo — conform to (đáp ứng tiêu chuẩn, quy tắc)', explanation: 'Động từ "conform" đi với "to": conform to standards = phù hợp/tuân theo tiêu chuẩn. (with/for/at không dùng với conform.)' },
  { id: 'pp-91', cat: 'verb', q: 'Please connect your laptop ___ the printer before you start the meeting.', options: ['with', 'at', 'to', 'on'], correct: 2, phrase: 'connect to', vi: 'kết nối với — connect to (nối, liên kết tới)', explanation: 'Động từ "connect" đi với "to" khi nối thiết bị này tới thiết bị khác: connect A to B = kết nối A với B. (with chỉ dùng theo nghĩa quan hệ; on/at không kết hợp với connect.)' },
  { id: 'pp-92', cat: 'verb', q: 'Her parents finally consented ___ the marriage after months of discussion.', options: ['for', 'with', 'on', 'to'], correct: 3, phrase: 'consent to', vi: 'đồng ý với — consent to (chấp thuận, ưng thuận)', explanation: 'Động từ "consent" luôn đi với "to": consent to something = đồng ý/chấp thuận điều gì. (for/with/on không kết hợp với consent.)' },
  { id: 'pp-93', cat: 'verb', q: 'The two companies agreed to cooperate ___ each other on the new project.', options: ['for', 'with', 'in', 'to'], correct: 1, phrase: 'cooperate with', vi: 'hợp tác với — cooperate with (cộng tác, làm việc cùng)', explanation: 'Động từ "cooperate" đi với "with" khi nói hợp tác với ai: cooperate with someone = hợp tác với ai đó. (to/for/in không dùng để chỉ đối tác.)' },
  { id: 'pp-94', cat: 'verb', q: 'The night train will depart ___ platform three at exactly nine o\'clock.', options: ['from', 'at', 'of', 'to'], correct: 0, phrase: 'depart from', vi: 'khởi hành từ — depart from (rời đi, xuất phát từ)', explanation: 'Động từ "depart" đi với "from" để chỉ nơi khởi hành: depart from a place = rời đi/xuất phát từ một nơi. (of/to/at không kết hợp với depart theo nghĩa này.)' },
  { id: 'pp-95', cat: 'verb', q: 'The long flight deprived the passengers ___ a good night\'s sleep.', options: ['with', 'to', 'from', 'of'], correct: 3, phrase: 'deprive of', vi: 'tước đoạt — deprive of (lấy đi, làm mất đi cái gì)', explanation: 'Động từ "deprive" luôn đi với "of": deprive someone of something = tước đoạt/lấy đi của ai cái gì. (from/with/to không kết hợp với deprive.)' },
  { id: 'pp-96', cat: 'verb', q: 'Many English words derive ___ Latin and ancient Greek roots.', options: ['by', 'from', 'of', 'to'], correct: 1, phrase: 'derive from', vi: 'bắt nguồn từ — derive from (có nguồn gốc từ)', explanation: 'Động từ "derive" đi với "from" để chỉ nguồn gốc: derive from something = bắt nguồn/có nguồn gốc từ cái gì. (of/to/by không dùng với derive theo nghĩa này.)' },
  { id: 'pp-97', cat: 'verb', q: 'She decided to devote her free time ___ helping homeless animals.', options: ['to', 'on', 'with', 'for'], correct: 0, phrase: 'devote to', vi: 'dành cho — devote to (cống hiến, dành trọn cho)', explanation: 'Động từ "devote" đi với "to": devote something to something = dành/cống hiến cái gì cho việc gì. (for/on/with không kết hợp với devote.)' },
  { id: 'pp-98', cat: 'verb', q: 'His grandmother strongly disapproves ___ children using phones at the table.', options: ['with', 'for', 'of', 'on'], correct: 2, phrase: 'disapprove of', vi: 'không tán thành — disapprove of (phản đối, không đồng tình)', explanation: 'Động từ "disapprove" luôn đi với "of": disapprove of something = không tán thành/phản đối điều gì. (with/for/on không kết hợp với disapprove.)' },
  { id: 'pp-99', cat: 'verb', q: 'Young children often cannot distinguish ___ reality and their imagination.', options: ['from', 'between', 'of', 'with'], correct: 1, phrase: 'distinguish between', vi: 'phân biệt giữa — distinguish between (nhận ra sự khác nhau giữa)', explanation: 'Động từ "distinguish" đi với "between" khi so sánh hai thứ: distinguish between A and B = phân biệt giữa A và B. (from dùng cho distinguish A from B; of/with không phù hợp ở đây.)' },
  { id: 'pp-100', cat: 'verb', q: 'The teacher asked us to divide the class ___ four small groups.', options: ['into', 'in', 'by', 'to'], correct: 0, phrase: 'divide into', vi: 'chia thành — divide into (phân chia ra thành các phần)', explanation: 'Động từ "divide" đi với "into" khi chia thành các phần: divide something into parts = chia cái gì thành các phần. (to/in/by không dùng để chỉ kết quả của phép chia này.)' },
  { id: 'pp-101', cat: 'verb', q: 'Many kind people donate ___ charity every month to help the poor.', options: ['at', 'for', 'on', 'to'], correct: 3, phrase: 'donate to', vi: 'quyên góp cho — donate to (tặng, đóng góp cho ai/tổ chức)', explanation: 'Động từ "donate" đi với "to": donate to something/someone = quyên góp cho. (for/at/on không kết hợp với donate khi chỉ nơi nhận.)' },
  { id: 'pp-102', cat: 'verb', q: 'A small rabbit suddenly emerged ___ the bushes near the river.', options: ['with', 'at', 'from', 'of'], correct: 2, phrase: 'emerge from', vi: 'hiện ra từ — emerge from (xuất hiện, đi ra từ đâu)', explanation: 'Động từ "emerge" đi với "from": emerge from = hiện ra/đi ra từ. (of/at/with không dùng để chỉ nơi xuất phát với emerge.)' },
  { id: 'pp-103', cat: 'verb', q: 'The students were eager to engage ___ a lively classroom debate.', options: ['at', 'on', 'in', 'for'], correct: 2, phrase: 'engage in', vi: 'tham gia vào — engage in (dấn thân, tham gia hoạt động gì)', explanation: 'Động từ "engage" đi với "in": engage in something = tham gia vào việc gì. (on/at/for không kết hợp với engage theo nghĩa này.)' },
  { id: 'pp-104', cat: 'verb', q: 'My younger brother really excels ___ solving difficult math problems quickly.', options: ['on', 'for', 'with', 'at'], correct: 3, phrase: 'excel at', vi: 'giỏi xuất sắc về — excel at (vượt trội, làm rất giỏi việc gì)', explanation: 'Động từ "excel" thường đi với "at": excel at something = rất giỏi việc gì. (in/on/with không phải cấu trúc thông dụng với excel.)' },
  { id: 'pp-105', cat: 'verb', q: 'She wanted to exchange the shirt ___ a larger size at the store.', options: ['of', 'to', 'for', 'with'], correct: 2, phrase: 'exchange for', vi: 'đổi lấy — exchange for (trao đổi cái này lấy cái kia)', explanation: 'Động từ "exchange" đi với "for": exchange A for B = đổi A lấy B. (with/to/of không diễn đạt việc đổi lấy thứ khác.)' },
  { id: 'pp-106', cat: 'verb', q: 'The brave soldiers were ready to fight ___ their country\'s freedom.', options: ['for', 'with', 'at', 'on'], correct: 0, phrase: 'fight for', vi: 'đấu tranh vì — fight for (chiến đấu/đấu tranh giành điều gì)', explanation: 'Động từ "fight" đi với "for" khi chỉ mục tiêu: fight for = đấu tranh vì. (with nghĩa là chống lại; on/at không hợp ở đây.)' },
  { id: 'pp-107', cat: 'verb', q: 'He quickly glanced ___ his watch and realized he was late.', options: ['at', 'on', 'in', 'to'], correct: 0, phrase: 'glance at', vi: 'liếc nhìn — glance at (nhìn lướt, nhìn nhanh vào)', explanation: 'Động từ "glance" đi với "at": glance at something = liếc nhìn vật gì. (on/to/in không dùng với glance.)' },
  { id: 'pp-108', cat: 'verb', q: 'During the meeting, the manager hinted ___ possible changes to our schedule.', options: ['of', 'on', 'to', 'at'], correct: 3, phrase: 'hint at', vi: 'ám chỉ, bóng gió về — hint at (gợi ý kín đáo về điều gì)', explanation: 'Động từ "hint" đi với "at": hint at something = ám chỉ, bóng gió về. (to/on/of không kết hợp với hint theo nghĩa này.)' },
  { id: 'pp-109', cat: 'verb', q: 'Many young readers strongly identify ___ the hero of that novel.', options: ['with', 'at', 'to', 'for'], correct: 0, phrase: 'identify with', vi: 'đồng cảm với — identify with (thấy mình giống, đồng cảm với ai)', explanation: 'Động từ "identify" đi với "with": identify with someone = đồng cảm, thấy mình giống ai. (to/for/at không dùng theo nghĩa này.)' },
  { id: 'pp-110', cat: 'verb', q: 'On weekends she likes to indulge ___ a bit of chocolate cake.', options: ['in', 'with', 'at', 'on'], correct: 0, phrase: 'indulge in', vi: 'thỏa thích, chiều theo — indulge in (cho phép mình tận hưởng điều gì)', explanation: 'Động từ "indulge" đi với "in": indulge in something = thỏa thích hưởng thụ điều gì. (at/on/with không kết hợp với indulge.)' },
  { id: 'pp-111', cat: 'verb', q: 'She went to the desk to inquire ___ the train times.', options: ['on', 'to', 'for', 'about'], correct: 3, phrase: 'inquire about', vi: 'hỏi thăm về — inquire about (tìm hiểu thông tin về việc gì)', explanation: 'Động từ "inquire" đi với "about": inquire about something = hỏi thăm về việc gì. (on/for/to không kết hợp với inquire theo nghĩa này.)' },
  { id: 'pp-112', cat: 'verb', q: 'Many homeowners insure their houses ___ fire and flooding.', options: ['with', 'against', 'for', 'from'], correct: 1, phrase: 'insure against', vi: 'bảo hiểm chống lại — insure against (mua bảo hiểm phòng rủi ro)', explanation: 'Động từ "insure" đi với "against": insure against something = bảo hiểm để phòng rủi ro. (for/with/from không dùng với insure theo nghĩa này.)' },
  { id: 'pp-113', cat: 'verb', q: 'After years abroad, he began to long ___ his home country.', options: ['at', 'to', 'for', 'of'], correct: 2, phrase: 'long for', vi: 'khao khát, mong mỏi — long for (rất muốn có điều gì)', explanation: 'Động từ "long" đi với "for": long for something = khao khát điều gì. (to/of/at không kết hợp với long.)' },
  { id: 'pp-114', cat: 'verb', q: 'The tourists stopped to marvel ___ the ancient temple\'s beauty.', options: ['at', 'on', 'with', 'of'], correct: 0, phrase: 'marvel at', vi: 'trầm trồ, kinh ngạc trước — marvel at (ngạc nhiên thán phục)', explanation: 'Động từ "marvel" đi với "at": marvel at something = kinh ngạc trước điều gì. (on/with/of không dùng với marvel.)' },
  { id: 'pp-115', cat: 'verb', q: 'You should not meddle ___ other people\'s private affairs.', options: ['to', 'for', 'at', 'in'], correct: 3, phrase: 'meddle in', vi: 'xen vào, can thiệp vào — meddle in (chõ mũi vào việc của người khác)', explanation: 'Động từ "meddle" đi với "in": meddle in something = xen vào việc gì. (at/for/to không kết hợp với meddle.)' },
  { id: 'pp-116', cat: 'verb', q: 'In the dim light, I mistook the stranger ___ my brother.', options: ['for', 'with', 'as', 'to'], correct: 0, phrase: 'mistake for', vi: 'nhầm với — mistake for (tưởng người/vật này là người/vật khác)', explanation: 'Động từ "mistake" đi với "for": mistake A for B = nhầm A với B. (as/with/to không dùng trong cấu trúc này.)' },
  { id: 'pp-117', cat: 'verb', q: 'The whole nation paused to mourn ___ the fallen soldiers.', options: ['at', 'for', 'of', 'on'], correct: 1, phrase: 'mourn for', vi: 'thương tiếc, để tang — mourn for (đau buồn vì ai đó mất)', explanation: 'Động từ "mourn" đi với "for": mourn for someone = thương tiếc ai đó. (of/at/on không kết hợp với mourn.)' },
  { id: 'pp-118', cat: 'verb', q: 'The surgeons will operate ___ the patient early tomorrow morning.', options: ['for', 'on', 'at', 'in'], correct: 1, phrase: 'operate on', vi: 'phẫu thuật cho — operate on (mổ, giải phẫu bệnh nhân)', explanation: 'Động từ "operate" (mổ) đi với "on": operate on someone = phẫu thuật cho ai. (at/in/for không dùng theo nghĩa này.)' },
  { id: 'pp-119', cat: 'verb', q: 'Instead of driving, they decided to opt ___ the train.', options: ['to', 'for', 'with', 'on'], correct: 1, phrase: 'opt for', vi: 'chọn, lựa chọn — opt for (quyết định chọn phương án nào)', explanation: 'Động từ "opt" đi với "for": opt for something = chọn điều gì. (to/with/on không kết hợp với opt.)' },
  { id: 'pp-120', cat: 'verb', q: 'She loved the old painting and refused to part ___ it.', options: ['to', 'from', 'with', 'of'], correct: 2, phrase: 'part with', vi: 'chia tay, từ bỏ — part with (đành rời bỏ thứ mình quý)', explanation: 'Động từ "part" đi với "with": part with something = từ bỏ thứ gì. (from/of/to không dùng với part theo nghĩa này.)' },
  { id: 'pp-121', cat: 'verb', q: 'Despite the warnings, he persisted ___ ignoring the safety rules.', options: ['on', 'for', 'in', 'at'], correct: 2, phrase: 'persist in', vi: 'khăng khăng, kiên trì làm — persist in (cố chấp tiếp tục làm gì)', explanation: 'Động từ "persist" đi với "in": persist in doing something = khăng khăng/kiên trì làm việc gì. (on/at/for không kết hợp với persist.)' },
  { id: 'pp-122', cat: 'verb', q: 'The rebels secretly plotted ___ the corrupt king for years.', options: ['with', 'over', 'against', 'for'], correct: 2, phrase: 'plot against', vi: 'âm mưu chống lại — plot against (lập mưu hại ai)', explanation: 'Động từ "plot" đi với "against": plot against someone = âm mưu chống lại ai. (for/with/over không diễn tả ý chống đối ở đây.)' },
  { id: 'pp-123', cat: 'verb', q: 'In the end, good sense prevailed ___ fear and panic.', options: ['over', 'from', 'on', 'at'], correct: 0, phrase: 'prevail over', vi: 'thắng thế, chiến thắng — prevail over (vượt qua, áp đảo)', explanation: 'Động từ "prevail" đi với "over": prevail over something = thắng thế/áp đảo cái gì. (on/at/from không dùng với prevail theo nghĩa này.)' },
  { id: 'pp-124', cat: 'verb', q: 'Many companies profited ___ the sudden rise in oil prices.', options: ['of', 'on', 'from', 'with'], correct: 2, phrase: 'profit from', vi: 'thu lợi từ — profit from (kiếm lợi nhờ điều gì)', explanation: 'Động từ "profit" đi với "from": profit from something = thu lợi từ việc gì. (of/on/with không kết hợp với profit.)' },
  { id: 'pp-125', cat: 'verb', q: 'Only students with top grades qualify ___ the scholarship.', options: ['in', 'to', 'for', 'at'], correct: 2, phrase: 'qualify for', vi: 'đủ điều kiện nhận — qualify for (đạt tiêu chuẩn cho)', explanation: 'Động từ "qualify" đi với "for": qualify for something = đủ điều kiện cho việc gì. (to/in/at không dùng với qualify theo nghĩa này.)' },
  { id: 'pp-126', cat: 'verb', q: 'She rarely quarrels ___ her neighbours about anything.', options: ['to', 'for', 'with', 'against'], correct: 2, phrase: 'quarrel with', vi: 'cãi nhau với — quarrel with (gây gổ, tranh cãi với ai)', explanation: 'Động từ "quarrel" đi với "with": quarrel with someone = cãi nhau với ai. (to/against/for không kết hợp với quarrel.)' },
  { id: 'pp-127', cat: 'verb', q: 'As a teenager, he rebelled ___ his parents\' strict rules.', options: ['from', 'against', 'to', 'over'], correct: 1, phrase: 'rebel against', vi: 'nổi loạn chống lại — rebel against (chống đối, phản kháng)', explanation: 'Động từ "rebel" đi với "against": rebel against something = nổi loạn chống lại cái gì. (from/to/over không diễn tả ý chống đối này.)' },
  { id: 'pp-128', cat: 'verb', q: 'Any new leader will have to reckon ___ public opposition.', options: ['for', 'at', 'with', 'on'], correct: 2, phrase: 'reckon with', vi: 'phải tính đến, đối phó với — reckon with (lường trước, đương đầu)', explanation: 'Động từ "reckon" đi với "with": reckon with something = phải tính đến/đối phó với điều gì. (on/for/at không dùng với reckon theo nghĩa này.)' },
  { id: 'pp-129', cat: 'verb', q: 'The whole village rejoiced ___ the safe return of the sailors.', options: ['on', 'for', 'from', 'at'], correct: 3, phrase: 'rejoice at', vi: 'vui mừng vì — rejoice at (hân hoan trước điều gì)', explanation: 'Động từ "rejoice" đi với "at": rejoice at something = vui mừng trước/vì điều gì. (on/for/from không kết hợp với rejoice ở đây.)' },
  { id: 'pp-130', cat: 'verb', q: 'Most readers can easily relate ___ the hero\'s struggles.', options: ['on', 'to', 'at', 'with'], correct: 1, phrase: 'relate to', vi: 'đồng cảm, liên hệ với — relate to (thấu hiểu, gắn với)', explanation: 'Động từ "relate" đi với "to": relate to something = đồng cảm/liên hệ với điều gì. (with/at/on không dùng với relate theo nghĩa này.)' },
  { id: 'pp-131', cat: 'verb', q: 'When talks failed, the workers had to resort ___ a strike.', options: ['on', 'for', 'at', 'to'], correct: 3, phrase: 'resort to', vi: 'phải dùng đến (biện pháp cuối) — resort to (viện đến cách nào đó)', explanation: 'Động từ "resort" luôn đi với "to": resort to something = phải dùng đến biện pháp gì (thường là biện pháp cuối cùng). (at/on/for không kết hợp với resort.)' },
  { id: 'pp-132', cat: 'verb', q: 'The manager promised to respond ___ every customer email quickly.', options: ['with', 'on', 'to', 'for'], correct: 2, phrase: 'respond to', vi: 'đáp lại, phản hồi — respond to (trả lời, đáp ứng)', explanation: 'Động từ "respond" luôn đi với "to": respond to something = đáp lại/phản hồi điều gì. (for/with/on không dùng với respond theo nghĩa này.)' },
  { id: 'pp-133', cat: 'verb', q: 'The judge decided to sentence the thief ___ three years in prison.', options: ['for', 'to', 'at', 'with'], correct: 1, phrase: 'sentence to', vi: 'kết án, tuyên án — sentence to (tuyên phạt ai mức án gì)', explanation: 'Động từ "sentence" đi với "to": sentence somebody to something = tuyên phạt ai mức án gì. (at/for/with không kết hợp với sentence ở đây.)' },
  { id: 'pp-134', cat: 'verb', q: 'A long fence separates our garden ___ the neighbour\'s property.', options: ['of', 'from', 'with', 'to'], correct: 1, phrase: 'separate from', vi: 'tách ra khỏi — separate from (phân chia, ngăn cách)', explanation: 'Động từ "separate" đi với "from": separate A from B = tách A ra khỏi B. (of/with/to không dùng với separate theo nghĩa ngăn cách.)' },
  { id: 'pp-135', cat: 'verb', q: 'He refused to settle ___ less than he truly deserved.', options: ['to', 'with', 'for', 'on'], correct: 2, phrase: 'settle for', vi: 'chấp nhận, đành nhận — settle for (đành bằng lòng với cái kém hơn)', explanation: 'Động từ "settle" trong nghĩa này đi với "for": settle for something = đành chấp nhận điều gì (dù chưa ưng). (with/on/to cho nghĩa khác, không hợp ở đây.)' },
  { id: 'pp-136', cat: 'verb', q: 'The rich man tended to sneer ___ anyone wearing cheap clothes.', options: ['at', 'on', 'over', 'to'], correct: 0, phrase: 'sneer at', vi: 'cười khẩy, khinh bỉ — sneer at (chế nhạo, coi thường)', explanation: 'Động từ "sneer" luôn đi với "at": sneer at somebody = cười khẩy/khinh bỉ ai. (on/to/over không kết hợp với sneer.)' },
  { id: 'pp-137', cat: 'verb', q: 'Can you tell me what the letters NASA actually stand ___?', options: ['for', 'with', 'of', 'by'], correct: 0, phrase: 'stand for', vi: 'là viết tắt của, đại diện cho — stand for (tượng trưng cho)', explanation: 'Cụm "stand for" nghĩa là viết tắt của/đại diện cho điều gì. Động từ "stand" đi với "for" trong nghĩa này. (of/with/by không dùng được ở đây.)' },
  { id: 'pp-138', cat: 'verb', q: 'Most of her fears seem to stem ___ a difficult childhood.', options: ['to', 'of', 'at', 'from'], correct: 3, phrase: 'stem from', vi: 'bắt nguồn từ, xuất phát từ — stem from (do đâu mà ra)', explanation: 'Động từ "stem" đi với "from": stem from something = bắt nguồn/xuất phát từ điều gì. (to/of/at không kết hợp với stem.)' },
  { id: 'pp-139', cat: 'verb', q: 'Once you make a plan, you should always stick ___ it.', options: ['on', 'to', 'of', 'for'], correct: 1, phrase: 'stick to', vi: 'giữ vững, bám sát — stick to (kiên trì theo, tuân thủ)', explanation: 'Động từ "stick" trong nghĩa kiên trì đi với "to": stick to something = giữ vững/bám sát điều gì. (with/on/for không hợp với nghĩa này.)' },
  { id: 'pp-140', cat: 'verb', q: 'Great athletes constantly strive ___ perfection in every competition.', options: ['on', 'at', 'to', 'for'], correct: 3, phrase: 'strive for', vi: 'phấn đấu vì, nỗ lực đạt — strive for (cố gắng giành lấy)', explanation: 'Động từ "strive" đi với "for": strive for something = phấn đấu/nỗ lực vì điều gì. (at/on/to không kết hợp với strive ở đây.)' },
  { id: 'pp-141', cat: 'verb', q: 'I really sympathize ___ you after losing your job last week.', options: ['with', 'to', 'for', 'on'], correct: 0, phrase: 'sympathize with', vi: 'thông cảm với — sympathize with (đồng cảm, chia sẻ cảm xúc với ai)', explanation: 'Động từ "sympathize" luôn đi với "with": sympathize with someone = thông cảm với ai. (for/to/on không kết hợp với sympathize.)' },
  { id: 'pp-142', cat: 'verb', q: 'The witness agreed to testify ___ the accused man in court.', options: ['against', 'to', 'with', 'at'], correct: 0, phrase: 'testify against', vi: 'làm chứng chống lại — testify against (ra tòa làm chứng buộc tội ai)', explanation: 'Khi làm chứng buộc tội ai, ta dùng "testify against": testify against someone. (with/for/to không diễn đạt nghĩa chống lại trong tòa.)' },
  { id: 'pp-143', cat: 'verb', q: 'She helped me translate the letter ___ Vietnamese for my parents.', options: ['in', 'for', 'into', 'to'], correct: 2, phrase: 'translate into', vi: 'dịch sang — translate into (chuyển ngôn ngữ này sang ngôn ngữ khác)', explanation: 'Động từ "translate" đi với "into" khi nói ngôn ngữ đích: translate into a language = dịch sang một ngôn ngữ. (to/for/in không dùng với translate ở đây.)' },
  { id: 'pp-144', cat: 'verb', q: 'I can vouch ___ his honesty because I have known him for years.', options: ['with', 'on', 'for', 'to'], correct: 2, phrase: 'vouch for', vi: 'đảm bảo cho — vouch for (bảo đảm, làm chứng về tính cách của ai)', explanation: 'Động từ "vouch" luôn đi với "for": vouch for someone = đảm bảo cho ai. (on/to/with không kết hợp với vouch.)' },
  { id: 'pp-145', cat: 'verb', q: 'After years abroad, she began to yearn ___ her hometown and family.', options: ['at', 'of', 'for', 'to'], correct: 2, phrase: 'yearn for', vi: 'khao khát, mong mỏi — yearn for (thèm muốn, nhớ nhung điều gì)', explanation: 'Động từ "yearn" đi với "for": yearn for something = khao khát điều gì. (to/at/of không kết hợp với yearn.)' },
  { id: 'pp-146', cat: 'verb', q: 'Most members opposed the plan, so they voted ___ the new tax proposal.', options: ['against', 'with', 'at', 'by'], correct: 0, phrase: 'vote against', vi: 'bỏ phiếu chống — vote against (phản đối điều gì bằng lá phiếu)', explanation: 'Để phản đối, ta dùng "vote against": vote against something = bỏ phiếu chống điều gì. ("vote for" là ủng hộ; to/on không phù hợp ở đây.)' },
  { id: 'pp-147', cat: 'verb', q: 'They will arrive ___ London early tomorrow morning after a long flight.', options: ['on', 'to', 'in', 'at'], correct: 2, phrase: 'arrive in', vi: 'đến (nơi lớn) — arrive in (đến một thành phố, quốc gia)', explanation: 'Với thành phố hay quốc gia, ta dùng "arrive in": arrive in London. ("arrive at" dùng cho địa điểm nhỏ; to/on không đi với arrive.)' },
  { id: 'pp-148', cat: 'verb', q: 'My teacher always asks ___ my family whenever we meet at school.', options: ['to', 'for', 'about', 'of'], correct: 2, phrase: 'ask about', vi: 'hỏi thăm về — ask about (hỏi để biết thông tin về điều gì)', explanation: 'Để hỏi thông tin, ta dùng "ask about": ask about something = hỏi về điều gì. ("ask for" là xin/yêu cầu; to/of không phù hợp.)' },
  { id: 'pp-149', cat: 'verb', q: 'Last night I dreamed ___ flying over the ocean on a giant bird.', options: ['for', 'at', 'to', 'about'], correct: 3, phrase: 'dream about', vi: 'mơ về — dream about (thấy điều gì trong giấc mơ khi ngủ)', explanation: 'Khi nói về giấc mơ lúc ngủ, ta dùng "dream about": dream about something. (for/at/to không kết hợp với dream theo nghĩa này.)' },
  { id: 'pp-150', cat: 'verb', q: 'I haven\'t heard ___ my old friend since she moved to Canada.', options: ['about', 'to', 'from', 'of'], correct: 2, phrase: 'hear from', vi: 'nhận tin từ — hear from (nhận được thư, tin nhắn hay liên lạc từ ai)', explanation: 'Để nói nhận được liên lạc từ ai, ta dùng "hear from": hear from someone. ("hear of/about" là nghe nói về ai; to không đi với hear.)' },
  { id: 'pp-151', cat: 'verb', q: 'After graduation, she decided to embark ___ a new career in nursing.', options: ['in', 'on', 'for', 'to'], correct: 1, phrase: 'embark on', vi: 'bắt đầu, dấn thân vào — embark on (khởi sự một việc lớn)', explanation: 'Động từ "embark" đi với "on": embark on something = bắt đầu/dấn thân vào việc gì. (in/to/for không kết hợp với embark.)' },
  { id: 'pp-152', cat: 'verb', q: 'The company quickly capitalized ___ the growing demand for electric cars.', options: ['in', 'at', 'of', 'on'], correct: 3, phrase: 'capitalize on', vi: 'tận dụng, khai thác — capitalize on (lợi dụng cơ hội)', explanation: 'Động từ "capitalize" đi với "on": capitalize on something = tận dụng/khai thác điều gì. (of/in/at không dùng với capitalize.)' },
  { id: 'pp-153', cat: 'verb', q: 'Try not to dwell ___ your past mistakes and move forward instead.', options: ['at', 'in', 'over', 'on'], correct: 3, phrase: 'dwell on', vi: 'day dứt, nghĩ mãi về — dwell on (cứ bận tâm chuyện gì)', explanation: 'Động từ "dwell" theo nghĩa này đi với "on": dwell on something = nghĩ mãi/day dứt về điều gì. (in/at/over không kết hợp với dwell.)' },
  { id: 'pp-154', cat: 'verb', q: 'At the end of the year, we should reflect ___ what we have learned.', options: ['to', 'about', 'on', 'at'], correct: 2, phrase: 'reflect on', vi: 'suy ngẫm về — reflect on (ngẫm nghĩ kỹ về điều gì)', explanation: 'Động từ "reflect" theo nghĩa suy ngẫm đi với "on": reflect on something = suy ngẫm về điều gì. (at/about/to không dùng với reflect.)' },
  { id: 'pp-155', cat: 'verb', q: 'The teacher frowned ___ the noisy students at the back of the room.', options: ['to', 'at', 'on', 'with'], correct: 1, phrase: 'frown at', vi: 'cau mày, nhăn mặt với — frown at (tỏ vẻ không hài lòng)', explanation: 'Động từ "frown" đi với "at" khi chỉ đối tượng: frown at someone = cau mày với ai. (on/to/with không kết hợp với frown.)' },
  { id: 'pp-156', cat: 'verb', q: 'She was so tired that she snapped ___ her colleague over a small mistake.', options: ['on', 'for', 'at', 'to'], correct: 2, phrase: 'snap at', vi: 'gắt gỏng, cáu với — snap at (nói cộc cằn với ai)', explanation: 'Động từ "snap" theo nghĩa cáu gắt đi với "at": snap at someone = gắt gỏng với ai. (on/to/for không dùng với snap.)' },
  { id: 'pp-157', cat: 'verb', q: 'The cat waited quietly, then pounced ___ the mouse in an instant.', options: ['over', 'on', 'in', 'to'], correct: 1, phrase: 'pounce on', vi: 'vồ lấy, chộp lấy — pounce on (lao vào tóm lấy)', explanation: 'Động từ "pounce" đi với "on": pounce on something = vồ/chộp lấy cái gì. (in/over/to không kết hợp với pounce.)' },
  { id: 'pp-158', cat: 'verb', q: 'My grandparents absolutely dote ___ their first grandchild every single day.', options: ['to', 'at', 'over', 'on'], correct: 3, phrase: 'dote on', vi: 'cưng chiều, yêu thương hết mực — dote on (nuông chiều ai)', explanation: 'Động từ "dote" đi với "on": dote on someone = cưng chiều/yêu thương hết mực ai. (over/to/at không dùng với dote.)' },
  { id: 'pp-159', cat: 'verb', q: 'Owls usually prey ___ small rodents such as mice and voles at night.', options: ['at', 'in', 'on', 'for'], correct: 2, phrase: 'prey on', vi: 'săn mồi, bắt làm mồi — prey on (lợi dụng/săn bắt)', explanation: 'Động từ "prey" đi với "on": prey on something = săn/bắt làm mồi. (at/for/in không kết hợp với prey.)' },
  { id: 'pp-160', cat: 'verb', q: 'The lecturer only briefly touched ___ that topic before the class ended.', options: ['in', 'to', 'on', 'at'], correct: 2, phrase: 'touch on', vi: 'đề cập sơ qua đến — touch on (nói lướt qua về điều gì)', explanation: 'Động từ "touch" theo nghĩa đề cập đi với "on": touch on something = nói sơ qua về điều gì. (at/in/to không dùng với touch theo nghĩa này.)' },
  { id: 'pp-161', cat: 'verb', q: 'All players must abide ___ the rules set by the referee.', options: ['by', 'to', 'with', 'in'], correct: 0, phrase: 'abide by', vi: 'tuân theo — abide by (chấp hành, tuân thủ quy tắc, luật lệ)', explanation: 'Động từ "abide" đi với "by": abide by the rules = tuân theo luật lệ. (with/to/in không kết hợp với abide.)' },
  { id: 'pp-162', cat: 'verb', q: 'Someone tried to tamper ___ the lock on the office door.', options: ['at', 'on', 'for', 'with'], correct: 3, phrase: 'tamper with', vi: 'can thiệp/phá trái phép — tamper with (động chạm, sửa lén lút)', explanation: 'Động từ "tamper" luôn đi với "with": tamper with something = can thiệp trái phép vào vật gì. (at/on/for không dùng với tamper.)' },
  { id: 'pp-163', cat: 'verb', q: 'Her bright orange shirt seemed to clash ___ the pink skirt.', options: ['to', 'from', 'with', 'against'], correct: 2, phrase: 'clash with', vi: 'xung đột/không hợp — clash with (đối chọi, kèn cựa, lệch nhau)', explanation: 'Động từ "clash" đi với "with": clash with something = xung đột hoặc không hợp với vật gì. (to/against/from không kết hợp với clash.)' },
  { id: 'pp-164', cat: 'verb', q: 'The cyclist nearly collided ___ a parked car on the corner.', options: ['on', 'to', 'with', 'into'], correct: 2, phrase: 'collide with', vi: 'va chạm/đâm vào — collide with (đụng mạnh vào nhau)', explanation: 'Động từ "collide" đi với "with": collide with something = va chạm vào vật gì. (into/to/on không dùng với collide.)' },
  { id: 'pp-165', cat: 'verb', q: 'She has corresponded ___ her pen pal in Japan for years.', options: ['for', 'to', 'at', 'with'], correct: 3, phrase: 'correspond with', vi: 'trao đổi thư từ — correspond with (liên lạc, thư từ với ai)', explanation: 'Động từ "correspond" đi với "with" khi nói về liên lạc: correspond with someone = trao đổi thư từ với ai. (to/at/for không dùng ở nghĩa này.)' },
  { id: 'pp-166', cat: 'verb', q: 'He spent the whole evening flirting ___ a girl at the bar.', options: ['on', 'to', 'at', 'with'], correct: 3, phrase: 'flirt with', vi: 'tán tỉnh — flirt with (đùa cợt, ve vãn ai)', explanation: 'Động từ "flirt" đi với "with": flirt with someone = tán tỉnh ai. (at/to/on không kết hợp với flirt.)' },
  { id: 'pp-167', cat: 'verb', q: 'My grandfather loves to tinker ___ old radios in the garage.', options: ['with', 'on', 'in', 'at'], correct: 0, phrase: 'tinker with', vi: 'mày mò sửa — tinker with (loay hoay vặn vọ, chỉnh sửa lặt vặt)', explanation: 'Động từ "tinker" đi với "with": tinker with something = mày mò sửa chữa vật gì. (on/in/at không dùng với tinker.)' },
  { id: 'pp-168', cat: 'verb', q: 'It was impossible to reason ___ the angry crowd outside.', options: ['with', 'to', 'for', 'against'], correct: 0, phrase: 'reason with', vi: 'phân tích thuyết phục — reason with (lý lẽ, khuyên giải ai)', explanation: 'Động từ "reason" đi với "with": reason with someone = thuyết phục ai bằng lý lẽ. (to/for/against không dùng với reason.)' },
  { id: 'pp-169', cat: 'verb', q: 'In every argument, she tends to side ___ her younger brother.', options: ['by', 'on', 'with', 'for'], correct: 2, phrase: 'side with', vi: 'đứng về phía — side with (ủng hộ, bênh vực ai)', explanation: 'Động từ "side" đi với "with": side with someone = đứng về phía, ủng hộ ai. (for/on/by không kết hợp với side.)' },
  { id: 'pp-170', cat: 'verb', q: 'In summer we can dispense ___ heavy coats and thick scarves.', options: ['off', 'from', 'of', 'with'], correct: 3, phrase: 'dispense with', vi: 'bỏ đi/không cần đến — dispense with (loại bỏ, miễn dùng)', explanation: 'Động từ "dispense" đi với "with": dispense with something = bỏ đi, không cần đến vật gì. (of/from/off không dùng với dispense.)' },
  { id: 'pp-171', cat: 'verb', q: 'The storm inflicted serious damage ___ the coastal villages overnight.', options: ['to', 'on', 'at', 'for'], correct: 1, phrase: 'inflict on', vi: 'gây ra (cho) — inflict on (giáng, áp đặt điều xấu lên ai/cái gì)', explanation: '"Inflict" luôn đi với "on": inflict something on someone = gây ra điều gì cho ai. (to/at/for không kết hợp với inflict.) Quy tắc: tác hại được giáng "lên" đối tượng nên dùng on.' },
  { id: 'pp-172', cat: 'verb', q: 'The government decided to impose a new tax ___ imported cars.', options: ['on', 'at', 'with', 'of'], correct: 0, phrase: 'impose on', vi: 'áp đặt lên — impose on (đặt ra, bắt buộc điều gì cho ai/cái gì)', explanation: '"Impose" đi với "on": impose something on something = áp đặt cái gì lên cái gì. (at/of/with không dùng với impose.) Một luật/thuế được đặt "lên" đối tượng nên dùng on.' },
  { id: 'pp-173', cat: 'verb', q: 'Many traditional families frown ___ marrying outside their own culture.', options: ['upon', 'under', 'off', 'into'], correct: 0, phrase: 'frown upon', vi: 'phản đối, không tán thành — frown upon (tỏ thái độ không hài lòng về điều gì)', explanation: '"Frown" theo nghĩa phản đối đi với "upon" (hoặc on): frown upon something = không tán thành điều gì. (into/off/under không kết hợp với frown.)' },
  { id: 'pp-174', cat: 'verb', q: 'While cleaning the attic, I stumbled ___ an old box of letters.', options: ['from', 'upon', 'through', 'against'], correct: 1, phrase: 'stumble upon', vi: 'tình cờ tìm thấy — stumble upon (vô tình bắt gặp, phát hiện điều gì)', explanation: '"Stumble" theo nghĩa tình cờ phát hiện đi với "upon" (hoặc on): stumble upon something = tình cờ tìm thấy. (from/against/through không dùng với nghĩa này.)' },
  { id: 'pp-175', cat: 'verb', q: 'His constant suspicion of everyone borders ___ paranoia at this point.', options: ['on', 'to', 'in', 'by'], correct: 0, phrase: 'border on', vi: 'gần như là, cận kề — border on (gần đạt tới một trạng thái/mức độ nào đó)', explanation: '"Border" theo nghĩa gần như là đi với "on": border on something = gần như đạt tới điều gì. (in/by/to không kết hợp với border ở nghĩa này.)' },
  { id: 'pp-176', cat: 'verb', q: 'The success of the whole project hinges ___ next week\'s final decision.', options: ['with', 'of', 'over', 'on'], correct: 3, phrase: 'hinge on', vi: 'phụ thuộc vào — hinge on (tùy thuộc hoàn toàn vào một yếu tố quyết định)', explanation: '"Hinge" đi với "on": hinge on something = phụ thuộc vào điều gì. (with/of/over không kết hợp với hinge.) Mọi thứ "bản lề" vào yếu tố then chốt nên dùng on.' },
  { id: 'pp-177', cat: 'adj', q: 'My younger sister is very good ___ playing the piano.', options: ['in', 'on', 'with', 'at'], correct: 3, phrase: 'good at', vi: 'giỏi về — good at (có khả năng làm tốt việc gì)', explanation: 'Tính từ "good" đi với "at" để chỉ kỹ năng: good at = giỏi về việc gì. (in/on/with không kết hợp với good ở nghĩa này.)' },
  { id: 'pp-178', cat: 'adj', q: 'He is really bad ___ remembering people\'s names at parties.', options: ['in', 'for', 'at', 'of'], correct: 2, phrase: 'bad at', vi: 'kém về — bad at (làm không tốt việc gì)', explanation: 'Tính từ "bad" đi với "at" khi nói về kỹ năng: bad at = kém về việc gì. (in/of/for không dùng với bad ở nghĩa này.)' },
  { id: 'pp-179', cat: 'adj', q: 'She has always been interested ___ ancient history and old buildings.', options: ['in', 'at', 'on', 'for'], correct: 0, phrase: 'interested in', vi: 'quan tâm đến — interested in (thích thú, hứng thú với)', explanation: 'Tính từ "interested" luôn đi với "in": interested in = quan tâm, hứng thú với. (on/at/for không kết hợp với interested.)' },
  { id: 'pp-180', cat: 'adj', q: 'Many small children are afraid ___ the dark at night.', options: ['about', 'for', 'of', 'from'], correct: 2, phrase: 'afraid of', vi: 'sợ — afraid of (e ngại, sợ hãi điều gì)', explanation: 'Tính từ "afraid" đi với "of": afraid of = sợ điều gì. (from/for/about không dùng sau afraid.)' },
  { id: 'pp-181', cat: 'adj', q: 'His parents were very proud ___ his exam results this year.', options: ['about', 'with', 'of', 'for'], correct: 2, phrase: 'proud of', vi: 'tự hào về — proud of (hãnh diện về ai/điều gì)', explanation: 'Tính từ "proud" đi với "of": proud of = tự hào về. (with/about/for không kết hợp với proud.)' },
  { id: 'pp-182', cat: 'adj', q: 'She felt jealous ___ her best friend\'s brand-new car.', options: ['to', 'of', 'about', 'with'], correct: 1, phrase: 'jealous of', vi: 'ghen tị với — jealous of (đố kỵ, ganh ghét)', explanation: 'Tính từ "jealous" đi với "of": jealous of = ghen tị với. (about/with/to không dùng sau jealous.)' },
  { id: 'pp-183', cat: 'adj', q: 'My grandmother is very fond ___ baking cakes on Sundays.', options: ['on', 'for', 'of', 'with'], correct: 2, phrase: 'fond of', vi: 'thích, yêu mến — fond of (mến mộ, ưa thích)', explanation: 'Tính từ "fond" luôn đi với "of": fond of = thích, yêu mến. (with/for/on không kết hợp với fond.)' },
  { id: 'pp-184', cat: 'adj', q: 'The little boy is scared ___ big dogs in the park.', options: ['of', 'by', 'from', 'at'], correct: 0, phrase: 'scared of', vi: 'sợ hãi — scared of (hoảng sợ điều gì)', explanation: 'Tính từ "scared" đi với "of": scared of = sợ hãi điều gì. (from/at/by không dùng sau scared ở nghĩa này.)' },
  { id: 'pp-185', cat: 'adj', q: 'I believe she is fully capable ___ leading the whole team.', options: ['of', 'in', 'for', 'to'], correct: 0, phrase: 'capable of', vi: 'có khả năng — capable of (đủ năng lực làm việc gì)', explanation: 'Tính từ "capable" đi với "of": capable of = có khả năng làm việc gì. (to/for/in không kết hợp với capable.)' },
  { id: 'pp-186', cat: 'adj', q: 'The classroom was full ___ noisy students after the lunch break.', options: ['of', 'in', 'with', 'by'], correct: 0, phrase: 'full of', vi: 'đầy — full of (chứa đầy, tràn đầy)', explanation: 'Tính từ "full" đi với "of": full of = đầy, chứa đầy. (with/in/by không dùng sau full ở nghĩa này.)' },
  { id: 'pp-187', cat: 'adj', q: 'I am really tired ___ hearing the same excuse every single day.', options: ['with', 'at', 'of', 'from'], correct: 2, phrase: 'tired of', vi: 'chán ngán, phát ngấy — tired of (mệt mỏi vì cái gì đó lặp lại)', explanation: 'Tính từ "tired" mang nghĩa "chán" luôn đi với "of": be tired of something = chán ngán việc gì. (with/from/at không dùng theo nghĩa này.)' },
  { id: 'pp-188', cat: 'adj', q: 'Every driver should be aware ___ the dangers of using a phone.', options: ['about', 'on', 'with', 'of'], correct: 3, phrase: 'aware of', vi: 'nhận thức, ý thức được — aware of (biết rõ về điều gì)', explanation: 'Tính từ "aware" luôn đi với "of": be aware of something = ý thức/biết về điều gì. (with/about/on không kết hợp với aware.)' },
  { id: 'pp-189', cat: 'adj', q: 'He felt deeply ashamed ___ the way he had treated his friends.', options: ['at', 'with', 'for', 'of'], correct: 3, phrase: 'ashamed of', vi: 'xấu hổ, hổ thẹn về — ashamed of (cảm thấy nhục nhã vì điều gì)', explanation: 'Tính từ "ashamed" luôn đi với "of": be ashamed of something = xấu hổ về điều gì. (for/at/with không dùng với ashamed.)' },
  { id: 'pp-190', cat: 'adj', q: 'She is completely fed up ___ his constant complaining about work.', options: ['by', 'with', 'about', 'of'], correct: 1, phrase: 'fed up with', vi: 'chán ngấy, phát ngán với — fed up with (quá mệt mỏi vì điều gì)', explanation: 'Cụm "fed up" luôn đi với "with": be fed up with something = chán ngấy với điều gì. (of/about/by không kết hợp với fed up.)' },
  { id: 'pp-191', cat: 'adj', q: 'The students grew bored ___ the long, repetitive grammar lesson.', options: ['at', 'from', 'with', 'of'], correct: 2, phrase: 'bored with', vi: 'chán, buồn chán với — bored with (mất hứng thú vì điều gì)', explanation: 'Tính từ "bored" thường đi với "with": be bored with something = chán với điều gì. (at/from không dùng; "of" ít trang trọng hơn.)' },
  { id: 'pp-192', cat: 'adj', q: 'The teacher was very pleased ___ her students\' progress this term.', options: ['for', 'at', 'with', 'of'], correct: 2, phrase: 'pleased with', vi: 'hài lòng, vui mừng với — pleased with (cảm thấy vừa ý về điều gì)', explanation: 'Tính từ "pleased" đi với "with" khi nói về kết quả/người: be pleased with something. (at/for/of không phù hợp ở đây.)' },
  { id: 'pp-193', cat: 'adj', q: 'Customers were not satisfied ___ the slow service at the new restaurant.', options: ['by', 'for', 'of', 'with'], correct: 3, phrase: 'satisfied with', vi: 'hài lòng, thỏa mãn với — satisfied with (cảm thấy đủ, vừa ý về điều gì)', explanation: 'Tính từ "satisfied" luôn đi với "with": be satisfied with something = hài lòng với điều gì. (of/by/for không kết hợp với satisfied.)' },
  { id: 'pp-194', cat: 'adj', q: 'We were quite disappointed ___ the hotel room we had booked online.', options: ['for', 'at', 'with', 'of'], correct: 2, phrase: 'disappointed with', vi: 'thất vọng với — disappointed with (cảm thấy hụt hẫng về điều gì)', explanation: 'Tính từ "disappointed" đi với "with" (hoặc in) trước danh từ: be disappointed with something. (of/for/at không dùng theo cách này.)' },
  { id: 'pp-195', cat: 'adj', q: 'My mother was angry ___ me for coming home so late last night.', options: ['with', 'to', 'on', 'of'], correct: 0, phrase: 'angry with', vi: 'tức giận với (ai đó) — angry with (giận một người về điều gì)', explanation: 'Tính từ "angry" đi với "with" khi giận một người: be angry with somebody. (to/of/on không dùng với angry trong nghĩa này.)' },
  { id: 'pp-196', cat: 'adj', q: 'The manager seemed annoyed ___ the staff who arrived late again.', options: ['for', 'at', 'with', 'of'], correct: 2, phrase: 'annoyed with', vi: 'bực mình, khó chịu với (ai) — annoyed with (cảm thấy phiền vì một người)', explanation: 'Tính từ "annoyed" đi với "with" khi nói về một người: be annoyed with somebody. (of/for không dùng; "at" dùng cho sự việc, không cho người ở đây.)' },
  { id: 'pp-197', cat: 'adj', q: 'The manager was busy ___ paperwork all morning and missed the meeting.', options: ['in', 'at', 'on', 'with'], correct: 3, phrase: 'busy with', vi: 'bận rộn với — busy with (đang mắc bận làm việc gì)', explanation: 'Tính từ "busy" đi với "with": busy with something = bận rộn với việc gì. (at/on/in không dùng với busy theo nghĩa này.)' },
  { id: 'pp-198', cat: 'adj', q: 'She is already familiar ___ the new software after one week of training.', options: ['of', 'in', 'with', 'to'], correct: 2, phrase: 'familiar with', vi: 'quen thuộc với — familiar with (đã biết rõ, thông thạo việc gì)', explanation: '"Familiar with" = quen thuộc, biết rõ về cái gì. (familiar to ai đó mới đúng cấu trúc khác; of/in không kết hợp với familiar.)' },
  { id: 'pp-199', cat: 'adj', q: 'The young teacher is very popular ___ her students because she is funny.', options: ['on', 'for', 'to', 'with'], correct: 3, phrase: 'popular with', vi: 'được yêu thích bởi — popular with (được nhiều người ưa chuộng)', explanation: '"Popular with" = được lòng, được yêu thích bởi một nhóm người. (to/for không dùng; among có thể gần nghĩa nhưng cấu trúc chuẩn ở đây là with.)' },
  { id: 'pp-200', cat: 'adj', q: 'A good nurse must be patient ___ elderly patients who move slowly.', options: ['for', 'at', 'to', 'with'], correct: 3, phrase: 'patient with', vi: 'kiên nhẫn với — patient with (nhẫn nại đối với ai)', explanation: '"Patient with" = kiên nhẫn với ai/cái gì. (for/to/at không kết hợp với patient theo nghĩa này.)' },
  { id: 'pp-201', cat: 'adj', q: 'He felt completely content ___ his simple life in the countryside.', options: ['for', 'at', 'with', 'of'], correct: 2, phrase: 'content with', vi: 'hài lòng với — content with (thỏa mãn, bằng lòng với điều gì)', explanation: '"Content with" = hài lòng, thỏa mãn với cái gì. (of/at/for không dùng với content.)' },
  { id: 'pp-202', cat: 'adj', q: 'The beach was crowded ___ tourists during the long summer holiday.', options: ['by', 'with', 'in', 'of'], correct: 1, phrase: 'crowded with', vi: 'đông nghịt — crowded with (chật kín, đầy ắp người/vật)', explanation: '"Crowded with" = đông nghịt, chật kín cái gì. (by/of/in không dùng để chỉ thứ làm cho đông đúc.)' },
  { id: 'pp-203', cat: 'adj', q: 'My aunt has been married ___ a doctor for almost twenty years.', options: ['to', 'for', 'of', 'with'], correct: 0, phrase: 'married to', vi: 'kết hôn với — married to (cưới, là vợ/chồng của ai)', explanation: '"Married to" = kết hôn với ai. (married with thường chỉ "có con"; for/of không dùng với married.)' },
  { id: 'pp-204', cat: 'adj', q: 'Your handwriting is very similar ___ your brother\'s, so I confused them.', options: ['with', 'than', 'as', 'to'], correct: 3, phrase: 'similar to', vi: 'giống với — similar to (tương tự, gần giống cái gì)', explanation: '"Similar to" = giống, tương tự với cái gì. (with/as/than không kết hợp với similar.)' },
  { id: 'pp-205', cat: 'adj', q: 'Please be kind ___ animals and never leave them hungry or cold.', options: ['of', 'to', 'for', 'with'], correct: 1, phrase: 'kind to', vi: 'tử tế với — kind to (đối xử tốt, dễ thương với ai)', explanation: '"Kind to" = tử tế, tốt bụng với ai. (with/for không dùng; "kind of" có nghĩa khác là "loại của".)' },
  { id: 'pp-206', cat: 'adj', q: 'It is very rude ___ strangers if you push past them without saying sorry.', options: ['with', 'for', 'at', 'to'], correct: 3, phrase: 'rude to', vi: 'thô lỗ với — rude to (cư xử khiếm nhã với ai)', explanation: '"Rude to" = thô lỗ, bất lịch sự với ai. (with/at/for không kết hợp với rude theo nghĩa này.)' },
  { id: 'pp-207', cat: 'adj', q: 'You should always be polite ___ your teachers and elderly people.', options: ['with', 'to', 'at', 'for'], correct: 1, phrase: 'polite to', vi: 'lịch sự với — polite to (cư xử nhã nhặn với ai)', explanation: 'Tính từ "polite" đi với giới từ "to": polite to somebody = lịch sự với ai. (with/at/for không dùng sau polite trong nghĩa này.)' },
  { id: 'pp-208', cat: 'adj', q: 'Her new house is very close ___ the train station and the park.', options: ['with', 'on', 'at', 'to'], correct: 3, phrase: 'close to', vi: 'gần — close to (gần gũi, sát với cái gì/ai)', explanation: 'Tính từ "close" đi với "to": close to something = gần với cái gì. (at/with/on không kết hợp với close.)' },
  { id: 'pp-209', cat: 'adj', q: 'Many health problems are directly related ___ a poor and unhealthy diet.', options: ['for', 'to', 'of', 'with'], correct: 1, phrase: 'related to', vi: 'liên quan đến — related to (có liên hệ với cái gì)', explanation: 'Tính từ "related" đi với "to": related to something = liên quan đến cái gì. (with/of/for không dùng sau related.)' },
  { id: 'pp-210', cat: 'adj', q: 'My little brother is completely addicted ___ playing video games all night.', options: ['to', 'on', 'in', 'with'], correct: 0, phrase: 'addicted to', vi: 'nghiện — addicted to (nghiện cái gì)', explanation: 'Tính từ "addicted" luôn đi với "to": addicted to something = nghiện cái gì. (on/with/in không kết hợp với addicted.)' },
  { id: 'pp-211', cat: 'adj', q: 'After living abroad, she became accustomed ___ the cold winter weather.', options: ['with', 'of', 'at', 'to'], correct: 3, phrase: 'accustomed to', vi: 'quen với — accustomed to (đã quen với cái gì)', explanation: 'Tính từ "accustomed" đi với "to": accustomed to something = quen với cái gì. (with/at/of không dùng sau accustomed.)' },
  { id: 'pp-212', cat: 'adj', q: 'Most local residents are strongly opposed ___ building the new factory here.', options: ['with', 'for', 'to', 'against'], correct: 2, phrase: 'opposed to', vi: 'phản đối — opposed to (chống lại, phản đối cái gì)', explanation: 'Tính từ "opposed" đi với "to": opposed to something = phản đối cái gì. (against/with/for không kết hợp với opposed.)' },
  { id: 'pp-213', cat: 'adj', q: 'The young nurse is completely devoted ___ caring for her sick patients.', options: ['to', 'for', 'on', 'with'], correct: 0, phrase: 'devoted to', vi: 'tận tụy với — devoted to (hết lòng vì ai/cái gì)', explanation: 'Tính từ "devoted" đi với "to": devoted to something = tận tụy, hết lòng với cái gì. (with/on/for không dùng sau devoted.)' },
  { id: 'pp-214', cat: 'adj', q: 'I cannot eat peanuts because I am seriously allergic ___ them.', options: ['to', 'of', 'with', 'from'], correct: 0, phrase: 'allergic to', vi: 'dị ứng với — allergic to (bị dị ứng với cái gì)', explanation: 'Tính từ "allergic" đi với "to": allergic to something = dị ứng với cái gì. (with/of/from không kết hợp với allergic.)' },
  { id: 'pp-215', cat: 'adj', q: 'This new model is far superior ___ the old one in every way.', options: ['to', 'from', 'over', 'than'], correct: 0, phrase: 'superior to', vi: 'vượt trội hơn — superior to (tốt hơn, hơn hẳn cái gì)', explanation: 'Tính từ "superior" đi với "to" (không phải "than"): superior to = vượt trội hơn. (than/over/from không dùng sau superior.)' },
  { id: 'pp-216', cat: 'adj', q: 'He always feels inferior ___ his more successful older brother.', options: ['than', 'to', 'with', 'of'], correct: 1, phrase: 'inferior to', vi: 'kém hơn, thua kém — inferior to (thấp kém hơn ai/cái gì)', explanation: 'Tính từ "inferior" đi với "to" (không phải "than"): inferior to = kém hơn. (than/with/of không kết hợp với inferior.)' },
  { id: 'pp-217', cat: 'adj', q: 'A good employee stays loyal ___ the company during hard times.', options: ['to', 'with', 'for', 'of'], correct: 0, phrase: 'loyal to', vi: 'trung thành với — loyal to (tận tụy, không phản bội)', explanation: 'Tính từ "loyal" luôn đi với "to": loyal to someone/something = trung thành với ai/cái gì. (with/for/of không kết hợp với loyal.)' },
  { id: 'pp-218', cat: 'adj', q: 'I am deeply grateful ___ the teacher who helped me succeed.', options: ['to', 'at', 'with', 'for'], correct: 0, phrase: 'grateful to', vi: 'biết ơn (ai) — grateful to (cảm kích với người nào đó)', explanation: 'Khi cảm ơn một NGƯỜI, "grateful" đi với "to": grateful to somebody = biết ơn ai. (Dùng "for" cho việc/lý do, không phải cho người; with/at sai.)' },
  { id: 'pp-219', cat: 'adj', q: 'The manager is responsible ___ training all the new staff members.', options: ['with', 'for', 'to', 'of'], correct: 1, phrase: 'responsible for', vi: 'chịu trách nhiệm về — responsible for (có nghĩa vụ với việc gì)', explanation: 'Tính từ "responsible" đi với "for": responsible for something = chịu trách nhiệm về việc gì. (of/to/with không kết hợp với responsible theo nghĩa này.)' },
  { id: 'pp-220', cat: 'adj', q: 'This small town is famous ___ its delicious seafood and beaches.', options: ['of', 'for', 'with', 'by'], correct: 1, phrase: 'famous for', vi: 'nổi tiếng về — famous for (được biết đến nhờ điều gì)', explanation: 'Tính từ "famous" đi với "for": famous for something = nổi tiếng về cái gì. (of/with/by không dùng với famous.)' },
  { id: 'pp-221', cat: 'adj', q: 'She felt sorry ___ the homeless man standing in the cold rain.', options: ['with', 'about', 'to', 'for'], correct: 3, phrase: 'sorry for', vi: 'thương cảm / tiếc cho — sorry for (cảm thấy thông cảm với ai)', explanation: 'Khi thương cảm cho ai, "sorry" đi với "for": feel sorry for somebody = thương cảm cho ai. (to/about/with không phù hợp ở đây.)' },
  { id: 'pp-222', cat: 'adj', q: 'The students are now fully ready ___ their final examinations next week.', options: ['for', 'at', 'to', 'with'], correct: 0, phrase: 'ready for', vi: 'sẵn sàng cho — ready for (chuẩn bị xong cho việc gì)', explanation: 'Trước một DANH TỪ, "ready" đi với "for": ready for something = sẵn sàng cho việc gì. ("ready to" dùng trước động từ; with/at sai.)' },
  { id: 'pp-223', cat: 'adj', q: 'This colourful movie is not really suitable ___ very young children.', options: ['of', 'with', 'to', 'for'], correct: 3, phrase: 'suitable for', vi: 'phù hợp với — suitable for (thích hợp cho ai/việc gì)', explanation: 'Tính từ "suitable" đi với "for": suitable for somebody/something = phù hợp với ai/cái gì. (to/with/of không kết hợp với suitable.)' },
  { id: 'pp-224', cat: 'adj', q: 'After five years of work, she became eligible ___ a promotion.', options: ['for', 'with', 'of', 'to'], correct: 0, phrase: 'eligible for', vi: 'đủ điều kiện cho — eligible for (có đủ tư cách nhận gì)', explanation: 'Tính từ "eligible" đi với "for": eligible for something = đủ điều kiện/tư cách cho việc gì. (to/of/with không dùng với eligible.)' },
  { id: 'pp-225', cat: 'adj', q: 'The young players were eager ___ a chance to prove themselves.', options: ['with', 'to', 'at', 'for'], correct: 3, phrase: 'eager for', vi: 'khao khát / mong muốn — eager for (rất muốn có điều gì)', explanation: 'Trước một DANH TỪ, "eager" đi với "for": eager for something = khao khát điều gì. ("eager to" đi trước động từ; with/at sai.)' },
  { id: 'pp-226', cat: 'adj', q: 'He was late ___ the meeting because the traffic was terrible.', options: ['at', 'to', 'for', 'on'], correct: 2, phrase: 'late for', vi: 'trễ / muộn (giờ) — late for (đến muộn một sự kiện)', explanation: 'Tính từ "late" đi với "for": late for something = đến trễ một việc/sự kiện. (to/at/on không kết hợp với late theo nghĩa này.)' },
  { id: 'pp-227', cat: 'adj', q: 'She felt very anxious ___ her exam results all week long.', options: ['for', 'about', 'with', 'of'], correct: 1, phrase: 'anxious about', vi: 'lo lắng về — anxious about (bồn chồn, bất an về việc gì)', explanation: 'Tính từ "anxious" đi với "about": anxious about something = lo lắng về điều gì. (of/for/with không kết hợp với anxious theo nghĩa này.)' },
  { id: 'pp-228', cat: 'adj', q: 'My parents are always worried ___ my safety when I travel alone.', options: ['on', 'about', 'for', 'of'], correct: 1, phrase: 'worried about', vi: 'lo lắng về — worried about (bận tâm, lo sợ cho việc gì)', explanation: 'Tính từ "worried" luôn đi với "about": worried about something = lo lắng về điều gì. (for/of/on không dùng với worried.)' },
  { id: 'pp-229', cat: 'adj', q: 'The children were really excited ___ the trip to the zoo.', options: ['of', 'about', 'with', 'at'], correct: 1, phrase: 'excited about', vi: 'hào hứng về — excited about (phấn khích, mong chờ điều gì)', explanation: 'Tính từ "excited" đi với "about": excited about something = hào hứng về điều gì. (of/with/at không kết hợp với excited theo nghĩa này.)' },
  { id: 'pp-230', cat: 'adj', q: 'He was quite nervous ___ his first job interview tomorrow morning.', options: ['for', 'about', 'of', 'to'], correct: 1, phrase: 'nervous about', vi: 'hồi hộp về — nervous about (lo lắng, căng thẳng về việc gì)', explanation: 'Tính từ "nervous" đi với "about": nervous about something = hồi hộp về điều gì. (of/for/to không dùng với nervous theo nghĩa này.)' },
  { id: 'pp-231', cat: 'adj', q: 'The student was curious ___ how the ancient pyramids were actually built.', options: ['in', 'about', 'on', 'of'], correct: 1, phrase: 'curious about', vi: 'tò mò về — curious about (muốn biết, hiếu kỳ về việc gì)', explanation: 'Tính từ "curious" đi với "about": curious about something = tò mò về điều gì. (of/in/on không kết hợp với curious.)' },
  { id: 'pp-232', cat: 'adj', q: 'Our teacher is very enthusiastic ___ teaching us new English words.', options: ['for', 'of', 'with', 'about'], correct: 3, phrase: 'enthusiastic about', vi: 'nhiệt tình với — enthusiastic about (hăng hái, say mê về việc gì)', explanation: 'Tính từ "enthusiastic" đi với "about": enthusiastic about something = nhiệt tình với điều gì. (for/with/of không dùng với enthusiastic.)' },
  { id: 'pp-233', cat: 'adj', q: 'Many people are deeply concerned ___ the rising levels of pollution.', options: ['about', 'of', 'for', 'to'], correct: 0, phrase: 'concerned about', vi: 'quan tâm, lo ngại về — concerned about (bận tâm về vấn đề gì)', explanation: 'Tính từ "concerned" mang nghĩa lo ngại đi với "about": concerned about something = lo lắng về điều gì. (for/of/to không phù hợp ở đây.)' },
  { id: 'pp-234', cat: 'adj', q: 'I am not very happy ___ the decision the manager made yesterday.', options: ['of', 'by', 'about', 'for'], correct: 2, phrase: 'happy about', vi: 'vui, hài lòng về — happy about (hài lòng với một việc cụ thể)', explanation: 'Tính từ "happy" đi với "about" khi nói về một sự việc: happy about something = hài lòng về điều gì. (of/for không kết hợp ở đây.)' },
  { id: 'pp-235', cat: 'adj', q: 'She is really serious ___ becoming a doctor after she finishes school.', options: ['in', 'about', 'on', 'of'], correct: 1, phrase: 'serious about', vi: 'nghiêm túc về — serious about (quyết tâm, coi trọng việc gì)', explanation: 'Tính từ "serious" đi với "about": serious about something = nghiêm túc về điều gì. (in/of/on không dùng với serious theo nghĩa này.)' },
  { id: 'pp-236', cat: 'adj', q: 'Everyone felt sad ___ the loss of their beloved old teacher.', options: ['about', 'for', 'of', 'with'], correct: 0, phrase: 'sad about', vi: 'buồn về — sad about (buồn bã, đau lòng về việc gì)', explanation: 'Tính từ "sad" đi với "about" khi nói về một sự việc: sad about something = buồn về điều gì. (for/of/with không phù hợp ở đây.)' },
  { id: 'pp-237', cat: 'adj', q: 'Are you absolutely sure ___ the answer before you write it down?', options: ['to', 'in', 'of', 'at'], correct: 2, phrase: 'sure of', vi: 'chắc chắn về — sure of (tin chắc điều gì)', explanation: 'Tính từ "sure" đi với "of": be sure of something = chắc chắn về điều gì. (at/in/to không kết hợp với sure theo nghĩa này.)' },
  { id: 'pp-238', cat: 'adj', q: 'The detective was certain ___ the suspect\'s guilt after the trial.', options: ['of', 'on', 'at', 'for'], correct: 0, phrase: 'certain of', vi: 'chắc chắn về — certain of (đoan chắc điều gì)', explanation: 'Tính từ "certain" đi với "of": be certain of something = chắc chắn về điều gì. (at/on/for không dùng với certain.)' },
  { id: 'pp-239', cat: 'adj', q: 'Our team felt confident ___ victory after months of hard training.', options: ['at', 'of', 'to', 'in'], correct: 1, phrase: 'confident of', vi: 'tự tin vào — confident of (tin tưởng vào kết quả)', explanation: 'Tính từ "confident" đi với "of" khi nói về kết quả: confident of success = tự tin vào thành công. (in/at/to không hợp ở đây.)' },
  { id: 'pp-240', cat: 'adj', q: 'My little brother is absolutely terrified ___ spiders and dark rooms.', options: ['by', 'of', 'at', 'from'], correct: 1, phrase: 'terrified of', vi: 'sợ hãi — terrified of (kinh hãi điều gì)', explanation: 'Tính từ "terrified" đi với "of": be terrified of something = rất sợ điều gì. (from/by/at không kết hợp với terrified.)' },
  { id: 'pp-241', cat: 'adj', q: 'The guard grew suspicious ___ the stranger waiting near the back door.', options: ['at', 'with', 'of', 'about'], correct: 2, phrase: 'suspicious of', vi: 'nghi ngờ — suspicious of (ngờ vực ai/điều gì)', explanation: 'Tính từ "suspicious" đi với "of": be suspicious of someone = nghi ngờ ai. (about/at/with không chuẩn với suspicious.)' },
  { id: 'pp-242', cat: 'adj', q: 'She was secretly envious ___ her friend\'s brand-new sports car.', options: ['for', 'to', 'at', 'of'], correct: 3, phrase: 'envious of', vi: 'ghen tị với — envious of (đố kỵ điều gì)', explanation: 'Tính từ "envious" đi với "of": be envious of something = ghen tị với điều gì. (at/for/to không dùng với envious.)' },
  { id: 'pp-243', cat: 'adj', q: 'A good teacher should be tolerant ___ students who make honest mistakes.', options: ['to', 'of', 'for', 'with'], correct: 1, phrase: 'tolerant of', vi: 'khoan dung với — tolerant of (chịu đựng, bao dung)', explanation: 'Tính từ "tolerant" đi với "of": be tolerant of something = khoan dung với điều gì. (to/with/for không kết hợp với tolerant.)' },
  { id: 'pp-244', cat: 'adj', q: 'The court found the man guilty ___ stealing money from the company.', options: ['with', 'about', 'of', 'for'], correct: 2, phrase: 'guilty of', vi: 'có tội về — guilty of (phạm tội điều gì)', explanation: 'Tính từ "guilty" đi với "of": be guilty of something = có tội về điều gì. (for/with/about không dùng với guilty theo nghĩa này.)' },
  { id: 'pp-245', cat: 'adj', q: 'She suddenly became conscious ___ everyone staring at her new haircut.', options: ['of', 'at', 'about', 'to'], correct: 0, phrase: 'conscious of', vi: 'ý thức về — conscious of (nhận biết điều gì)', explanation: 'Tính từ "conscious" đi với "of": be conscious of something = ý thức/nhận biết về điều gì. (about/at/to không kết hợp với conscious.)' },
  { id: 'pp-246', cat: 'adj', q: 'Many old sailors were fearful ___ storms appearing far out at sea.', options: ['of', 'from', 'at', 'with'], correct: 0, phrase: 'fearful of', vi: 'sợ hãi — fearful of (lo sợ điều gì)', explanation: 'Tính từ "fearful" đi với "of": be fearful of something = sợ điều gì. (from/at/with không dùng với fearful.)' },
  { id: 'pp-247', cat: 'adj', q: 'Many voters were highly critical ___ the new tax policy.', options: ['to', 'on', 'about', 'of'], correct: 3, phrase: 'critical of', vi: 'chỉ trích, phê phán — critical of (không hài lòng với điều gì)', explanation: 'Tính từ "critical" đi với "of": critical of something = chỉ trích, phê phán điều gì. (to/on/about không kết hợp với critical theo nghĩa này.)' },
  { id: 'pp-248', cat: 'adj', q: 'As an adult, she became completely independent ___ her parents.', options: ['from', 'to', 'on', 'of'], correct: 3, phrase: 'independent of', vi: 'độc lập với — independent of (không phụ thuộc vào)', explanation: 'Tính từ "independent" đi với "of": independent of someone = độc lập, không phụ thuộc vào ai. (from/on/to không dùng với independent.)' },
  { id: 'pp-249', cat: 'adj', q: 'Arriving late is so typical ___ him on important days.', options: ['to', 'for', 'with', 'of'], correct: 3, phrase: 'typical of', vi: 'điển hình, đặc trưng cho — typical of (đúng kiểu của ai/cái gì)', explanation: 'Tính từ "typical" đi với "of": typical of someone = điển hình, đúng kiểu của ai. (for/to/with không kết hợp với typical.)' },
  { id: 'pp-250', cat: 'adj', q: 'We are still short ___ money to buy the new car.', options: ['in', 'on', 'at', 'of'], correct: 3, phrase: 'short of', vi: 'thiếu, không đủ — short of (không có đủ cái gì)', explanation: 'Tính từ "short" đi với "of": short of something = thiếu, không đủ cái gì. (on/in/at không dùng với short theo nghĩa thiếu hụt.)' },
  { id: 'pp-251', cat: 'adj', q: 'Life in the countryside is quite different ___ life in the city.', options: ['with', 'at', 'by', 'from'], correct: 3, phrase: 'different from', vi: 'khác với — different from (không giống cái gì)', explanation: 'Tính từ "different" đi với "from": different from something = khác với cái gì. (than/to/with không phải dạng chuẩn dùng với different.)' },
  { id: 'pp-252', cat: 'adj', q: 'He was absent ___ work for three days because of illness.', options: ['of', 'from', 'in', 'at'], correct: 1, phrase: 'absent from', vi: 'vắng mặt khỏi — absent from (không có mặt ở đâu)', explanation: 'Tính từ "absent" đi với "from": absent from somewhere = vắng mặt khỏi nơi nào. (of/in/at không kết hợp với absent.)' },
  { id: 'pp-253', cat: 'adj', q: 'Inside the shelter, the villagers felt safe ___ the storm.', options: ['from', 'with', 'of', 'by'], correct: 0, phrase: 'safe from', vi: 'an toàn, được bảo vệ khỏi — safe from (không bị nguy hiểm bởi)', explanation: 'Tính từ "safe" đi với "from": safe from something = an toàn, được bảo vệ khỏi mối nguy. (of/by/with không dùng với safe theo nghĩa này.)' },
  { id: 'pp-254', cat: 'adj', q: 'After treatment, she was finally free ___ pain and stress.', options: ['at', 'with', 'from', 'to'], correct: 2, phrase: 'free from', vi: 'thoát khỏi, không còn — free from (không bị cái gì làm ảnh hưởng)', explanation: 'Tính từ "free" đi với "from": free from something = thoát khỏi, không còn bị điều gì. (of cũng gặp nhưng with/at thì không; ở đây "from" là chuẩn.)' },
  { id: 'pp-255', cat: 'adj', q: 'Eating plenty of vegetables is very good ___ your health.', options: ['with', 'at', 'for', 'to'], correct: 2, phrase: 'good for', vi: 'tốt cho — good for (có lợi cho cái gì)', explanation: 'Tính từ "good" đi với "for" khi nói có lợi: good for something = tốt cho cái gì. (at đi với kỹ năng, còn to/with không hợp ở đây.)' },
  { id: 'pp-256', cat: 'adj', q: 'Smoking too many cigarettes is extremely bad ___ your lungs.', options: ['to', 'on', 'at', 'for'], correct: 3, phrase: 'bad for', vi: 'có hại cho — bad for (gây hại cho cái gì)', explanation: 'Tính từ "bad" đi với "for" khi nói có hại: bad for something = có hại cho cái gì. (at đi với kỹ năng kém, còn to/on không hợp ở đây.)' },
  { id: 'pp-257', cat: 'adj', q: 'Fresh water is absolutely essential ___ the survival of all living things.', options: ['at', 'for', 'of', 'with'], correct: 1, phrase: 'essential for', vi: 'thiết yếu cho — essential for (rất cần thiết để có)', explanation: 'Tính từ "essential" đi với "for": essential for something = thiết yếu cho việc gì. (to/of/with không dùng với essential theo nghĩa này.)' },
  { id: 'pp-258', cat: 'adj', q: 'A balanced diet is necessary ___ good health and strong bones.', options: ['with', 'for', 'at', 'of'], correct: 1, phrase: 'necessary for', vi: 'cần thiết cho — necessary for (đòi hỏi phải có để)', explanation: 'Tính từ "necessary" kết hợp với "for": necessary for something = cần thiết cho việc gì. (of/at không đi với necessary.)' },
  { id: 'pp-259', cat: 'adj', q: 'We are truly grateful ___ all the help you gave us last year.', options: ['about', 'for', 'to', 'of'], correct: 1, phrase: 'grateful for', vi: 'biết ơn vì — grateful for (cảm kích về điều gì)', explanation: 'Khi cảm ơn về một việc, "grateful" đi với "for": grateful for something. (Dùng "to" với người, không với việc; of/about sai.)' },
  { id: 'pp-260', cat: 'adj', q: 'She felt deeply thankful ___ the kindness of the strangers who helped her.', options: ['of', 'to', 'for', 'about'], correct: 2, phrase: 'thankful for', vi: 'biết ơn vì — thankful for (cảm thấy biết ơn về điều gì)', explanation: 'Tính từ "thankful" đi với "for": thankful for something = biết ơn vì điều gì. (of/about/to không kết hợp với thankful theo nghĩa này.)' },
  { id: 'pp-261', cat: 'adj', q: 'Many small villages are still completely dependent ___ farming for their income.', options: ['on', 'to', 'for', 'of'], correct: 0, phrase: 'dependent on', vi: 'phụ thuộc vào — dependent on (lệ thuộc vào)', explanation: 'Tính từ "dependent" đi với "on": dependent on something = phụ thuộc vào việc gì. (of/to/for không dùng với dependent.)' },
  { id: 'pp-262', cat: 'adj', q: 'My younger brother has always been very keen ___ playing football.', options: ['for', 'in', 'on', 'at'], correct: 2, phrase: 'keen on', vi: 'hứng thú với, mê — keen on (thích, đam mê việc gì)', explanation: 'Tính từ "keen" đi với "on": keen on something = thích, mê việc gì. (at/in/for không kết hợp với keen.)' },
  { id: 'pp-263', cat: 'adj', q: 'The popular new film is based ___ a true story from the war.', options: ['in', 'on', 'at', 'of'], correct: 1, phrase: 'based on', vi: 'dựa trên — based on (lấy làm cơ sở từ)', explanation: 'Tính từ/quá khứ phân từ "based" đi với "on": based on something = dựa trên việc gì. (in không dùng; "upon" trang trọng nhưng "on" là chuẩn thông dụng.)' },
  { id: 'pp-264', cat: 'adj', q: 'The thieves were clearly intent ___ stealing the jewels from the museum.', options: ['to', 'at', 'with', 'on'], correct: 3, phrase: 'intent on', vi: 'quyết tâm, chăm chú vào — intent on (một lòng muốn làm gì)', explanation: 'Tính từ "intent" đi với "on": intent on doing something = quyết tâm làm việc gì. (at/to/with không dùng với intent.)' },
  { id: 'pp-265', cat: 'adj', q: 'During the exam she stayed completely focused ___ answering every question carefully.', options: ['for', 'in', 'on', 'at'], correct: 2, phrase: 'focused on', vi: 'tập trung vào — focused on (chú tâm vào việc gì)', explanation: 'Tính từ "focused" đi với "on": focused on something = tập trung vào việc gì. (at/in/for không kết hợp với focused.)' },
  { id: 'pp-266', cat: 'adj', q: 'You shouldn\'t be so hard ___ yourself when you make a small mistake.', options: ['at', 'to', 'with', 'on'], correct: 3, phrase: 'hard on', vi: 'khắt khe với — hard on (đối xử nghiêm khắc với)', explanation: 'Cụm "hard on" nghĩa là khắt khe với ai: be hard on someone. (to/with/at không dùng để diễn đạt sự nghiêm khắc này.)' },
  { id: 'pp-267', cat: 'adj', q: 'Several students were involved ___ organizing the school charity event last week.', options: ['with', 'at', 'on', 'in'], correct: 3, phrase: 'involved in', vi: 'tham gia vào — involved in (dính líu, liên quan đến)', explanation: 'Tính từ "involved" đi với "in": be involved in something = tham gia/dính líu vào việc gì. (on/at/with không dùng với involved theo nghĩa này.)' },
  { id: 'pp-268', cat: 'adj', q: 'Our new manager is highly experienced ___ handling difficult customer complaints.', options: ['for', 'on', 'in', 'at'], correct: 2, phrase: 'experienced in', vi: 'có kinh nghiệm về — experienced in (thành thạo, từng trải trong)', explanation: 'Tính từ "experienced" đi với "in": be experienced in something = có kinh nghiệm trong việc gì. (at/on/for không kết hợp với experienced ở đây.)' },
  { id: 'pp-269', cat: 'adj', q: 'After living in Paris for years, she became completely fluent ___ French.', options: ['on', 'with', 'at', 'in'], correct: 3, phrase: 'fluent in', vi: 'thông thạo (ngôn ngữ) — fluent in (nói trôi chảy)', explanation: 'Tính từ "fluent" đi với "in": be fluent in a language = thông thạo một ngôn ngữ. (at/on/with không dùng với fluent.)' },
  { id: 'pp-270', cat: 'adj', q: 'Fresh oranges and lemons are very rich ___ vitamin C and fibre.', options: ['at', 'of', 'in', 'with'], correct: 2, phrase: 'rich in', vi: 'giàu, nhiều (chất) — rich in (chứa nhiều)', explanation: 'Tính từ "rich" đi với "in": be rich in something = giàu/chứa nhiều thứ gì. (of/with/at không kết hợp với rich theo nghĩa này.)' },
  { id: 'pp-271', cat: 'adj', q: 'His latest essay was clearly lacking ___ detail and solid evidence.', options: ['on', 'of', 'with', 'in'], correct: 3, phrase: 'lacking in', vi: 'thiếu — lacking in (không có đủ)', explanation: 'Tính từ "lacking" đi với "in": be lacking in something = thiếu thứ gì. (of/with/on không dùng với lacking.)' },
  { id: 'pp-272', cat: 'adj', q: 'The team was finally successful ___ securing the funding they needed.', options: ['on', 'at', 'in', 'for'], correct: 2, phrase: 'successful in', vi: 'thành công trong — successful in (đạt được kết quả tốt)', explanation: 'Tính từ "successful" đi với "in": be successful in (doing) something = thành công trong việc gì. (at/on/for không kết hợp với successful ở đây.)' },
  { id: 'pp-273', cat: 'adj', q: 'Many elderly people are deficient ___ vitamin D during the winter months.', options: ['with', 'of', 'in', 'at'], correct: 2, phrase: 'deficient in', vi: 'thiếu hụt — deficient in (không đủ, thiếu)', explanation: 'Tính từ "deficient" đi với "in": be deficient in something = thiếu hụt thứ gì. (of/at/with không dùng với deficient.)' },
  { id: 'pp-274', cat: 'adj', q: 'The two scientists were deeply engaged ___ research on renewable energy.', options: ['at', 'with', 'on', 'in'], correct: 3, phrase: 'engaged in', vi: 'bận rộn với, tham gia vào — engaged in (dấn thân vào)', explanation: 'Tính từ "engaged" đi với "in": be engaged in something = bận rộn/tham gia vào việc gì. (on/with/at không kết hợp với engaged theo nghĩa này.)' },
  { id: 'pp-275', cat: 'adj', q: 'The little boy was so absorbed ___ his book that he forgot dinner.', options: ['at', 'in', 'on', 'by'], correct: 1, phrase: 'absorbed in', vi: 'mải mê, chăm chú vào — absorbed in (đắm chìm)', explanation: 'Tính từ "absorbed" đi với "in": be absorbed in something = mải mê/chăm chú vào việc gì. (by/at/on không dùng với absorbed ở nghĩa này.)' },
  { id: 'pp-276', cat: 'adj', q: 'My younger brother has always been brilliant ___ solving maths problems quickly.', options: ['at', 'in', 'with', 'on'], correct: 0, phrase: 'brilliant at', vi: 'rất giỏi về — brilliant at (xuất sắc trong)', explanation: 'Tính từ "brilliant" đi với "at": be brilliant at something = rất giỏi việc gì. (in/on/with không kết hợp với brilliant theo nghĩa này.)' },
  { id: 'pp-277', cat: 'adj', q: 'My brother is completely hopeless ___ remembering people\'s names at parties.', options: ['in', 'with', 'at', 'on'], correct: 2, phrase: 'hopeless at', vi: 'rất kém ở — hopeless at (dở tệ, vô vọng trong việc gì)', explanation: 'Tính từ "hopeless" đi với "at" để chỉ kỹ năng kém: hopeless at = rất dở việc gì. (in/on/with không dùng với hopeless theo nghĩa này.)' },
  { id: 'pp-278', cat: 'adj', q: 'She is very skilled ___ negotiating prices with stubborn local sellers.', options: ['for', 'at', 'on', 'to'], correct: 1, phrase: 'skilled at', vi: 'giỏi, thành thạo ở — skilled at (lành nghề trong việc gì)', explanation: 'Tính từ "skilled" đi với "at" để chỉ sự thành thạo: skilled at = giỏi việc gì. (on/for/to không kết hợp với skilled.)' },
  { id: 'pp-279', cat: 'adj', q: 'Only a few reporters were present ___ the private signing ceremony yesterday.', options: ['in', 'at', 'on', 'for'], correct: 1, phrase: 'present at', vi: 'có mặt tại — present at (hiện diện tại sự kiện)', explanation: 'Tính từ "present" đi với "at" để chỉ sự có mặt tại sự kiện: present at = có mặt tại. (in/on/for không dùng với present ở đây.)' },
  { id: 'pp-280', cat: 'adj', q: 'We were really surprised ___ how quickly the children learned the new song.', options: ['for', 'at', 'to', 'with'], correct: 1, phrase: 'surprised at', vi: 'ngạc nhiên về — surprised at (bất ngờ trước điều gì)', explanation: 'Tính từ "surprised" đi với "at" để chỉ sự ngạc nhiên: surprised at = ngạc nhiên trước điều gì. (for/with/to không dùng với surprised theo nghĩa này.)' },
  { id: 'pp-281', cat: 'adj', q: 'The tourists were amazed ___ the size of the ancient stone temple.', options: ['for', 'of', 'at', 'on'], correct: 2, phrase: 'amazed at', vi: 'kinh ngạc trước — amazed at (sửng sốt vì điều gì)', explanation: 'Tính từ "amazed" đi với "at" để chỉ sự kinh ngạc: amazed at = kinh ngạc trước điều gì. (of/on/for không kết hợp với amazed.)' },
  { id: 'pp-282', cat: 'adj', q: 'Everyone was astonished ___ the speed of the runner\'s final lap.', options: ['to', 'of', 'in', 'at'], correct: 3, phrase: 'astonished at', vi: 'sửng sốt trước — astonished at (kinh ngạc tột độ vì điều gì)', explanation: 'Tính từ "astonished" đi với "at" để chỉ sự sửng sốt: astonished at = sửng sốt trước điều gì. (by/in/to không dùng với astonished ở đây.)' },
  { id: 'pp-283', cat: 'adj', q: 'My grandmother has always been very good ___ small children and animals.', options: ['at', 'for', 'with', 'on'], correct: 2, phrase: 'good with', vi: 'giỏi xoay xở với — good with (khéo léo với ai/cái gì)', explanation: 'Cụm "good with" dùng để chỉ sự khéo léo khi tiếp xúc với người hay vật: good with = khéo với. (at/for/on không dùng trong nghĩa này.)' },
  { id: 'pp-284', cat: 'adj', q: 'Please be gentle ___ the puppy because it is still very young.', options: ['for', 'at', 'to', 'with'], correct: 3, phrase: 'gentle with', vi: 'nhẹ nhàng với — gentle with (đối xử dịu dàng với ai/cái gì)', explanation: 'Tính từ "gentle" đi với "with" để chỉ cách đối xử dịu dàng: gentle with = nhẹ nhàng với. (to/at/for không kết hợp với gentle ở đây.)' },
  { id: 'pp-285', cat: 'adj', q: 'Our new manager is remarkably generous ___ her time and helpful advice.', options: ['to', 'in', 'for', 'with'], correct: 3, phrase: 'generous with', vi: 'hào phóng với — generous with (rộng rãi, sẵn lòng cho cái gì)', explanation: 'Tính từ "generous" đi với "with" để chỉ sự rộng rãi về thứ gì: generous with = hào phóng với. (for/in/to không dùng với generous theo nghĩa này.)' },
  { id: 'pp-286', cat: 'adj', q: 'You should be careful ___ that knife because the blade is extremely sharp.', options: ['on', 'about', 'of', 'with'], correct: 3, phrase: 'careful with', vi: 'cẩn thận với — careful with (thận trọng khi dùng/giữ cái gì)', explanation: 'Tính từ "careful" đi với "with" để chỉ sự cẩn thận khi xử lý vật gì: careful with = cẩn thận với. (of/on/about không phù hợp ở đây.)' },
  { id: 'pp-287', cat: 'adj', q: 'She felt completely comfortable ___ her new colleagues after the first week.', options: ['in', 'on', 'with', 'at'], correct: 2, phrase: 'comfortable with', vi: 'thoải mái với — comfortable with (cảm thấy dễ chịu, không lo lắng về)', explanation: 'Tính từ "comfortable" đi với "with": comfortable with something/someone = thoải mái với ai/việc gì. (at/on/in không kết hợp với comfortable theo nghĩa này.)' },
  { id: 'pp-288', cat: 'adj', q: 'This new printer is fully compatible ___ all modern laptops and tablets.', options: ['to', 'for', 'with', 'on'], correct: 2, phrase: 'compatible with', vi: 'tương thích với — compatible with (phù hợp, hoạt động cùng được với)', explanation: 'Tính từ "compatible" luôn đi với "with": compatible with = tương thích với. (to/for/on không dùng với compatible.)' },
  { id: 'pp-289', cat: 'adj', q: 'His latest statement is not consistent ___ what he told us yesterday.', options: ['to', 'for', 'of', 'with'], correct: 3, phrase: 'consistent with', vi: 'nhất quán với — consistent with (phù hợp, không mâu thuẫn với)', explanation: 'Tính từ "consistent" đi với "with": consistent with = nhất quán/phù hợp với. (to/of/for không kết hợp với consistent.)' },
  { id: 'pp-290', cat: 'adj', q: 'They are truly blessed ___ three healthy and cheerful children.', options: ['in', 'with', 'by', 'of'], correct: 1, phrase: 'blessed with', vi: 'được ban cho — blessed with (may mắn có được điều tốt đẹp)', explanation: 'Tính từ "blessed" đi với "with": blessed with something = được ban tặng/may mắn có. (by/of/in không dùng trong cấu trúc này.)' },
  { id: 'pp-291', cat: 'adj', q: 'The teacher was delighted ___ the excellent results her students achieved.', options: ['with', 'for', 'to', 'at'], correct: 0, phrase: 'delighted with', vi: 'hài lòng với — delighted with (rất vui mừng, hài lòng về)', explanation: 'Tính từ "delighted" đi với "with" khi nói về kết quả/vật: delighted with = hài lòng, vui mừng với. (at/for/to không phù hợp ở đây.)' },
  { id: 'pp-292', cat: 'adj', q: 'The manager was very impressed ___ how quickly the team finished the project.', options: ['at', 'with', 'of', 'for'], correct: 1, phrase: 'impressed with', vi: 'ấn tượng với — impressed with (cảm thấy thán phục, đánh giá cao)', explanation: 'Tính từ "impressed" đi với "with" (hoặc by): impressed with = ấn tượng với. (of/at/for không kết hợp với impressed.)' },
  { id: 'pp-293', cat: 'adj', q: 'Over the years he became quite friendly ___ his next-door neighbours.', options: ['with', 'to', 'at', 'for'], correct: 0, phrase: 'friendly with', vi: 'thân thiết với — friendly with (có quan hệ thân thiện, gần gũi với)', explanation: 'Tính từ "friendly" đi với "with" khi chỉ quan hệ thân thiết: friendly with = thân với ai. (to/for/at không dùng với nghĩa này.)' },
  { id: 'pp-294', cat: 'adj', q: 'My little brother is completely obsessed ___ dinosaurs and space rockets.', options: ['on', 'of', 'about', 'with'], correct: 3, phrase: 'obsessed with', vi: 'ám ảnh/mê mẩn — obsessed with (bị cuốn hút, nghĩ về suốt)', explanation: 'Tính từ "obsessed" luôn đi với "with": obsessed with = mê mẩn, ám ảnh về. (on/about/of không kết hợp với obsessed.)' },
  { id: 'pp-295', cat: 'adj', q: 'The old man is deeply attached ___ the small house where he grew up.', options: ['with', 'on', 'to', 'of'], correct: 2, phrase: 'attached to', vi: 'gắn bó với — attached to (có tình cảm sâu sắc, quyến luyến)', explanation: 'Tính từ "attached" đi với "to": attached to = gắn bó/quyến luyến với. (with/on/of không dùng với attached theo nghĩa này.)' },
  { id: 'pp-296', cat: 'adj', q: 'Our company is fully committed ___ reducing waste and protecting the environment.', options: ['on', 'to', 'for', 'with'], correct: 1, phrase: 'committed to', vi: 'cam kết/tận tâm với — committed to (dốc lòng, dành trọn vào)', explanation: 'Tính từ "committed" đi với "to": committed to = cam kết/tận tâm với. (for/with/on không kết hợp với committed.)' },
  { id: 'pp-297', cat: 'adj', q: 'The young doctor is completely dedicated ___ helping poor families in the village.', options: ['to', 'on', 'with', 'for'], correct: 0, phrase: 'dedicated to', vi: 'tận tâm với, cống hiến cho — dedicated to (dành hết tâm sức cho)', explanation: 'Tính từ "dedicated" luôn đi với "to": dedicated to something/doing = tận tâm với, cống hiến cho việc gì. (for/on/with không kết hợp với dedicated.)' },
  { id: 'pp-298', cat: 'adj', q: 'Her eyes are very sensitive ___ bright sunlight after the surgery.', options: ['to', 'at', 'with', 'for'], correct: 0, phrase: 'sensitive to', vi: 'nhạy cảm với — sensitive to (dễ bị ảnh hưởng bởi)', explanation: 'Tính từ "sensitive" đi với "to": sensitive to something = nhạy cảm với, dễ bị tác động bởi cái gì. (with/for/at không dùng sau sensitive.)' },
  { id: 'pp-299', cat: 'adj', q: 'This quiet town is perfectly suited ___ people who dislike crowds.', options: ['on', 'to', 'with', 'at'], correct: 1, phrase: 'suited to', vi: 'phù hợp với, thích hợp cho — suited to (hợp với ai/việc gì)', explanation: 'Tính từ "suited" đi với "to": suited to something/somebody = phù hợp với, thích hợp cho. (for/on/with không kết hợp với suited.)' },
  { id: 'pp-300', cat: 'adj', q: 'People who skip breakfast are often more prone ___ headaches during the day.', options: ['on', 'for', 'of', 'to'], correct: 3, phrase: 'prone to', vi: 'dễ mắc, dễ bị — prone to (có xu hướng gặp phải)', explanation: 'Tính từ "prone" đi với "to": prone to something = dễ bị, dễ mắc phải cái gì. (on/of/for không dùng sau prone.)' },
  { id: 'pp-301', cat: 'adj', q: 'All ticket prices are subject ___ change without any prior notice.', options: ['to', 'for', 'with', 'by'], correct: 0, phrase: 'subject to', vi: 'phụ thuộc vào, có thể bị — subject to (chịu sự chi phối của)', explanation: 'Tính từ "subject" đi với "to": subject to something = phụ thuộc vào, có thể chịu sự thay đổi. (for/with/by không kết hợp với subject ở nghĩa này.)' },
  { id: 'pp-302', cat: 'noun', q: 'Nobody knows the real reason ___ his sudden decision to resign.', options: ['about', 'to', 'of', 'for'], correct: 3, phrase: 'reason for', vi: 'lý do cho/về — reason for (nguyên nhân dẫn đến việc gì)', explanation: 'Danh từ "reason" đi với "for": the reason for something = lý do cho việc gì. (of/to/about không kết hợp với reason theo nghĩa này.)' },
  { id: 'pp-303', cat: 'noun', q: 'The engineers finally found a clever solution ___ the traffic problem.', options: ['by', 'of', 'to', 'with'], correct: 2, phrase: 'solution to', vi: 'giải pháp cho — solution to (cách giải quyết vấn đề gì)', explanation: 'Danh từ "solution" đi với "to": a solution to a problem = giải pháp cho một vấn đề. (of/for/with không dùng với solution.)' },
  { id: 'pp-304', cat: 'noun', q: 'She could not give a clear answer ___ the teacher\'s difficult question.', options: ['on', 'to', 'of', 'for'], correct: 1, phrase: 'answer to', vi: 'câu trả lời cho — answer to (lời giải đáp cho câu hỏi/vấn đề)', explanation: 'Danh từ "answer" đi với "to": the answer to a question = câu trả lời cho câu hỏi. (for/of/on không kết hợp với answer.)' },
  { id: 'pp-305', cat: 'noun', q: 'Hard work and patience are the key ___ lasting success in life.', options: ['for', 'of', 'in', 'to'], correct: 3, phrase: 'key to', vi: 'chìa khóa của/cho — key to (yếu tố then chốt dẫn đến điều gì)', explanation: 'Danh từ "key" theo nghĩa bóng đi với "to": the key to success = chìa khóa của thành công. (of/for/in không dùng với key theo nghĩa này.)' },
  { id: 'pp-306', cat: 'noun', q: 'There has been a sharp increase ___ house prices over the past year.', options: ['of', 'in', 'on', 'to'], correct: 1, phrase: 'increase in', vi: 'sự tăng về — increase in (sự gia tăng về số lượng/mức độ)', explanation: 'Danh từ "increase" đi với "in" khi nói về lĩnh vực tăng: an increase in prices = sự tăng giá. (of/on/to không phù hợp ở đây.)' },
  { id: 'pp-307', cat: 'noun', q: 'The company reported a steady decrease ___ sales after the holidays.', options: ['of', 'on', 'at', 'in'], correct: 3, phrase: 'decrease in', vi: 'sự giảm về — decrease in (sự sụt giảm về số lượng/mức độ)', explanation: 'Danh từ "decrease" đi với "in": a decrease in sales = sự giảm doanh số. (of/on/at không kết hợp với decrease theo nghĩa này.)' },
  { id: 'pp-308', cat: 'noun', q: 'Scientists are worried about the rapid rise ___ global temperatures.', options: ['to', 'of', 'in', 'on'], correct: 2, phrase: 'rise in', vi: 'sự tăng về — rise in (sự dâng lên, tăng lên về mức độ)', explanation: 'Danh từ "rise" đi với "in": a rise in temperature = sự tăng nhiệt độ. (of/to/on không dùng với rise ở đây.)' },
  { id: 'pp-309', cat: 'noun', q: 'Economists noticed a sudden fall ___ the value of the currency.', options: ['in', 'off', 'down', 'of'], correct: 0, phrase: 'fall in', vi: 'sự giảm về — fall in (sự sụt giảm về mức độ/giá trị)', explanation: 'Danh từ "fall" đi với "in": a fall in value = sự giảm giá trị. (of/off/down không kết hợp với fall theo nghĩa này.)' },
  { id: 'pp-310', cat: 'noun', q: 'From a young age she showed a deep interest ___ ancient history.', options: ['on', 'of', 'for', 'in'], correct: 3, phrase: 'interest in', vi: 'sự quan tâm/hứng thú với — interest in (sự thích thú đối với điều gì)', explanation: 'Danh từ "interest" đi với "in": an interest in something = sự quan tâm tới việc gì. (for/of/on không dùng với interest theo nghĩa này.)' },
  { id: 'pp-311', cat: 'noun', q: 'One big advantage ___ living in the city is the convenient public transport.', options: ['of', 'in', 'for', 'to'], correct: 0, phrase: 'advantage of', vi: 'lợi thế/ưu điểm của — advantage of (điểm có lợi của việc gì)', explanation: 'Danh từ "advantage" đi với "of": the advantage of something = ưu điểm của việc gì. (to/for/in không kết hợp với advantage ở đây.)' },
  { id: 'pp-312', cat: 'noun', q: 'The main disadvantage ___ this plan is its very high cost.', options: ['in', 'to', 'of', 'for'], correct: 2, phrase: 'disadvantage of', vi: 'bất lợi của — disadvantage of (điểm yếu, mặt hạn chế của)', explanation: 'Danh từ "disadvantage" đi với "of": the disadvantage of something = bất lợi của việc gì. (to/for/in không kết hợp với disadvantage theo nghĩa này.)' },
  { id: 'pp-313', cat: 'noun', q: 'Doctors are still searching for the real cause ___ the disease.', options: ['to', 'in', 'of', 'for'], correct: 2, phrase: 'cause of', vi: 'nguyên nhân của — cause of (lý do gây ra điều gì)', explanation: 'Danh từ "cause" đi với "of": the cause of something = nguyên nhân của việc gì. (for/to/in không dùng với cause ở đây.)' },
  { id: 'pp-314', cat: 'noun', q: 'Too much sugar has a bad effect ___ your health over time.', options: ['of', 'to', 'in', 'on'], correct: 3, phrase: 'effect on', vi: 'ảnh hưởng đến — effect on (tác động lên cái gì)', explanation: 'Danh từ "effect" đi với "on": an effect on something = tác động lên cái gì. (to/in/of không kết hợp với effect theo nghĩa tác động.)' },
  { id: 'pp-315', cat: 'noun', q: 'Her teacher had a strong influence ___ her career choice.', options: ['with', 'for', 'to', 'on'], correct: 3, phrase: 'influence on', vi: 'ảnh hưởng đến — influence on (sự tác động lên ai/cái gì)', explanation: 'Danh từ "influence" đi với "on": an influence on someone = ảnh hưởng đến ai. (to/for/with không dùng với influence ở đây.)' },
  { id: 'pp-316', cat: 'noun', q: 'The new law had a huge impact ___ small local businesses.', options: ['on', 'at', 'in', 'to'], correct: 0, phrase: 'impact on', vi: 'tác động đến — impact on (ảnh hưởng mạnh lên cái gì)', explanation: 'Danh từ "impact" đi với "on": an impact on something = tác động đến cái gì. (in/to/at không kết hợp với impact.)' },
  { id: 'pp-317', cat: 'noun', q: 'There is a growing demand ___ electric cars in many countries.', options: ['for', 'to', 'of', 'on'], correct: 0, phrase: 'demand for', vi: 'nhu cầu về — demand for (sự cần đến, đòi hỏi cái gì)', explanation: 'Danh từ "demand" đi với "for": demand for something = nhu cầu về cái gì. (of/to/on không dùng với demand theo nghĩa này.)' },
  { id: 'pp-318', cat: 'noun', q: 'Everyone understands the need ___ clean water in rural areas.', options: ['with', 'for', 'to', 'of'], correct: 1, phrase: 'need for', vi: 'nhu cầu về — need for (sự cần thiết có cái gì)', explanation: 'Danh từ "need" đi với "for": the need for something = nhu cầu về cái gì. (of/to/with không kết hợp với need ở đây.)' },
  { id: 'pp-319', cat: 'noun', q: 'Scientists are working hard to find a cure ___ cancer.', options: ['to', 'against', 'for', 'of'], correct: 2, phrase: 'cure for', vi: 'phương thuốc chữa — cure for (cách chữa khỏi bệnh gì)', explanation: 'Danh từ "cure" đi với "for": a cure for something = phương thuốc chữa bệnh gì. (to/of/against không dùng với cure.)' },
  { id: 'pp-320', cat: 'noun', q: 'My grandmother gave me her secret recipe ___ apple pie.', options: ['with', 'for', 'to', 'of'], correct: 1, phrase: 'recipe for', vi: 'công thức làm — recipe for (cách chế biến món gì)', explanation: 'Danh từ "recipe" đi với "for": a recipe for something = công thức làm món gì. (of/to/with không kết hợp với recipe.)' },
  { id: 'pp-321', cat: 'noun', q: 'The manager received a formal request ___ more office staff.', options: ['on', 'to', 'of', 'for'], correct: 3, phrase: 'request for', vi: 'yêu cầu về — request for (lời đề nghị xin cái gì)', explanation: 'Danh từ "request" đi với "for": a request for something = yêu cầu về cái gì. (of/to/on không dùng với request theo nghĩa này.)' },
  { id: 'pp-322', cat: 'noun', q: 'The students showed great respect ___ their elderly history teacher.', options: ['for', 'with', 'of', 'to'], correct: 0, phrase: 'respect for', vi: 'sự tôn trọng đối với — respect for (lòng kính trọng dành cho)', explanation: 'Danh từ "respect" đi với "for": respect for somebody = sự tôn trọng đối với ai. (to/of/with không kết hợp với danh từ respect theo nghĩa này.)' },
  { id: 'pp-323', cat: 'noun', q: 'She has a remarkable talent ___ painting beautiful landscapes.', options: ['of', 'in', 'at', 'for'], correct: 3, phrase: 'talent for', vi: 'năng khiếu về — talent for (tài năng trong việc gì)', explanation: 'Danh từ "talent" luôn đi với "for": talent for something = năng khiếu về việc gì. (in/at/of không dùng sau danh từ talent.)' },
  { id: 'pp-324', cat: 'noun', q: 'This restaurant has a reputation ___ serving excellent fresh seafood.', options: ['of', 'for', 'on', 'with'], correct: 1, phrase: 'reputation for', vi: 'tiếng tăm về — reputation for (danh tiếng nổi tiếng về điều gì)', explanation: 'Danh từ "reputation" đi với "for": reputation for something = tiếng tăm về việc gì. (of/with/on không kết hợp với reputation ở đây.)' },
  { id: 'pp-325', cat: 'noun', q: 'The manager took full responsibility ___ the team\'s costly mistake.', options: ['over', 'for', 'to', 'of'], correct: 1, phrase: 'responsibility for', vi: 'trách nhiệm về — responsibility for (chịu trách nhiệm cho điều gì)', explanation: 'Danh từ "responsibility" đi với "for": responsibility for something = trách nhiệm về việc gì. (to/of/over không dùng sau responsibility theo nghĩa này.)' },
  { id: 'pp-326', cat: 'noun', q: 'His failure was caused by a complete lack ___ preparation.', options: ['in', 'for', 'of', 'with'], correct: 2, phrase: 'lack of', vi: 'sự thiếu — lack of (sự thiếu hụt cái gì)', explanation: 'Danh từ "lack" luôn đi với "of": lack of something = sự thiếu cái gì. (in/for/with không kết hợp với danh từ lack.)' },
  { id: 'pp-327', cat: 'noun', q: 'This building is a perfect example ___ modern Japanese architecture.', options: ['to', 'about', 'of', 'for'], correct: 2, phrase: 'example of', vi: 'ví dụ về — example of (một thí dụ điển hình của cái gì)', explanation: 'Danh từ "example" đi với "of": example of something = ví dụ về cái gì. (for/to/about không dùng sau danh từ example.)' },
  { id: 'pp-328', cat: 'noun', q: 'Many people have a deep fear ___ speaking in front of crowds.', options: ['of', 'for', 'from', 'about'], correct: 0, phrase: 'fear of', vi: 'nỗi sợ — fear of (sự sợ hãi điều gì)', explanation: 'Danh từ "fear" đi với "of": fear of something = nỗi sợ điều gì. (for/about/from không kết hợp với fear theo nghĩa này.)' },
  { id: 'pp-329', cat: 'noun', q: 'They left early in the hope ___ avoiding the heavy traffic.', options: ['of', 'to', 'for', 'in'], correct: 0, phrase: 'hope of', vi: 'hy vọng về — hope of (niềm hy vọng làm/đạt được điều gì)', explanation: 'Danh từ "hope" trong cụm này đi với "of": hope of doing something = hy vọng làm việc gì. (for/to/in không dùng trong cấu trúc "in the hope of".)' },
  { id: 'pp-330', cat: 'noun', q: 'Reading every day is a great way ___ improving your vocabulary.', options: ['of', 'for', 'to', 'in'], correct: 0, phrase: 'way of', vi: 'cách để — way of (phương cách làm việc gì)', explanation: 'Danh từ "way" đi với "of" + V-ing: way of doing something = cách làm việc gì. (to/for/in không đi với way of trước danh động từ.)' },
  { id: 'pp-331', cat: 'noun', q: 'In that village, bicycles are the main means ___ transport.', options: ['with', 'for', 'of', 'to'], correct: 2, phrase: 'means of', vi: 'phương tiện để — means of (cách thức/phương tiện làm điều gì)', explanation: 'Danh từ "means" đi với "of": means of something = phương tiện/cách thức làm việc gì. (for/to/with không kết hợp với danh từ means.)' },
  { id: 'pp-332', cat: 'noun', q: 'This is the most effective method ___ teaching young children new words.', options: ['to', 'in', 'for', 'of'], correct: 3, phrase: 'method of', vi: 'phương pháp (để làm gì) — method of (cách thức thực hiện)', explanation: 'Danh từ "method" đi với "of" + V-ing: method of doing = phương pháp làm việc gì. (to/for/in không kết hợp với method ở đây.)' },
  { id: 'pp-333', cat: 'noun', q: 'Her deep knowledge ___ history impressed everyone on the panel.', options: ['of', 'in', 'on', 'about'], correct: 0, phrase: 'knowledge of', vi: 'sự hiểu biết về — knowledge of (kiến thức, am hiểu)', explanation: 'Danh từ "knowledge" thường đi với "of": knowledge of something = sự hiểu biết về điều gì. (about/on/in không phải cách kết hợp chuẩn với knowledge.)' },
  { id: 'pp-334', cat: 'noun', q: 'He has a wonderful sense ___ humor that makes everyone laugh.', options: ['for', 'at', 'to', 'of'], correct: 3, phrase: 'sense of', vi: 'khả năng/cảm nhận về — sense of (sense of humor = khiếu hài hước)', explanation: 'Danh từ "sense" đi với "of": sense of humor = khiếu hài hước. (to/at/for không kết hợp với sense.)' },
  { id: 'pp-335', cat: 'noun', q: 'The sun is the main source ___ energy for plants on Earth.', options: ['from', 'of', 'for', 'to'], correct: 1, phrase: 'source of', vi: 'nguồn (của cái gì) — source of (nơi xuất phát)', explanation: 'Danh từ "source" đi với "of": source of energy = nguồn năng lượng. (from/for/to không kết hợp với source.)' },
  { id: 'pp-336', cat: 'noun', q: 'The accident was the direct result ___ his careless driving.', options: ['by', 'of', 'from', 'for'], correct: 1, phrase: 'result of', vi: 'kết quả/hậu quả của — result of (do điều gì gây ra)', explanation: 'Danh từ "result" đi với "of": result of something = kết quả của điều gì. (from/by/for không kết hợp với danh từ result.)' },
  { id: 'pp-337', cat: 'noun', q: 'Smoking greatly increases the risk ___ developing serious lung disease.', options: ['of', 'to', 'on', 'for'], correct: 0, phrase: 'risk of', vi: 'nguy cơ (mắc/gặp điều gì) — risk of (khả năng xấu xảy ra)', explanation: 'Danh từ "risk" đi với "of" + V-ing: risk of doing = nguy cơ làm/gặp điều gì. (for/to/on không kết hợp với risk.)' },
  { id: 'pp-338', cat: 'noun', q: 'There is a real danger ___ flooding when the heavy rain continues.', options: ['in', 'for', 'to', 'of'], correct: 3, phrase: 'danger of', vi: 'mối nguy hiểm về — danger of (rủi ro có thể xảy ra)', explanation: 'Danh từ "danger" đi với "of": danger of something = mối nguy về điều gì. (to/for/in không kết hợp với danger ở đây.)' },
  { id: 'pp-339', cat: 'noun', q: 'We cannot ignore the possibility ___ losing the contract next month.', options: ['about', 'of', 'to', 'for'], correct: 1, phrase: 'possibility of', vi: 'khả năng (điều gì xảy ra) — possibility of (xác suất, viễn cảnh)', explanation: 'Danh từ "possibility" đi với "of" + V-ing: possibility of doing = khả năng làm/xảy ra điều gì. (for/to/about không kết hợp với possibility.)' },
  { id: 'pp-340', cat: 'noun', q: 'There is little chance ___ winning the lottery with one ticket.', options: ['to', 'for', 'at', 'of'], correct: 3, phrase: 'chance of', vi: 'cơ hội/khả năng — chance of (xác suất điều gì xảy ra)', explanation: 'Danh từ "chance" đi với "of" + V-ing: chance of doing = khả năng/cơ hội làm điều gì. (to/for/at không kết hợp với chance ở nghĩa này.)' },
  { id: 'pp-341', cat: 'noun', q: 'Finishing this project is simply a matter ___ time and patience.', options: ['with', 'for', 'in', 'of'], correct: 3, phrase: 'matter of', vi: 'vấn đề/chuyện (về) — matter of (a matter of time = chỉ là vấn đề thời gian)', explanation: 'Danh từ "matter" đi với "of": a matter of time = chỉ là vấn đề thời gian. (for/in/with không kết hợp với matter ở đây.)' },
  { id: 'pp-342', cat: 'noun', q: 'I really don\'t see the point ___ arguing about it anymore.', options: ['to', 'of', 'for', 'in'], correct: 1, phrase: 'point of', vi: 'mục đích của — point of (ý nghĩa, lý do của việc gì)', explanation: 'Danh từ "point" đi với "of": the point of something = mục đích/ý nghĩa của việc gì. (to/in/for không tạo cụm này với "the point of".)' },
  { id: 'pp-343', cat: 'noun', q: 'What kind ___ music do you usually listen to in the car?', options: ['at', 'of', 'for', 'to'], correct: 1, phrase: 'kind of', vi: 'loại — kind of (kiểu, dạng của cái gì)', explanation: '"Kind" luôn đi với "of": kind of something = loại/kiểu gì. (to/at/for không kết hợp với kind.)' },
  { id: 'pp-344', cat: 'noun', q: 'It was a strange sort ___ feeling that I could not explain.', options: ['of', 'in', 'for', 'to'], correct: 0, phrase: 'sort of', vi: 'loại/kiểu — sort of (một loại nào đó)', explanation: 'Danh từ "sort" đi với "of": a sort of + N = một loại/kiểu gì đó. (in/for/to không dùng sau "sort" trong cụm này.)' },
  { id: 'pp-345', cat: 'noun', q: 'This type ___ phone is very popular among young students.', options: ['for', 'of', 'with', 'to'], correct: 1, phrase: 'type of', vi: 'loại — type of (kiểu, dạng của cái gì)', explanation: 'Danh từ "type" đi với "of": type of something = loại/kiểu gì. (for/to/with không dùng với type ở đây.)' },
  { id: 'pp-346', cat: 'noun', q: 'Can you give me a piece ___ advice about my job?', options: ['of', 'on', 'for', 'to'], correct: 0, phrase: 'piece of', vi: 'một mẩu/miếng — piece of (một phần của cái gì)', explanation: '"Piece" luôn đi với "of": a piece of something = một mẩu/miếng/phần gì. (on/for/to không kết hợp với piece.)' },
  { id: 'pp-347', cat: 'noun', q: 'Don\'t worry, we still have plenty ___ time before the train leaves.', options: ['of', 'for', 'in', 'with'], correct: 0, phrase: 'plenty of', vi: 'rất nhiều — plenty of (đủ và dư, nhiều)', explanation: '"Plenty" luôn đi với "of": plenty of something = rất nhiều/dư dả cái gì. (with/in/for không dùng với plenty.)' },
  { id: 'pp-348', cat: 'noun', q: 'Her positive attitude ___ work impressed all of her colleagues.', options: ['of', 'at', 'from', 'to'], correct: 3, phrase: 'attitude to', vi: 'thái độ đối với — attitude to (cách nhìn nhận về việc gì)', explanation: 'Danh từ "attitude" đi với "to" (hoặc towards): attitude to something = thái độ đối với cái gì. (of/at/from không tạo cụm này.)' },
  { id: 'pp-349', cat: 'noun', q: 'His relaxed attitude ___ deadlines sometimes annoys his manager.', options: ['on', 'towards', 'for', 'of'], correct: 1, phrase: 'attitude towards', vi: 'thái độ đối với — attitude towards (cách nhìn nhận về việc gì)', explanation: '"Attitude" đi với "towards" (hoặc to): attitude towards something = thái độ đối với cái gì. (for/on/of không dùng với attitude.)' },
  { id: 'pp-350', cat: 'noun', q: 'Students now have easy access ___ the online library from home.', options: ['with', 'to', 'for', 'of'], correct: 1, phrase: 'access to', vi: 'sự tiếp cận với — access to (quyền dùng, vào được cái gì)', explanation: 'Danh từ "access" đi với "to": access to something = sự tiếp cận/quyền dùng cái gì. (of/for/with không kết hợp với access.)' },
  { id: 'pp-351', cat: 'noun', q: 'Cycling is a healthy alternative ___ driving to the office.', options: ['to', 'of', 'from', 'for'], correct: 0, phrase: 'alternative to', vi: 'giải pháp thay thế cho — alternative to (lựa chọn khác thay cho cái gì)', explanation: 'Danh từ "alternative" đi với "to": an alternative to something = giải pháp thay thế cho cái gì. (for/of/from không dùng với alternative.)' },
  { id: 'pp-352', cat: 'noun', q: 'Her fresh approach ___ teaching made the lessons much more enjoyable.', options: ['with', 'to', 'of', 'for'], correct: 1, phrase: 'approach to', vi: 'cách tiếp cận đối với — approach to (phương pháp, cách xử lý vấn đề gì)', explanation: 'Danh từ "approach" đi với "to": approach to something = cách tiếp cận việc gì. (of/for/with không dùng với approach theo nghĩa này.)' },
  { id: 'pp-353', cat: 'noun', q: 'His angry reaction ___ the bad news surprised everyone in the room.', options: ['at', 'with', 'to', 'for'], correct: 2, phrase: 'reaction to', vi: 'phản ứng đối với — reaction to (sự đáp lại trước điều gì)', explanation: 'Danh từ "reaction" luôn đi với "to": reaction to something = phản ứng trước điều gì. (with/at/for không kết hợp với reaction.)' },
  { id: 'pp-354', cat: 'noun', q: 'The company\'s quick response ___ the complaint pleased all the customers.', options: ['on', 'for', 'of', 'to'], correct: 3, phrase: 'response to', vi: 'sự đáp lại đối với — response to (phản hồi trước điều gì)', explanation: 'Danh từ "response" đi với "to": response to something = sự đáp lại điều gì. (of/on/for không dùng với response.)' },
  { id: 'pp-355', cat: 'noun', q: 'Her huge contribution ___ the project earned her a special award.', options: ['of', 'to', 'in', 'for'], correct: 1, phrase: 'contribution to', vi: 'sự đóng góp cho — contribution to (phần góp vào việc gì)', explanation: 'Danh từ "contribution" đi với "to": contribution to something = sự đóng góp cho việc gì. (for/of/in không kết hợp với contribution.)' },
  { id: 'pp-356', cat: 'noun', q: 'Pollution is a serious threat ___ the health of our planet.', options: ['of', 'to', 'for', 'on'], correct: 1, phrase: 'threat to', vi: 'mối đe dọa đối với — threat to (nguy cơ gây hại cho cái gì)', explanation: 'Danh từ "threat" đi với "to": threat to something = mối đe dọa đối với cái gì. (for/of/on không dùng với threat theo nghĩa này.)' },
  { id: 'pp-357', cat: 'noun', q: 'The storm caused terrible damage ___ the roofs of many houses.', options: ['on', 'of', 'for', 'to'], correct: 3, phrase: 'damage to', vi: 'thiệt hại đối với — damage to (sự hư hại gây ra cho cái gì)', explanation: 'Danh từ "damage" đi với "to": damage to something = thiệt hại cho cái gì. (of/on/for không kết hợp với damage.)' },
  { id: 'pp-358', cat: 'noun', q: 'She received a lovely invitation ___ her best friend\'s wedding party.', options: ['at', 'of', 'to', 'for'], correct: 2, phrase: 'invitation to', vi: 'lời mời đến — invitation to (giấy mời tham dự sự kiện gì)', explanation: 'Danh từ "invitation" đi với "to": invitation to something = lời mời đến sự kiện gì. (for/of/at không dùng với invitation theo nghĩa này.)' },
  { id: 'pp-359', cat: 'noun', q: 'This strange case is the only exception ___ the general rule.', options: ['to', 'of', 'from', 'for'], correct: 0, phrase: 'exception to', vi: 'ngoại lệ đối với — exception to (trường hợp khác với quy tắc)', explanation: 'Danh từ "exception" đi với "to": exception to the rule = ngoại lệ của quy tắc. (of/from/for không kết hợp với exception.)' },
  { id: 'pp-360', cat: 'noun', q: 'He has a very close relationship ___ his younger brother and sister.', options: ['to', 'with', 'of', 'for'], correct: 1, phrase: 'relationship with', vi: 'mối quan hệ với — relationship with (sự gắn bó giữa người với người)', explanation: 'Danh từ "relationship" đi với "with" khi nói về người: relationship with someone = mối quan hệ với ai. (to/of/for không dùng trong trường hợp này.)' },
  { id: 'pp-361', cat: 'noun', q: 'The police found no connection ___ the two separate robberies in town.', options: ['of', 'to', 'with', 'for'], correct: 2, phrase: 'connection with', vi: 'mối liên hệ với — connection with (sự liên quan giữa các sự việc)', explanation: 'Danh từ "connection" thường đi với "with": connection with something = mối liên hệ với cái gì. (of/for không kết hợp; to ít tự nhiên ở đây.)' },
  { id: 'pp-362', cat: 'noun', q: 'The astronaut lost all contact ___ the control center for several hours.', options: ['to', 'with', 'on', 'for'], correct: 1, phrase: 'contact with', vi: 'liên lạc với — contact with (sự tiếp xúc, liên hệ với)', explanation: 'Danh từ "contact" đi với "with": contact with someone/something = liên lạc, tiếp xúc với. (to/on/for không kết hợp với contact theo nghĩa này.)' },
  { id: 'pp-363', cat: 'noun', q: 'Our company finally reached an agreement ___ the new supplier last week.', options: ['with', 'to', 'on', 'for'], correct: 0, phrase: 'agreement with', vi: 'thỏa thuận với — agreement with (sự đồng ý, hợp đồng với ai)', explanation: 'Danh từ "agreement" đi với "with" khi nói tới bên kia: agreement with someone = thỏa thuận với ai. (to/on/for không dùng để chỉ đối tác trong agreement.)' },
  { id: 'pp-364', cat: 'noun', q: 'Can you explain the difference ___ these two English tenses to me?', options: ['from', 'of', 'with', 'between'], correct: 3, phrase: 'difference between', vi: 'sự khác biệt giữa — difference between (điểm khác nhau giữa hai thứ)', explanation: 'Danh từ "difference" đi với "between" khi so sánh hai thứ: difference between A and B = sự khác biệt giữa A và B. (of/with/from không dùng để nối hai đối tượng so sánh.)' },
  { id: 'pp-365', cat: 'noun', q: 'Scientists found a clear link ___ smoking and several serious diseases.', options: ['with', 'of', 'to', 'between'], correct: 3, phrase: 'link between', vi: 'mối liên hệ giữa — link between (sự kết nối giữa hai thứ)', explanation: 'Danh từ "link" đi với "between" khi nối hai thứ: link between A and B = mối liên hệ giữa A và B. (of/to/with không dùng để nối hai đối tượng ở đây.)' },
  { id: 'pp-366', cat: 'noun', q: 'The teacher described the relationship ___ effort and exam results clearly.', options: ['of', 'to', 'for', 'between'], correct: 3, phrase: 'relationship between', vi: 'mối quan hệ giữa — relationship between (sự liên hệ giữa hai thứ)', explanation: 'Danh từ "relationship" đi với "between" khi nói hai thứ: relationship between A and B = mối quan hệ giữa A và B. (of/to/for không nối hai đối tượng trong relationship.)' },
  { id: 'pp-367', cat: 'noun', q: 'There is a huge gap ___ the rich and the poor in this city.', options: ['with', 'between', 'of', 'among'], correct: 1, phrase: 'gap between', vi: 'khoảng cách giữa — gap between (sự chênh lệch giữa hai nhóm)', explanation: 'Danh từ "gap" đi với "between" khi nói hai nhóm: gap between A and B = khoảng cách giữa A và B. (of/with/among không dùng cho gap giữa hai đối tượng.)' },
  { id: 'pp-368', cat: 'noun', q: 'The report makes an interesting comparison ___ life in cities and villages.', options: ['to', 'between', 'with', 'of'], correct: 1, phrase: 'comparison between', vi: 'sự so sánh giữa — comparison between (việc đối chiếu hai thứ)', explanation: 'Danh từ "comparison" đi với "between" khi so sánh hai thứ: comparison between A and B = sự so sánh giữa A và B. (to/of/with không nối hai đối tượng so sánh ở đây.)' },
  { id: 'pp-369', cat: 'noun', q: 'Photographers love the sharp contrast ___ light and shadow in old streets.', options: ['to', 'between', 'with', 'of'], correct: 1, phrase: 'contrast between', vi: 'sự tương phản giữa — contrast between (sự đối lập giữa hai thứ)', explanation: 'Danh từ "contrast" đi với "between" khi nói hai thứ: contrast between A and B = sự tương phản giữa A và B. (of/with/to không nối hai đối tượng tương phản.)' },
  { id: 'pp-370', cat: 'noun', q: 'My uncle is a well-known expert ___ ancient Vietnamese history.', options: ['for', 'of', 'to', 'on'], correct: 3, phrase: 'expert on', vi: 'chuyên gia về — expert on (người am hiểu sâu một chủ đề)', explanation: 'Danh từ "expert" thường đi với "on" khi nói chủ đề: expert on something = chuyên gia về vấn đề gì. (of/for không dùng; "in" hợp với lĩnh vực rộng hơn là chủ đề cụ thể này.)' },
  { id: 'pp-371', cat: 'noun', q: 'The government plans to introduce a new tax ___ sugary drinks next year.', options: ['to', 'on', 'of', 'for'], correct: 1, phrase: 'tax on', vi: 'thuế đánh vào — tax on (khoản thuế áp lên thứ gì)', explanation: 'Danh từ "tax" đi với "on" khi nói đối tượng bị đánh thuế: tax on something = thuế đánh vào thứ gì. (for/of/to không dùng để chỉ vật chịu thuế.)' },
  { id: 'pp-372', cat: 'noun', q: 'The government placed a strict ban ___ smoking in all restaurants.', options: ['at', 'in', 'to', 'on'], correct: 3, phrase: 'ban on', vi: 'lệnh cấm đối với — ban on (sự cấm đoán việc gì)', explanation: 'Danh từ "ban" luôn đi với "on": a ban on something = lệnh cấm về việc gì. (at/in/to không dùng với ban.)' },
  { id: 'pp-373', cat: 'noun', q: 'The newspaper published a fierce attack ___ the new education policy.', options: ['of', 'to', 'for', 'on'], correct: 3, phrase: 'attack on', vi: 'sự công kích vào — attack on (sự tấn công, chỉ trích)', explanation: 'Danh từ "attack" đi với "on": an attack on something = sự tấn công/công kích vào việc gì. (to/for/of không kết hợp với attack ở nghĩa này.)' },
  { id: 'pp-374', cat: 'noun', q: 'This school puts a strong emphasis ___ creativity and independent thinking.', options: ['with', 'for', 'on', 'in'], correct: 2, phrase: 'emphasis on', vi: 'sự nhấn mạnh vào — emphasis on (sự coi trọng, chú trọng)', explanation: 'Danh từ "emphasis" đi với "on": emphasis on something = sự nhấn mạnh vào việc gì. (in/for/with không dùng với emphasis.)' },
  { id: 'pp-375', cat: 'noun', q: 'Could you share your honest opinion ___ this controversial topic?', options: ['to', 'for', 'on', 'of'], correct: 2, phrase: 'opinion on', vi: 'ý kiến về — opinion on (quan điểm, nhận định)', explanation: 'Danh từ "opinion" đi với "on": an opinion on something = ý kiến về việc gì. (for/of/to không phù hợp ở nghĩa này.)' },
  { id: 'pp-376', cat: 'noun', q: 'There was a long debate ___ climate change at the conference.', options: ['with', 'at', 'on', 'by'], correct: 2, phrase: 'debate on', vi: 'cuộc tranh luận về — debate on (cuộc bàn cãi về vấn đề)', explanation: 'Danh từ "debate" đi với "on": a debate on something = cuộc tranh luận về việc gì. (at/with/by không dùng với debate.)' },
  { id: 'pp-377', cat: 'noun', q: 'The manager has complete control ___ the company\'s daily operations.', options: ['over', 'to', 'on', 'at'], correct: 0, phrase: 'control over', vi: 'sự kiểm soát đối với — control over (quyền chi phối, điều khiển)', explanation: 'Danh từ "control" đi với "over": control over something = sự kiểm soát đối với việc gì. (on/at/to không kết hợp với control ở nghĩa này.)' },
  { id: 'pp-378', cat: 'noun', q: 'The new director has full authority ___ all of his employees.', options: ['with', 'on', 'over', 'for'], correct: 2, phrase: 'authority over', vi: 'quyền hành đối với — authority over (quyền lực, thẩm quyền)', explanation: 'Danh từ "authority" đi với "over": authority over someone = quyền hành đối với ai. (on/for/with không dùng với authority ở nghĩa này.)' },
  { id: 'pp-379', cat: 'noun', q: 'The team celebrated a stunning victory ___ their biggest rivals.', options: ['over', 'of', 'on', 'against'], correct: 0, phrase: 'victory over', vi: 'chiến thắng trước — victory over (sự thắng lợi trước ai)', explanation: 'Danh từ "victory" đi với "over": a victory over someone = chiến thắng trước ai. (on/against/of không kết hợp với victory.)' },
  { id: 'pp-380', cat: 'noun', q: 'Parents expressed deep concern ___ the safety of the playground.', options: ['for', 'to', 'on', 'about'], correct: 3, phrase: 'concern about', vi: 'sự lo ngại về — concern about (mối quan tâm, lo lắng)', explanation: 'Danh từ "concern" đi với "about": concern about something = sự lo ngại về việc gì. (for/on/to không phù hợp ở nghĩa này.)' },
  { id: 'pp-381', cat: 'noun', q: 'Please give me more information ___ the upcoming training course.', options: ['about', 'to', 'of', 'for'], correct: 0, phrase: 'information about', vi: 'thông tin về — information about (dữ liệu, tin tức về)', explanation: 'Danh từ "information" đi với "about": information about something = thông tin về việc gì. (of/for/to không dùng với information ở nghĩa này.)' },
  { id: 'pp-382', cat: 'noun', q: 'My grandfather told us a wonderful story ___ his childhood village.', options: ['about', 'of', 'for', 'on'], correct: 0, phrase: 'story about', vi: 'câu chuyện về — story about (chuyện kể về điều gì)', explanation: 'Danh từ "story" đi với "about": a story about something = câu chuyện về điều gì. (of/on/for không dùng theo nghĩa này với story.)' },
  { id: 'pp-383', cat: 'noun', q: 'She has some interesting ideas ___ how to improve the project.', options: ['at', 'in', 'about', 'for'], correct: 2, phrase: 'idea about', vi: 'ý tưởng về — idea about (suy nghĩ, quan niệm về điều gì)', explanation: 'Danh từ "idea" đi với "about": an idea about something = ý tưởng về điều gì. (for/at/in không phù hợp ở nghĩa này.)' },
  { id: 'pp-384', cat: 'noun', q: 'I have serious doubts ___ his ability to finish the job on time.', options: ['to', 'about', 'of', 'on'], correct: 1, phrase: 'doubt about', vi: 'sự nghi ngờ về — doubt about (mối hoài nghi về điều gì)', explanation: 'Danh từ "doubt" đi với "about": a doubt about something = sự nghi ngờ về điều gì. (of/on/to không kết hợp với doubt ở đây.)' },
  { id: 'pp-385', cat: 'noun', q: 'The committee must make a decision ___ the new budget tomorrow.', options: ['by', 'to', 'for', 'about'], correct: 3, phrase: 'decision about', vi: 'quyết định về — decision about (sự lựa chọn, định đoạt về điều gì)', explanation: 'Danh từ "decision" đi với "about": a decision about something = quyết định về điều gì. (to/for/on không dùng theo nghĩa này với decision.)' },
  { id: 'pp-386', cat: 'noun', q: 'His addiction ___ video games started affecting his schoolwork.', options: ['to', 'of', 'for', 'with'], correct: 0, phrase: 'addiction to', vi: 'sự nghiện — addiction to (sự lệ thuộc, mê đắm vào điều gì)', explanation: 'Danh từ "addiction" đi với "to": an addiction to something = sự nghiện điều gì. (for/with/of không kết hợp với addiction.)' },
  { id: 'pp-387', cat: 'noun', q: 'Everyone admired her dedication ___ helping the poor children.', options: ['on', 'in', 'for', 'to'], correct: 3, phrase: 'dedication to', vi: 'sự tận tụy với — dedication to (sự cống hiến, hết lòng vì điều gì)', explanation: 'Danh từ "dedication" đi với "to": dedication to something = sự tận tụy với điều gì. (for/in/on không dùng với dedication.)' },
  { id: 'pp-388', cat: 'noun', q: 'The company showed a strong commitment ___ protecting the environment.', options: ['for', 'of', 'to', 'with'], correct: 2, phrase: 'commitment to', vi: 'sự cam kết với — commitment to (sự tận tâm, gắn bó với điều gì)', explanation: 'Danh từ "commitment" đi với "to": commitment to something = sự cam kết với điều gì. (for/with/of không kết hợp với commitment.)' },
  { id: 'pp-389', cat: 'noun', q: 'Her devotion ___ her family was clear to everyone who knew her.', options: ['to', 'with', 'for', 'of'], correct: 0, phrase: 'devotion to', vi: 'sự tận tâm với — devotion to (lòng tận tụy, yêu thương dành cho ai/điều gì)', explanation: 'Danh từ "devotion" đi với "to": devotion to someone/something = sự tận tâm với ai/điều gì. (for/of/with không dùng với devotion.)' },
  { id: 'pp-390', cat: 'noun', q: 'His firm belief ___ hard work helped him succeed in life.', options: ['in', 'on', 'to', 'of'], correct: 0, phrase: 'belief in', vi: 'niềm tin vào — belief in (sự tin tưởng vào điều gì)', explanation: 'Danh từ "belief" đi với "in": belief in something = niềm tin vào điều gì. (on/of/to không kết hợp với belief.)' },
  { id: 'pp-391', cat: 'noun', q: 'The coach never lost his faith ___ the young players on his team.', options: ['on', 'in', 'to', 'for'], correct: 1, phrase: 'faith in', vi: 'niềm tin vào — faith in (lòng tin tưởng đặt vào ai/điều gì)', explanation: 'Danh từ "faith" đi với "in": faith in someone/something = niềm tin vào ai/điều gì. (to/on/for không dùng với faith.)' },
  { id: 'pp-392', cat: 'noun', q: 'She is a respected expert ___ ancient Roman history at the university.', options: ['for', 'at', 'in', 'of'], correct: 2, phrase: 'expert in', vi: 'chuyên gia về — expert in (người am hiểu sâu một lĩnh vực)', explanation: 'Danh từ "expert" đi với "in" khi nói về một lĩnh vực: an expert in something = chuyên gia về lĩnh vực gì. (on/at/of không phải cấu trúc chuẩn với expert + lĩnh vực.)' },
  { id: 'pp-393', cat: 'noun', q: 'He earned a degree ___ mechanical engineering from a top college.', options: ['of', 'in', 'at', 'on'], correct: 1, phrase: 'degree in', vi: 'bằng cấp về — degree in (bằng đại học chuyên ngành nào đó)', explanation: 'Danh từ "degree" đi với "in" để chỉ chuyên ngành: a degree in something = bằng cấp ngành gì. (of/on/at không dùng với degree theo nghĩa này.)' },
  { id: 'pp-394', cat: 'noun', q: 'The students made great progress ___ English after the summer course.', options: ['on', 'with', 'at', 'in'], correct: 3, phrase: 'progress in', vi: 'tiến bộ trong — progress in (sự cải thiện ở lĩnh vực nào đó)', explanation: 'Danh từ "progress" đi với "in" khi chỉ lĩnh vực tiến bộ: progress in something = tiến bộ trong việc gì. (on/at/with không kết hợp tự nhiên với progress + lĩnh vực.)' },
  { id: 'pp-395', cat: 'noun', q: 'The scandal destroyed public trust ___ the government completely.', options: ['to', 'on', 'at', 'in'], correct: 3, phrase: 'trust in', vi: 'sự tin tưởng vào — trust in (niềm tin đặt vào ai/cái gì)', explanation: 'Danh từ "trust" đi với "in": trust in someone/something = niềm tin vào ai/cái gì. (on/at/to không dùng với trust theo nghĩa này.)' },
  { id: 'pp-396', cat: 'noun', q: 'She takes great pride ___ her neatly organized garden.', options: ['on', 'in', 'at', 'of'], correct: 1, phrase: 'pride in', vi: 'niềm tự hào về — pride in (sự hãnh diện về điều gì)', explanation: 'Danh từ "pride" đi với "in": take pride in something = tự hào về điều gì. (of/on/at không kết hợp với pride trong cấu trúc này.)' },
  { id: 'pp-397', cat: 'noun', q: 'There has been a sharp decline ___ sales over the past year.', options: ['at', 'of', 'on', 'in'], correct: 3, phrase: 'decline in', vi: 'sự suy giảm về — decline in (sự sụt giảm của cái gì)', explanation: 'Danh từ "decline" đi với "in": a decline in something = sự suy giảm của cái gì. (of/at/on không dùng để chỉ lĩnh vực sụt giảm.)' },
  { id: 'pp-398', cat: 'noun', q: 'My doctor is a specialist ___ heart diseases at the city hospital.', options: ['on', 'at', 'in', 'of'], correct: 2, phrase: 'specialist in', vi: 'chuyên gia về — specialist in (bác sĩ/người chuyên một lĩnh vực)', explanation: 'Danh từ "specialist" đi với "in": a specialist in something = chuyên gia về lĩnh vực gì. (on/of/at không phải cấu trúc chuẩn với specialist.)' },
  { id: 'pp-399', cat: 'noun', q: 'I am taking a course ___ digital photography this semester.', options: ['of', 'in', 'for', 'at'], correct: 1, phrase: 'course in', vi: 'khóa học về — course in (lớp học một môn/chủ đề)', explanation: 'Danh từ "course" thường đi với "in" để chỉ môn học: a course in something = khóa học về môn gì. (of/at không dùng; on cũng gặp nhưng "in" là lựa chọn chuẩn ở đây.)' },
  { id: 'pp-400', cat: 'noun', q: 'You need a qualification ___ nursing to apply for this job.', options: ['at', 'of', 'on', 'in'], correct: 3, phrase: 'qualification in', vi: 'bằng cấp/chứng chỉ về — qualification in (chứng nhận chuyên môn)', explanation: 'Danh từ "qualification" đi với "in": a qualification in something = chứng chỉ/bằng cấp về lĩnh vực gì. (of/on/at không kết hợp với qualification + lĩnh vực.)' },
  { id: 'pp-401', cat: 'noun', q: 'Recent advances ___ medicine have saved millions of lives.', options: ['in', 'of', 'on', 'at'], correct: 0, phrase: 'advance in', vi: 'tiến bộ/bước tiến trong — advance in (sự phát triển của một lĩnh vực)', explanation: 'Danh từ "advance" đi với "in": an advance in something = bước tiến trong lĩnh vực gì. (of/on/at không dùng để chỉ lĩnh vực có tiến bộ.)' },
  { id: 'pp-402', cat: 'phrase', q: 'In addition ___ his salary, he earns a yearly bonus from the company.', options: ['for', 'with', 'of', 'to'], correct: 3, phrase: 'in addition to', vi: 'thêm vào, ngoài ra — in addition to (bên cạnh, cộng thêm)', explanation: 'Cụm "in addition to" luôn kết thúc bằng "to": in addition to something = thêm vào/ngoài việc gì. (of/for/with không dùng trong cụm này.)' },
  { id: 'pp-403', cat: 'phrase', q: 'The flight was delayed ___ of the heavy storm last night.', options: ['instead', 'aside', 'because', 'ahead'], correct: 2, phrase: 'because of', vi: 'bởi vì, do — because of (vì lý do gì đó)', explanation: 'Cụm chỉ nguyên nhân là "because of": because of something = bởi vì điều gì. (instead/ahead/aside tạo cụm khác, không hợp nghĩa nguyên nhân ở đây.)' },
  { id: 'pp-404', cat: 'phrase', q: 'He walked to the office instead ___ taking the crowded bus.', options: ['to', 'for', 'from', 'of'], correct: 3, phrase: 'instead of', vi: 'thay vì, thay cho — instead of (thay thế cho việc gì)', explanation: 'Cụm "instead of" luôn đi với "of": instead of something = thay vì việc gì. (to/for/from không kết hợp với instead.)' },
  { id: 'pp-405', cat: 'phrase', q: 'According ___ the weather forecast, it will rain heavily tomorrow.', options: ['by', 'of', 'to', 'with'], correct: 2, phrase: 'according to', vi: 'theo như, dựa theo — according to (căn cứ vào nguồn nào)', explanation: 'Cụm "according to" luôn dùng "to": according to someone/something = theo như ai/cái gì. (with/of/by không đi với according.)' },
  { id: 'pp-406', cat: 'phrase', q: 'She went for a run in spite ___ the freezing cold weather.', options: ['of', 'at', 'with', 'for'], correct: 0, phrase: 'in spite of', vi: 'mặc dù, bất chấp — in spite of (dù có điều gì cản trở)', explanation: 'Cụm "in spite of" luôn kết thúc bằng "of": in spite of something = mặc dù điều gì. (for/with/at không dùng trong cụm này.)' },
  { id: 'pp-407', cat: 'phrase', q: 'A tall man was standing in front ___ me at the concert.', options: ['of', 'on', 'at', 'to'], correct: 0, phrase: 'in front of', vi: 'phía trước, đằng trước — in front of (ở vị trí trước mặt)', explanation: 'Cụm "in front of" luôn dùng "of": in front of something = ở phía trước cái gì. (to/at/on không kết hợp trong cụm chỉ vị trí này.)' },
  { id: 'pp-408', cat: 'phrase', q: 'She accepted the award on behalf ___ the entire research team.', options: ['with', 'of', 'for', 'to'], correct: 1, phrase: 'on behalf of', vi: 'thay mặt cho, đại diện cho — on behalf of (nhân danh ai đó)', explanation: 'Cụm "on behalf of" luôn đi với "of": on behalf of someone = thay mặt cho ai. (for/to/with không dùng trong cụm này.)' },
  { id: 'pp-409', cat: 'phrase', q: 'They crossed the wide river by means ___ a small wooden boat.', options: ['by', 'with', 'of', 'in'], correct: 2, phrase: 'by means of', vi: 'bằng cách, nhờ vào — by means of (sử dụng phương tiện gì)', explanation: 'Cụm "by means of" luôn kết thúc bằng "of": by means of something = bằng phương tiện gì. (with/by/in không hợp trong cụm cố định này.)' },
  { id: 'pp-410', cat: 'phrase', q: 'In case ___ fire, please use the stairs and not the elevator.', options: ['of', 'at', 'with', 'for'], correct: 0, phrase: 'in case of', vi: 'trong trường hợp, phòng khi — in case of (nếu xảy ra điều gì)', explanation: 'Cụm "in case of" luôn dùng "of": in case of something = trong trường hợp có điều gì. (for/with/at không kết hợp với cụm này.)' },
  { id: 'pp-411', cat: 'phrase', q: 'My manager is in charge ___ the marketing department this year.', options: ['to', 'of', 'for', 'with'], correct: 1, phrase: 'in charge of', vi: 'phụ trách, chịu trách nhiệm về — in charge of (quản lý việc gì)', explanation: 'Cụm "in charge of" luôn đi với "of": in charge of something = phụ trách việc gì. (for/to/with không dùng trong cụm cố định này.)' },
  { id: 'pp-412', cat: 'phrase', q: 'Most of the members voted in favor ___ the new proposal.', options: ['of', 'for', 'on', 'to'], correct: 0, phrase: 'in favor of', vi: 'ủng hộ, tán thành — in favor of (đứng về phía điều gì)', explanation: 'Cụm "in favor of" luôn kết thúc bằng "of": in favor of something = ủng hộ điều gì. (to/for/on không kết hợp trong cụm này.)' },
  { id: 'pp-413', cat: 'phrase', q: 'This plan is better ___ terms of cost and long-term benefits.', options: ['by', 'in', 'on', 'at'], correct: 1, phrase: 'in terms of', vi: 'về mặt — in terms of (xét theo, liên quan đến)', explanation: 'Cụm "in terms of" luôn bắt đầu bằng "in": in terms of = về mặt, xét theo phương diện gì. (on/by/at không tạo thành cụm này.)' },
  { id: 'pp-414', cat: 'phrase', q: 'She put the heavy box ___ top of the wooden table.', options: ['at', 'on', 'over', 'in'], correct: 1, phrase: 'on top of', vi: 'ở trên, ngoài ra — on top of (bên trên; thêm vào đó)', explanation: 'Cụm "on top of" bắt đầu bằng "on": on top of = ở phía trên cái gì. (at/in/over không kết hợp với "top of" theo nghĩa này.)' },
  { id: 'pp-415', cat: 'phrase', q: 'We will receive our salary ___ the end of each month.', options: ['on', 'by', 'at', 'in'], correct: 2, phrase: 'at the end of', vi: 'vào cuối — at the end of (ở thời điểm kết thúc của)', explanation: 'Chỉ một thời điểm kết thúc dùng "at the end of": at the end of the month = vào cuối tháng. (in/on/by không dùng với "the end of" theo nghĩa thời điểm.)' },
  { id: 'pp-416', cat: 'phrase', q: 'You must finish the whole report ___ the end of this week.', options: ['at', 'on', 'in', 'by'], correct: 3, phrase: 'by the end of', vi: 'trước khi kết thúc, chậm nhất là — by the end of (không muộn hơn lúc kết thúc)', explanation: 'Cụm "by the end of" dùng "by" để chỉ thời hạn: by the end of the week = chậm nhất là cuối tuần. (at/in/on không diễn tả hạn chót như "by".)' },
  { id: 'pp-417', cat: 'phrase', q: 'My phone rang loudly ___ the middle of the important meeting.', options: ['by', 'on', 'in', 'at'], correct: 2, phrase: 'in the middle of', vi: 'ở giữa, đang lúc — in the middle of (giữa không gian hoặc thời gian)', explanation: 'Cụm "in the middle of" bắt đầu bằng "in": in the middle of = ở giữa, đang giữa lúc. (at/on/by không kết hợp với "the middle of".)' },
  { id: 'pp-418', cat: 'phrase', q: 'They stayed together ___ the sake of their two young children.', options: ['to', 'for', 'with', 'of'], correct: 1, phrase: 'for the sake of', vi: 'vì lợi ích của, vì — for the sake of (vì mục đích, vì điều tốt cho ai/gì)', explanation: 'Cụm "for the sake of" bắt đầu bằng "for": for the sake of = vì lợi ích của. (of/to/with không mở đầu cụm này.)' },
  { id: 'pp-419', cat: 'phrase', q: 'The city held a grand parade ___ honor of the war heroes.', options: ['in', 'of', 'on', 'for'], correct: 0, phrase: 'in honor of', vi: 'để tôn vinh, vinh danh — in honor of (nhằm bày tỏ sự kính trọng)', explanation: 'Cụm "in honor of" bắt đầu bằng "in": in honor of = để vinh danh ai. (on/for/of không tạo thành cụm cố định này.)' },
  { id: 'pp-420', cat: 'phrase', q: 'The explorers traveled deep into the jungle ___ search of treasure.', options: ['on', 'of', 'for', 'in'], correct: 3, phrase: 'in search of', vi: 'để tìm kiếm — in search of (đi tìm cái gì)', explanation: 'Cụm "in search of" bắt đầu bằng "in": in search of = để tìm kiếm. (on/for/of không kết hợp với "search of" theo cách này.)' },
  { id: 'pp-421', cat: 'phrase', q: 'After the long journey, the old car was badly ___ need of repair.', options: ['for', 'of', 'on', 'in'], correct: 3, phrase: 'in need of', vi: 'đang cần, cần đến — in need of (cần điều gì đó)', explanation: 'Cụm "in need of" bắt đầu bằng "in": in need of = đang cần. (of/for/on không mở đầu cụm cố định này.)' },
  { id: 'pp-422', cat: 'phrase', q: 'Without help, the rare species is ___ danger of becoming extinct soon.', options: ['at', 'in', 'on', 'of'], correct: 1, phrase: 'in danger of', vi: 'có nguy cơ — in danger of (đứng trước rủi ro bị/làm gì)', explanation: 'Cụm "in danger of" bắt đầu bằng "in": in danger of = có nguy cơ. (at/on/of không kết hợp với "danger of" trong cụm này.)' },
  { id: 'pp-423', cat: 'phrase', q: 'The football match was canceled ___ account of the heavy rain.', options: ['for', 'by', 'in', 'on'], correct: 3, phrase: 'on account of', vi: 'vì, do bởi — on account of (vì lý do gì đó)', explanation: 'Cụm "on account of" bắt đầu bằng "on": on account of = vì, do bởi. (by/in/for không tạo thành cụm chỉ nguyên nhân này.)' },
  { id: 'pp-424', cat: 'phrase', q: 'The company lowered its prices in response ___ growing customer complaints.', options: ['for', 'to', 'with', 'of'], correct: 1, phrase: 'in response to', vi: 'để đáp lại — in response to (phản ứng lại điều gì)', explanation: 'Cụm "in response to" luôn đi với "to": in response to something = để đáp lại điều gì. (of/for/with không dùng với cụm này.)' },
  { id: 'pp-425', cat: 'phrase', q: 'With regard ___ your application, we will contact you next week.', options: ['for', 'on', 'of', 'to'], correct: 3, phrase: 'with regard to', vi: 'liên quan đến — with regard to (về vấn đề, đối với)', explanation: 'Cụm "with regard to" dùng "to": with regard to = liên quan đến, về vấn đề gì. (of/for/on không kết hợp với cụm này.)' },
  { id: 'pp-426', cat: 'phrase', q: 'In contrast ___ his brother, Tom is very quiet and shy.', options: ['at', 'for', 'from', 'to'], correct: 3, phrase: 'in contrast to', vi: 'trái ngược với — in contrast to (khác hẳn so với)', explanation: 'Cụm "in contrast to" đi với "to": in contrast to something = trái ngược với điều gì. (with/for/from không chuẩn với "in contrast to".)' },
  { id: 'pp-427', cat: 'phrase', q: 'Our salary is quite low in comparison ___ international standards.', options: ['of', 'at', 'for', 'with'], correct: 3, phrase: 'in comparison with', vi: 'so với — in comparison with (đem ra so sánh với)', explanation: 'Cụm "in comparison with" dùng "with": in comparison with something = khi so sánh với điều gì. (of/for không dùng ở đây.)' },
  { id: 'pp-428', cat: 'phrase', q: 'The teacher explained the rules in relation ___ student behavior in class.', options: ['for', 'of', 'to', 'with'], correct: 2, phrase: 'in relation to', vi: 'liên quan đến — in relation to (xét trong mối quan hệ với)', explanation: 'Cụm "in relation to" luôn đi với "to": in relation to something = liên quan đến, xét về điều gì. (with/of/for không kết hợp.)' },
  { id: 'pp-429', cat: 'phrase', q: 'All workers must act in accordance ___ the safety regulations here.', options: ['to', 'by', 'of', 'with'], correct: 3, phrase: 'in accordance with', vi: 'theo đúng, phù hợp với — in accordance with (tuân theo quy định)', explanation: 'Cụm "in accordance with" đi với "with": in accordance with = theo đúng, phù hợp với. (to/of/by không dùng với cụm này.)' },
  { id: 'pp-430', cat: 'phrase', q: 'The new policy is in line ___ the company\'s long-term goals.', options: ['for', 'of', 'to', 'with'], correct: 3, phrase: 'in line with', vi: 'phù hợp, nhất quán với — in line with (đúng theo)', explanation: 'Cụm "in line with" dùng "with": in line with = phù hợp, nhất quán với điều gì. (to/for/of không kết hợp với cụm này.)' },
  { id: 'pp-431', cat: 'phrase', q: 'They hired her on the basis ___ her excellent interview performance.', options: ['for', 'on', 'of', 'with'], correct: 2, phrase: 'on the basis of', vi: 'dựa trên — on the basis of (căn cứ vào)', explanation: 'Cụm "on the basis of" đi với "of": on the basis of = dựa trên, căn cứ vào điều gì. (for/with/on không dùng ở đây.)' },
  { id: 'pp-432', cat: 'phrase', q: 'He built his career at the expense ___ his family relationships.', options: ['for', 'of', 'to', 'on'], correct: 1, phrase: 'at the expense of', vi: 'phải trả giá bằng — at the expense of (hy sinh điều gì)', explanation: 'Cụm "at the expense of" luôn đi với "of": at the expense of = phải trả giá bằng, hy sinh điều gì. (for/to/on không chuẩn.)' },
  { id: 'pp-433', cat: 'phrase', q: 'She spoke very quietly for fear ___ waking the sleeping baby.', options: ['of', 'with', 'to', 'from'], correct: 0, phrase: 'for fear of', vi: 'vì sợ rằng — for fear of (để tránh điều gì xảy ra)', explanation: 'Cụm "for fear of" đi với "of": for fear of = vì sợ, để tránh điều gì. (to/with/from không kết hợp với cụm này.)' },
  { id: 'pp-434', cat: 'phrase', q: 'The team stayed calm in the face ___ enormous pressure during the final.', options: ['of', 'for', 'at', 'with'], correct: 0, phrase: 'in the face of', vi: 'đối mặt với — in the face of (trước, bất chấp khó khăn)', explanation: 'Cụm "in the face of" luôn đi với "of": in the face of = đối mặt với, bất chấp điều gì. (for/at/with không dùng ở đây.)' },
  { id: 'pp-435', cat: 'phrase', q: 'In the event ___ a fire, please use the nearest emergency exit.', options: ['to', 'in', 'for', 'of'], correct: 3, phrase: 'in the event of', vi: 'trong trường hợp — in the event of (nếu xảy ra việc gì)', explanation: 'Cụm "in the event of" luôn đi với "of": in the event of = trong trường hợp (điều gì xảy ra). (for/to/in không dùng với cụm này.)' },
  { id: 'pp-436', cat: 'phrase', q: 'He gave me his old laptop in exchange ___ a few games.', options: ['with', 'of', 'to', 'for'], correct: 3, phrase: 'in exchange for', vi: 'để đổi lấy — in exchange for (trao đổi cái gì lấy cái gì)', explanation: 'Cụm "in exchange for" luôn dùng "for": in exchange for = để đổi lấy. (of/to/with không hợp với in exchange.)' },
  { id: 'pp-437', cat: 'phrase', q: 'She helped him move house in return ___ a home-cooked meal.', options: ['of', 'for', 'with', 'to'], correct: 1, phrase: 'in return for', vi: 'để đáp lại, đổi lại — in return for (nhận lại điều gì)', explanation: 'Cụm "in return for" luôn dùng "for": in return for = để đáp lại, đổi lại. (of/to/with không kết hợp với in return.)' },
  { id: 'pp-438', cat: 'phrase', q: 'After months of stress, she was on the verge ___ tears.', options: ['at', 'of', 'in', 'to'], correct: 1, phrase: 'on the verge of', vi: 'sắp sửa, bên bờ vực của — on the verge of (gần như làm gì)', explanation: 'Cụm "on the verge of" luôn đi với "of": on the verge of = sắp sửa, bên bờ vực. (to/at/in không dùng với verge.)' },
  { id: 'pp-439', cat: 'phrase', q: 'The small boat was at the mercy ___ the powerful waves.', options: ['of', 'with', 'to', 'for'], correct: 0, phrase: 'at the mercy of', vi: 'phó mặc cho, dưới sự định đoạt của — at the mercy of (không thể kiểm soát)', explanation: 'Cụm "at the mercy of" luôn dùng "of": at the mercy of = phó mặc cho, bị chi phối bởi. (for/with/to không hợp với mercy.)' },
  { id: 'pp-440', cat: 'phrase', q: 'By virtue ___ his experience, he was chosen to lead the team.', options: ['of', 'by', 'with', 'for'], correct: 0, phrase: 'by virtue of', vi: 'nhờ vào, do bởi — by virtue of (vì lý do gì)', explanation: 'Cụm "by virtue of" luôn đi với "of": by virtue of = nhờ vào, do bởi. (for/with/by không dùng với cụm này.)' },
  { id: 'pp-441', cat: 'phrase', q: 'In light ___ the new evidence, the judge reopened the case.', options: ['of', 'for', 'on', 'with'], correct: 0, phrase: 'in light of', vi: 'xét theo, dựa vào — in light of (cân nhắc đến điều gì)', explanation: 'Cụm "in light of" luôn dùng "of": in light of = xét theo, dựa vào. (with/on/for không kết hợp với cụm này.)' },
  { id: 'pp-442', cat: 'phrase', q: 'In the absence ___ the manager, the assistant ran the meeting.', options: ['from', 'to', 'for', 'of'], correct: 3, phrase: 'in the absence of', vi: 'khi vắng mặt, thiếu vắng — in the absence of (không có ai/cái gì)', explanation: 'Cụm "in the absence of" luôn đi với "of": in the absence of = khi vắng mặt, thiếu. (from/for/to không dùng với absence ở đây.)' },
  { id: 'pp-443', cat: 'phrase', q: 'She finished the report two days ahead ___ the deadline.', options: ['for', 'with', 'of', 'to'], correct: 2, phrase: 'ahead of', vi: 'trước, sớm hơn — ahead of (đi trước về thời gian/vị trí)', explanation: 'Cụm "ahead of" luôn dùng "of": ahead of = trước, sớm hơn. (to/with/for không kết hợp với ahead.)' },
  { id: 'pp-444', cat: 'phrase', q: 'Apart ___ a slight headache, I feel completely fine today.', options: ['to', 'with', 'from', 'of'], correct: 2, phrase: 'apart from', vi: 'ngoài ra, trừ — apart from (không kể đến điều gì)', explanation: 'Cụm "apart from" luôn đi với "from": apart from = ngoài ra, trừ. (of/to/with không dùng với apart.)' },
  { id: 'pp-445', cat: 'phrase', q: 'Aside ___ the cost, the plan seems perfectly reasonable to me.', options: ['from', 'to', 'of', 'for'], correct: 0, phrase: 'aside from', vi: 'ngoài ra, trừ — aside from (không tính đến điều gì)', explanation: 'Cụm "aside from" luôn dùng "from": aside from = ngoài ra, trừ. (of/to/for không kết hợp với aside.)' },
  { id: 'pp-446', cat: 'phrase', q: 'Everyone is welcome to join the club regardless ___ their age.', options: ['from', 'for', 'to', 'of'], correct: 3, phrase: 'regardless of', vi: 'bất kể, không phụ thuộc vào — regardless of (dù cho thế nào)', explanation: 'Cụm "regardless" luôn đi với "of": regardless of = bất kể điều gì. (to/for/from không kết hợp với regardless.)' },
  { id: 'pp-447', cat: 'phrase', q: '___ view of the bad weather, the match was cancelled today.', options: ['At', 'On', 'For', 'In'], correct: 3, phrase: 'in view of', vi: 'xét đến, vì lý do — in view of (do, bởi vì)', explanation: 'Cụm cố định "in view of" = xét đến, vì lý do gì. Từ đầu câu nên viết hoa "In". (On/At/For không tạo thành cụm này.)' },
  { id: 'pp-448', cat: 'phrase', q: 'He made many friends ___ the course of his long career.', options: ['on', 'in', 'by', 'at'], correct: 1, phrase: 'in the course of', vi: 'trong suốt, trong quá trình — in the course of (trong khoảng thời gian)', explanation: 'Cụm cố định "in the course of" = trong suốt, trong quá trình. (on/at/by không dùng với "the course of".)' },
  { id: 'pp-449', cat: 'phrase', q: 'Many homes were rebuilt ___ the wake of the terrible storm.', options: ['at', 'in', 'after', 'on'], correct: 1, phrase: 'in the wake of', vi: 'sau, theo sau (hậu quả của) — in the wake of (ngay sau một sự kiện)', explanation: 'Cụm cố định "in the wake of" = ngay sau / theo sau (một sự kiện). Luôn dùng "in": in the wake of the storm = sau cơn bão. (at/on/after không tạo thành cụm cố định này.)' },
  { id: 'pp-450', cat: 'phrase', q: 'The project was abandoned ___ lack of money and support.', options: ['for', 'with', 'by', 'at'], correct: 0, phrase: 'for lack of', vi: 'vì thiếu — for lack of (do không có đủ)', explanation: 'Cụm cố định "for lack of" = vì thiếu điều gì. (by/with/at không tạo thành cụm chỉ lý do này.)' },
  { id: 'pp-451', cat: 'phrase', q: 'She moved abroad ___ pursuit of a better job and life.', options: ['at', 'for', 'in', 'on'], correct: 2, phrase: 'in pursuit of', vi: 'để theo đuổi, nhằm tìm kiếm — in pursuit of (cố gắng đạt được)', explanation: 'Cụm cố định "in pursuit of" = để theo đuổi, tìm kiếm điều gì. (on/at/for không dùng với "pursuit of".)' },
  { id: 'pp-452', cat: 'phrase', q: 'Without exercise, he is ___ risk of serious heart problems.', options: ['under', 'in', 'on', 'at'], correct: 3, phrase: 'at risk of', vi: 'có nguy cơ — at risk of (đối mặt với khả năng xấu)', explanation: 'Cụm cố định "at risk of" = có nguy cơ gặp điều gì. (in/on/under không kết hợp với "risk of".)' },
  { id: 'pp-453', cat: 'phrase', q: 'Terrible crimes have been committed ___ the name of religion.', options: ['in', 'for', 'at', 'on'], correct: 0, phrase: 'in the name of', vi: 'nhân danh, vì danh nghĩa — in the name of (lấy danh nghĩa của)', explanation: 'Cụm cố định "in the name of" = nhân danh, vì danh nghĩa của. (on/at/for không tạo thành cụm này.)' },
  { id: 'pp-454', cat: 'phrase', q: 'The two countries were ___ the brink of a serious war.', options: ['in', 'over', 'on', 'at'], correct: 2, phrase: 'on the brink of', vi: 'bên bờ vực, sắp xảy ra — on the brink of (rất gần với điều gì)', explanation: 'Cụm cố định "on the brink of" = bên bờ vực, sắp xảy ra. (in/at/over không dùng với "the brink of".)' },
  { id: 'pp-455', cat: 'phrase', q: 'Trust lies ___ the heart of every successful business partnership.', options: ['by', 'at', 'in', 'on'], correct: 1, phrase: 'at the heart of', vi: 'là cốt lõi, trung tâm của — at the heart of (yếu tố quan trọng nhất)', explanation: 'Cụm cố định "at the heart of" = là cốt lõi, trung tâm của. (in/on/by không tạo thành cụm này.)' },
  { id: 'pp-456', cat: 'phrase', q: 'He gave us some flowers ___ way of an apology for being late.', options: ['as', 'for', 'by', 'in'], correct: 2, phrase: 'by way of', vi: 'như một cách, để thể hiện — by way of (nhằm mục đích)', explanation: 'Cụm cố định "by way of" = như một cách, để thể hiện điều gì. (in/as/for không dùng với "way of" theo nghĩa này.)' },
  { id: 'pp-457', cat: 'phrase', q: 'The new building was designed in keeping ___ the old town\'s style.', options: ['to', 'for', 'with', 'of'], correct: 2, phrase: 'in keeping with', vi: 'phù hợp với — in keeping with (hài hòa, đúng với phong cách)', explanation: 'Cụm "in keeping with" luôn dùng "with": in keeping with = phù hợp/hài hòa với. (to/of/for không kết hợp với cụm này.) Đây là thành ngữ cố định.' },
  { id: 'pp-458', cat: 'phrase', q: 'The festival was organized in conjunction ___ the local council this year.', options: ['of', 'to', 'by', 'with'], correct: 3, phrase: 'in conjunction with', vi: 'cùng với, kết hợp với — in conjunction with (phối hợp cùng)', explanation: 'Cụm "in conjunction with" cố định với "with": nghĩa là cùng/phối hợp với. (of/to/by không dùng trong cụm này.) Hãy nhớ như một khối.' },
  { id: 'pp-459', cat: 'phrase', q: 'Your reward will be calculated in proportion ___ the hours you work.', options: ['with', 'to', 'for', 'of'], correct: 1, phrase: 'in proportion to', vi: 'tương xứng với, theo tỉ lệ — in proportion to (cân đối theo)', explanation: 'Cụm "in proportion to" luôn đi với "to": tương xứng/theo tỉ lệ với. (with/of/for không kết hợp ở đây.) Đây là thành ngữ cố định.' },
  { id: 'pp-460', cat: 'phrase', q: 'The company reported profits in excess ___ ten million dollars last year.', options: ['to', 'over', 'of', 'than'], correct: 2, phrase: 'in excess of', vi: 'vượt quá, hơn — in excess of (nhiều hơn một con số)', explanation: 'Cụm "in excess of" cố định với "of": nghĩa là vượt quá/hơn một số lượng. (than/over/to không dùng trong cụm này.) Hãy nhớ cả khối.' },
  { id: 'pp-461', cat: 'phrase', q: 'They offered extra days off in lieu ___ a pay increase this year.', options: ['for', 'to', 'with', 'of'], correct: 3, phrase: 'in lieu of', vi: 'thay cho, thay vì — in lieu of (dùng thay thế)', explanation: 'Cụm "in lieu of" luôn đi với "of": nghĩa là thay cho/thay vì. (for/to/with không kết hợp ở đây.) Đây là thành ngữ trang trọng cố định.' },
  { id: 'pp-462', cat: 'phrase', q: 'His cold reply was completely devoid ___ any warmth or kindness.', options: ['in', 'of', 'from', 'with'], correct: 1, phrase: 'devoid of', vi: 'hoàn toàn không có, thiếu vắng — devoid of (trống rỗng, không chứa)', explanation: 'Tính từ "devoid" luôn đi với "of": devoid of = hoàn toàn không có gì. (from/in/with không dùng với devoid.) Hãy nhớ cặp cố định này.' },
  { id: 'pp-463', cat: 'phrase', q: 'They bought extra food in anticipation ___ the coming storm and lockdown.', options: ['to', 'of', 'for', 'at'], correct: 1, phrase: 'in anticipation of', vi: 'để chuẩn bị cho, lường trước — in anticipation of (đoán trước điều gì)', explanation: 'Cụm "in anticipation of" cố định với "of": nghĩa là chuẩn bị/lường trước việc gì. (for/to/at không kết hợp ở đây.) Hãy nhớ cả khối.' },
  { id: 'pp-464', cat: 'phrase', q: 'She received a medal in recognition ___ her years of devoted service.', options: ['of', 'for', 'with', 'to'], correct: 0, phrase: 'in recognition of', vi: 'để ghi nhận, công nhận — in recognition of (tôn vinh đóng góp)', explanation: 'Cụm "in recognition of" luôn đi với "of": nghĩa là để ghi nhận/công nhận điều gì. (to/for/with không dùng ở đây.) Đây là thành ngữ cố định.' },
  { id: 'pp-465', cat: 'phrase', q: 'A garden was planted in memory ___ the soldiers who died here.', options: ['about', 'to', 'of', 'for'], correct: 2, phrase: 'in memory of', vi: 'để tưởng nhớ — in memory of (ghi nhớ ai đó đã mất)', explanation: 'Cụm "in memory of" cố định với "of": nghĩa là để tưởng nhớ ai. (for/to/about không kết hợp ở đây.) Hãy nhớ cả khối.' },
  { id: 'pp-466', cat: 'phrase', q: 'The lawyer spoke passionately in defense ___ her innocent young client.', options: ['of', 'with', 'for', 'to'], correct: 0, phrase: 'in defense of', vi: 'để bảo vệ, biện hộ cho — in defense of (đứng về phía ai)', explanation: 'Cụm "in defense of" luôn đi với "of": nghĩa là để bảo vệ/biện hộ cho ai. (for/to/with không dùng ở đây.) Đây là thành ngữ cố định.' },
  { id: 'pp-467', cat: 'phrase', q: 'Thousands marched in support ___ the new environmental law last weekend.', options: ['for', 'with', 'to', 'of'], correct: 3, phrase: 'in support of', vi: 'để ủng hộ — in support of (đứng về phía, tán thành)', explanation: 'Cụm "in support of" cố định với "of": nghĩa là để ủng hộ điều gì/ai. (to/for/with không kết hợp ở đây.) Hãy nhớ cả khối.' },
  { id: 'pp-468', cat: 'phrase', q: 'Thousands marched in opposition ___ the new tax on small businesses.', options: ['of', 'with', 'to', 'for'], correct: 2, phrase: 'in opposition to', vi: 'phản đối, chống lại — in opposition to (đối lập với điều gì)', explanation: 'Cụm "in opposition to" luôn đi với "to": in opposition to something = phản đối điều gì. (of/with/for không dùng với cụm này.)' },
  { id: 'pp-469', cat: 'phrase', q: 'He finished the project on time, but ___ the cost of his health.', options: ['on', 'in', 'by', 'at'], correct: 3, phrase: 'at the cost of', vi: 'phải trả giá bằng, đánh đổi — at the cost of (mất mát điều gì)', explanation: 'Cụm cố định "at the cost of" bắt đầu bằng "at": at the cost of = phải trả giá bằng. (on/in/by không tạo thành cụm đúng.)' },
  { id: 'pp-470', cat: 'phrase', q: 'She studied hard ___ the hope of passing the final exam.', options: ['on', 'at', 'in', 'with'], correct: 2, phrase: 'in the hope of', vi: 'với hy vọng — in the hope of (mong đợi điều gì)', explanation: 'Cụm "in the hope of" luôn bắt đầu bằng "in": in the hope of doing = với hy vọng làm gì. (on/with/at không kết hợp được.)' },
  { id: 'pp-471', cat: 'phrase', q: 'Everyone enjoyed the trip, ___ the exception of two tired children.', options: ['at', 'by', 'in', 'with'], correct: 3, phrase: 'with the exception of', vi: 'ngoại trừ, trừ — with the exception of (trừ điều gì ra)', explanation: 'Cụm "with the exception of" mở đầu bằng "with": with the exception of = ngoại trừ. (by/in/at không tạo thành cụm này.)' },
  { id: 'pp-472', cat: 'phrase', q: 'The meeting ended early, ___ the interest of saving everyone\'s time.', options: ['to', 'for', 'on', 'in'], correct: 3, phrase: 'in the interest of', vi: 'vì lợi ích của — in the interest of (vì mục đích gì)', explanation: 'Cụm cố định "in the interest of" dùng "in": in the interest of = vì lợi ích của. (for/to/on không dùng ở đây.)' },
  { id: 'pp-473', cat: 'phrase', q: 'The phone rang ___ the midst of our quiet family dinner.', options: ['on', 'during', 'at', 'in'], correct: 3, phrase: 'in the midst of', vi: 'giữa lúc, ngay trong — in the midst of (đang ở giữa điều gì)', explanation: 'Cụm "in the midst of" luôn đi với "in": in the midst of = giữa lúc, ngay trong. (at/on/during không tạo thành cụm này.)' },
  { id: 'pp-474', cat: 'phrase', q: 'The young students stood ___ awe of the towering ancient cathedral.', options: ['at', 'in', 'on', 'with'], correct: 1, phrase: 'in awe of', vi: 'kinh ngạc, thán phục — in awe of (sợ kính, ngưỡng mộ điều gì)', explanation: 'Cụm "in awe of" bắt đầu bằng "in": in awe of = kinh ngạc, thán phục. (on/with/at không kết hợp với awe theo cách này.)' },
  { id: 'pp-475', cat: 'phrase', q: 'Please switch off your phone ___ to the start of the performance.', options: ['prior', 'previous', 'before', 'ahead'], correct: 0, phrase: 'prior to', vi: 'trước, trước khi — prior to (xảy ra trước điều gì)', explanation: 'Cụm trang trọng "prior to" dùng từ "prior": prior to = trước khi. (before/ahead/previous không tạo thành cụm "___ to" đúng.)' },
  { id: 'pp-476', cat: 'phrase', q: '___ to popular belief, the test was actually quite easy.', options: ['Opposite', 'Contrary', 'Against', 'Reverse'], correct: 1, phrase: 'contrary to', vi: 'trái với, ngược với — contrary to (đối nghịch với điều gì)', explanation: 'Cụm "contrary to" dùng "contrary": contrary to = trái với, ngược với. (Opposite/Against/Reverse không tạo thành cụm "___ to" chuẩn này.)' },
  { id: 'pp-477', cat: 'phrase', q: 'The match was cancelled owing ___ the heavy snow at the stadium.', options: ['to', 'of', 'for', 'with'], correct: 0, phrase: 'owing to', vi: 'do, bởi vì — owing to (nguyên nhân của điều gì)', explanation: 'Cụm "owing to" = do, bởi vì. Sau "owing" luôn là "to": owing to the snow = do tuyết. (of/for/with không theo sau "owing".)' },
  { id: 'pp-478', cat: 'phrase', q: 'The whole team finished the project early, thanks ___ her hard work.', options: ['to', 'of', 'for', 'by'], correct: 0, phrase: 'thanks to', vi: 'nhờ có, nhờ vào — thanks to (nhờ điều gì tích cực)', explanation: 'Cụm "thanks to" = nhờ có. Sau "thanks" (nghĩa này) luôn là "to": thanks to her hard work = nhờ sự chăm chỉ của cô ấy.' },
  { id: 'pp-479', cat: 'phrase', q: 'The little cafe is right next ___ the old bookstore on Main Street.', options: ['to', 'by', 'of', 'at'], correct: 0, phrase: 'next to', vi: 'bên cạnh — next to (ngay kế bên, sát cạnh)', explanation: '"Next" theo sau bởi "to" để chỉ vị trí kế bên: next to = ngay bên cạnh. (of/at/by không kết hợp với next theo nghĩa này.)' },
  { id: 'pp-480', cat: 'phrase', q: 'The flight was delayed for hours ___ to the heavy snowstorm last night.', options: ['on', 'for', 'of', 'due'], correct: 3, phrase: 'due to', vi: 'do, vì — due to (bởi nguyên nhân, lý do)', explanation: 'Cụm "due to" nghĩa là "do, vì", luôn dùng "due" trước "to". (on/of/for không tạo thành cụm chỉ nguyên nhân này.)' },
  { id: 'pp-481', cat: 'phrase', q: 'All prices listed in the catalog are subject ___ change without prior notice.', options: ['of', 'to', 'for', 'with'], correct: 1, phrase: 'subject to', vi: 'phải chịu, tùy thuộc vào — subject to (có thể bị thay đổi/áp dụng)', explanation: 'Cụm "subject to" nghĩa là "có thể bị, phải chịu", luôn đi với "to". (of/for/with không kết hợp với subject theo nghĩa này.)' },
  { id: 'pp-482', cat: 'phrase', q: 'Everyone is welcome to join the club irrespective ___ age or experience.', options: ['of', 'from', 'for', 'to'], correct: 0, phrase: 'irrespective of', vi: 'bất kể, không kể đến — irrespective of (không phụ thuộc vào)', explanation: 'Cụm "irrespective of" nghĩa là "bất kể", luôn đi với "of". (to/from/for không kết hợp với irrespective.)' },
  { id: 'pp-483', cat: 'phrase', q: 'The whole house was completely silent, save ___ the ticking of the clock.', options: ['from', 'to', 'of', 'for'], correct: 3, phrase: 'save for', vi: 'ngoại trừ — save for (trừ ra, chỉ trừ)', explanation: 'Cụm "save for" nghĩa là "ngoại trừ", dùng "for" để chỉ ngoại lệ. (of/to/from không tạo nghĩa "ngoại trừ" với save.)' },
  { id: 'pp-484', cat: 'phrase', q: 'We would have missed the train but ___ your timely phone call this morning.', options: ['with', 'to', 'of', 'for'], correct: 3, phrase: 'but for', vi: 'nếu không có, nếu không vì — but for (giả định ngược)', explanation: 'Cụm "but for" nghĩa là "nếu không có", luôn đi với "for". (of/to/with không kết hợp với but theo nghĩa giả định này.)' },
  { id: 'pp-485', cat: 'phrase', q: 'I really enjoyed the movie; as ___ the food, it was rather disappointing.', options: ['of', 'to', 'about', 'for'], correct: 3, phrase: 'as for', vi: 'còn về, về phần — as for (chuyển sang nói về điều khác)', explanation: 'Cụm "as for" nghĩa là "còn về, về phần", dùng "for" để chuyển chủ đề. (to/of/about không tạo cụm chuyển chủ đề này.)' },
  { id: 'pp-486', cat: 'phrase', q: 'Their new apartment is very near ___ the train station and the shops.', options: ['of', 'to', 'by', 'at'], correct: 1, phrase: 'near to', vi: 'gần với — near to (ở gần, sát với)', explanation: '"Near" có thể theo sau bởi "to" để chỉ khoảng cách gần: near to = ở gần. (of/at/by không kết hợp với near theo nghĩa này.)' },
  { id: 'pp-487', cat: 'phrase', q: 'The total bill comes to fifty dollars, exclusive ___ service charges and taxes.', options: ['of', 'to', 'from', 'for'], correct: 0, phrase: 'exclusive of', vi: 'không tính cả, không bao gồm — exclusive of (loại trừ ra)', explanation: 'Cụm "exclusive of" nghĩa là "không bao gồm", luôn đi với "of". (to/for/from không kết hợp với exclusive.)' },
  { id: 'pp-488', cat: 'phrase', q: 'The hotel room costs ninety pounds a night, inclusive ___ breakfast and parking.', options: ['with', 'to', 'for', 'of'], correct: 3, phrase: 'inclusive of', vi: 'bao gồm cả — inclusive of (đã tính luôn)', explanation: 'Cụm "inclusive of" nghĩa là "bao gồm cả", luôn đi với "of". (to/with/for không kết hợp với inclusive.)' },
  { id: 'pp-489', cat: 'phrase', q: 'The accident was caused by sheer carelessness on the part ___ the driver.', options: ['of', 'to', 'by', 'for'], correct: 0, phrase: 'on the part of', vi: 'về phía, do — on the part of (thuộc về ai đó)', explanation: 'Cụm "on the part of" nghĩa là "về phía ai đó", kết thúc bằng "of". (to/for/by không tạo thành cụm cố định này.)' },
  { id: 'pp-490', cat: 'phrase', q: 'Her name was written ___ the top of the list of winners.', options: ['to', 'on', 'in', 'at'], correct: 3, phrase: 'at the top of', vi: 'ở trên cùng của — at the top of (ở vị trí cao nhất)', explanation: 'Cụm "at the top of" luôn bắt đầu bằng "at": at the top of = ở trên cùng của. (on/in/to không dùng trong cụm này.)' },
  { id: 'pp-491', cat: 'phrase', q: 'You will find the answers ___ the bottom of the page.', options: ['at', 'on', 'by', 'in'], correct: 0, phrase: 'at the bottom of', vi: 'ở dưới cùng của — at the bottom of (ở vị trí thấp nhất)', explanation: 'Cụm "at the bottom of" dùng "at": at the bottom of = ở dưới cùng của. (on/in/by không kết hợp đúng ở đây.)' },
  { id: 'pp-492', cat: 'phrase', q: 'A small lamp was standing ___ the corner of the dark room.', options: ['in', 'to', 'at', 'on'], correct: 0, phrase: 'in the corner of', vi: 'ở góc của — in the corner of (trong một góc phòng)', explanation: 'Cụm "in the corner of" dùng "in": in the corner of = ở góc của (một không gian khép kín). (at/on/to không phù hợp.)' },
  { id: 'pp-493', cat: 'phrase', q: 'The old fountain stands proudly ___ the centre of the city.', options: ['on', 'at', 'in', 'of'], correct: 2, phrase: 'in the centre of', vi: 'ở trung tâm của — in the centre of (ở giữa, ở chính giữa)', explanation: 'Cụm "in the centre of" dùng "in": in the centre of = ở trung tâm của. (at/on/of không dùng trong cụm này.)' },
  { id: 'pp-494', cat: 'phrase', q: 'We parked the car ___ the side of the quiet country road.', options: ['in', 'to', 'on', 'for'], correct: 2, phrase: 'on the side of', vi: 'ở bên cạnh của — on the side of (ở phía, bên lề)', explanation: 'Cụm "on the side of" dùng "on": on the side of = ở bên/phía của. (in/at/to không kết hợp đúng ở đây.)' },
  { id: 'pp-495', cat: 'phrase', q: 'The children baked cookies ___ the shape of little yellow stars.', options: ['on', 'of', 'with', 'in'], correct: 3, phrase: 'in the shape of', vi: 'có hình dạng — in the shape of (mang hình của)', explanation: 'Cụm "in the shape of" dùng "in": in the shape of = có hình dạng của. (of/on/with không tạo thành cụm đúng.)' },
  { id: 'pp-496', cat: 'phrase', q: 'He received his bonus ___ the form of extra holiday days.', options: ['on', 'of', 'in', 'by'], correct: 2, phrase: 'in the form of', vi: 'dưới hình thức — in the form of (dưới dạng)', explanation: 'Cụm "in the form of" dùng "in": in the form of = dưới hình thức/dạng của. (of/on/by không dùng được ở đây.)' },
  { id: 'pp-497', cat: 'phrase', q: 'My grandfather is ___ the habit of reading the newspaper every morning.', options: ['on', 'at', 'in', 'with'], correct: 2, phrase: 'in the habit of', vi: 'có thói quen — in the habit of (quen làm gì)', explanation: 'Cụm "in the habit of" dùng "in": be in the habit of = có thói quen làm gì. (on/at/with không kết hợp với habit ở đây.)' },
  { id: 'pp-498', cat: 'phrase', q: 'The company is ___ the process of moving to a new office.', options: ['under', 'at', 'on', 'in'], correct: 3, phrase: 'in the process of', vi: 'đang trong quá trình — in the process of (đang tiến hành)', explanation: 'Cụm "in the process of" dùng "in": be in the process of = đang trong quá trình. (at/on/under không dùng trong cụm này.)' },
  { id: 'pp-499', cat: 'phrase', q: 'The thief was caught ___ the act of stealing the gold watch.', options: ['during', 'in', 'on', 'at'], correct: 1, phrase: 'in the act of', vi: 'đang khi làm — in the act of (ngay lúc đang thực hiện)', explanation: 'Cụm "in the act of" dùng "in": caught in the act of = bị bắt quả tang khi đang làm. (on/at/during không tạo thành cụm đúng.)' },
  { id: 'pp-500', cat: 'phrase', q: 'The little boy started crying ___ the sight of the huge dog.', options: ['in', 'by', 'at', 'on'], correct: 2, phrase: 'at the sight of', vi: 'khi nhìn thấy — at the sight of (trước cảnh tượng)', explanation: 'Cụm "at the sight of" dùng "at": at the sight of = khi/trước khi nhìn thấy. (in/on/by không kết hợp với sight ở đây.)' }
];

if (typeof module !== 'undefined' && module.exports) { module.exports = { PREPOSITION_QUESTIONS }; }
